const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, BorderStyle, ShadingType, WidthType,
  LevelFormat, PageNumber, PageBreak, Table, TableRow, TableCell
} = require('docx');
const fs = require('fs');

const questions = [
// ==================== SECTION 1: OS BASICS ====================
{ id:1, q:"What is an Operating System?", a:"An Operating System (OS) is system software that manages computer hardware and software resources and provides common services for computer programs.", exp:"The OS acts as an intermediary between users and hardware. It handles process management, memory management, file systems, and device management. Examples: Windows, Linux, macOS, Android." },
{ id:2, q:"What are the main functions of an Operating System?", a:"Process management, memory management, file system management, device management, security, and user interface.", exp:"Each function is critical: Process mgmt schedules CPU time; Memory mgmt allocates RAM; File mgmt organizes data; Device mgmt handles I/O; Security protects resources; UI allows user interaction." },
{ id:3, q:"What is the kernel?", a:"The kernel is the core part of an OS that manages system resources and allows hardware and software to communicate.", exp:"The kernel runs in privileged mode (kernel mode) and handles critical tasks like CPU scheduling, memory allocation, and device drivers. It is loaded first during boot and stays in memory throughout." },
{ id:4, q:"What is the difference between kernel mode and user mode?", a:"Kernel mode allows unrestricted access to all hardware and system instructions; user mode restricts access to protect the system.", exp:"In kernel mode, the CPU can execute all instructions and access all memory. In user mode, certain instructions are prohibited. User programs run in user mode; OS core runs in kernel mode. A mode switch (trap/interrupt) is needed to move between them." },
{ id:5, q:"What is a system call?", a:"A system call is the programmatic way a program requests a service from the operating system kernel.", exp:"When a user-space program needs OS services (e.g., file read, process creation), it issues a system call. This causes a trap to kernel mode, the OS performs the operation, and control returns to user mode. Examples: read(), write(), fork(), exec()." },
{ id:6, q:"What is multiprogramming?", a:"Multiprogramming allows multiple programs to reside in memory simultaneously so the CPU is never idle.", exp:"When one process waits for I/O, the CPU switches to another process. This improves CPU utilization. It's the foundation of modern multitasking OS design." },
{ id:7, q:"What is time-sharing (multitasking)?", a:"Time-sharing is a technique where the CPU rapidly switches between processes giving each a time slice, creating the illusion of simultaneous execution.", exp:"Each process gets a small quantum of CPU time (e.g., 10–100ms). After the quantum expires, the next process runs. This provides interactive response to users. UNIX and Windows use time-sharing." },
{ id:8, q:"What is a real-time operating system (RTOS)?", a:"An RTOS is an OS designed to process data and events within strict timing constraints (deadlines).", exp:"Used in embedded systems, medical devices, aircraft control. Two types: Hard RTOS (deadline miss = system failure), Soft RTOS (deadline miss = degraded performance). Examples: VxWorks, FreeRTOS, QNX." },
{ id:9, q:"What is a distributed operating system?", a:"A distributed OS manages a group of independent computers and makes them appear to the user as a single coherent system.", exp:"Resources are shared across a network. Examples include Amoeba and LOCUS. Advantages: resource sharing, fault tolerance, scalability. Challenges: network latency, partial failures, synchronization." },
{ id:10, q:"What is a batch operating system?", a:"A batch OS groups similar jobs together and processes them without user interaction.", exp:"Jobs are collected, batched, and executed sequentially. Used in early mainframes. No interactivity; users submit jobs and wait for results. Efficient for large repetitive tasks but poor for interactive use." },
{ id:11, q:"What is the difference between a process and a program?", a:"A program is a passive set of instructions stored on disk; a process is an active instance of a program in execution.", exp:"One program can spawn multiple processes. A process has its own memory space, program counter, registers, and resources. Running 'notepad.exe' twice creates two separate processes from one program." },
{ id:12, q:"What is a thread?", a:"A thread is the smallest unit of CPU execution within a process, sharing the process's memory and resources.", exp:"Threads within the same process share code, data, and OS resources but have their own stack, registers, and program counter. Multithreading improves concurrency. Examples: web browsers use threads for each tab." },
{ id:13, q:"What is the difference between a process and a thread?", a:"A process is an independent program in execution with its own memory space; a thread is a lightweight sub-unit within a process sharing that memory.", exp:"Process creation is expensive (separate address space); thread creation is cheap (shared memory). Processes are isolated (crash doesn't affect others); threads in the same process can corrupt shared data. IPC needed between processes; threads communicate via shared memory." },
{ id:14, q:"What are the states of a process?", a:"New, Ready, Running, Waiting (Blocked), and Terminated.", exp:"New: process being created. Ready: waiting for CPU. Running: currently executing. Waiting: waiting for I/O or event. Terminated: execution complete. Transitions are driven by scheduler decisions and I/O completion." },
{ id:15, q:"What is a Process Control Block (PCB)?", a:"A PCB is a data structure in the OS that holds all information about a process.", exp:"PCB contains: process ID, process state, program counter, CPU registers, memory limits, list of open files, scheduling info, and I/O status. It is created when a process starts and deleted when it terminates." },
{ id:16, q:"What is context switching?", a:"Context switching is the process of saving the state of a running process and loading the state of another process.", exp:"When the OS switches the CPU from one process to another, it saves the PCB of the current process and loads the PCB of the next. This incurs overhead (pure overhead — no useful work done). Frequent context switches reduce throughput." },
{ id:17, q:"What is a scheduler?", a:"A scheduler is an OS component that decides which process runs next on the CPU.", exp:"Three types: Long-term (job scheduler) — decides which jobs enter the ready queue. Short-term (CPU scheduler) — picks which ready process gets the CPU. Medium-term (swapper) — decides which processes to swap in/out of memory." },
{ id:18, q:"What is the difference between preemptive and non-preemptive scheduling?", a:"Preemptive scheduling can forcibly remove a running process from the CPU; non-preemptive scheduling waits until the process voluntarily releases the CPU.", exp:"Preemptive: OS can interrupt a running process (e.g., when a higher-priority process arrives or time quantum expires). Non-preemptive: process runs until it blocks or exits. Preemptive is more responsive but requires careful synchronization." },
{ id:19, q:"What is FCFS scheduling?", a:"First-Come First-Served (FCFS) is a non-preemptive scheduling algorithm where processes are executed in the order they arrive.", exp:"Simple to implement using a queue. Suffers from the convoy effect — short processes wait behind long ones. Average waiting time can be high. Not suitable for interactive systems." },
{ id:20, q:"What is SJF scheduling?", a:"Shortest Job First (SJF) selects the process with the smallest next CPU burst for execution.", exp:"Provably optimal for minimizing average waiting time. Problem: requires knowing future burst times (not practical). Can cause starvation of long processes. Preemptive version is called SRTF (Shortest Remaining Time First)." },
{ id:21, q:"What is Round Robin scheduling?", a:"Round Robin assigns each process a fixed time quantum and cycles through all ready processes in order.", exp:"Preemptive and fair. Works well for time-sharing systems. Performance depends on quantum size: too small → high context-switch overhead; too large → degenerates to FCFS. Typical quantum: 10–100ms." },
{ id:22, q:"What is Priority Scheduling?", a:"Priority Scheduling assigns each process a priority and the CPU is given to the highest-priority process.", exp:"Can be preemptive or non-preemptive. Lower-priority processes may starve. Solution: Aging — gradually increasing priority of waiting processes. Used in real-time systems." },
{ id:23, q:"What is the Multilevel Queue Scheduling?", a:"It divides the ready queue into multiple separate queues, each with its own scheduling algorithm, based on process properties.", exp:"Processes are permanently assigned to a queue (e.g., foreground vs background). Each queue has a priority and scheduling policy. The CPU is allocated to queues by priority. Cannot move processes between queues." },
{ id:24, q:"What is Multilevel Feedback Queue (MLFQ) scheduling?", a:"MLFQ allows processes to move between queues based on their CPU burst behavior, combining responsiveness with efficiency.", exp:"New processes start in the highest-priority queue. If they use their full quantum, they drop to a lower queue. Short CPU bursts stay in high-priority queues. Aging prevents starvation. Most modern OS schedulers use a variant of MLFQ." },
{ id:25, q:"What is CPU utilization?", a:"CPU utilization is the percentage of time the CPU is busy executing processes rather than being idle.", exp:"Goal is to keep CPU utilization as high as possible (typically 40–90%). Idle time wastes resources. Multiprogramming increases CPU utilization by running other processes when one is waiting for I/O." },

// ==================== SECTION 2: PROCESS SYNCHRONIZATION ====================
{ id:26, q:"What is the critical section problem?", a:"The critical section problem ensures that when one process executes in its critical section (shared resource), no other process can enter its critical section.", exp:"Requirements: Mutual Exclusion, Progress (no process should block others from entering if critical section is free), Bounded Waiting (limited waiting time). Solutions include Peterson's algorithm, semaphores, and monitors." },
{ id:27, q:"What is a race condition?", a:"A race condition occurs when the output of a system depends on the sequence or timing of uncontrollable events like thread execution order.", exp:"Example: Two threads both read a counter (value 5), both increment it, both write back 6 — but the correct answer is 7. Race conditions lead to inconsistent data and hard-to-reproduce bugs." },
{ id:28, q:"What is mutual exclusion?", a:"Mutual exclusion ensures that only one process at a time can be in the critical section accessing shared resources.", exp:"It prevents race conditions. Achieved through locks, semaphores, and monitors. Key requirement: if one process is in the critical section, no other should be allowed to enter." },
{ id:29, q:"What is a semaphore?", a:"A semaphore is an integer variable used for process synchronization, accessed only through two atomic operations: wait (P) and signal (V).", exp:"wait(S): if S>0, decrement S; else block the process. signal(S): increment S; if processes are waiting, wake one. Binary semaphore (mutex): values 0 or 1. Counting semaphore: any non-negative value. Used to manage access to resources." },
{ id:30, q:"What is a mutex?", a:"A mutex (mutual exclusion lock) is a binary semaphore that allows only one thread to access a resource at a time.", exp:"A thread acquires (locks) the mutex before entering the critical section and releases (unlocks) it on exit. If the mutex is already locked, the requesting thread blocks. Unlike binary semaphores, mutexes have ownership — only the locking thread can unlock." },
{ id:31, q:"What is a monitor?", a:"A monitor is a high-level synchronization construct that encapsulates shared variables, procedures, and synchronization into one module.", exp:"Only one process can be active inside a monitor at a time. Monitors use condition variables (wait/signal) for coordination. Easier to use correctly than semaphores. Java's synchronized methods implement monitors." },
{ id:32, q:"What is a deadlock?", a:"Deadlock is a situation where a set of processes are permanently blocked because each process is waiting for a resource held by another process in the set.", exp:"Classic example: Process A holds R1, wants R2; Process B holds R2, wants R1. Neither can proceed. Deadlock requires four conditions to hold simultaneously: mutual exclusion, hold and wait, no preemption, circular wait." },
{ id:33, q:"What are the four necessary conditions for deadlock (Coffman conditions)?", a:"Mutual Exclusion, Hold and Wait, No Preemption, and Circular Wait.", exp:"1) Mutual Exclusion: resources are non-shareable. 2) Hold & Wait: process holds a resource and waits for more. 3) No Preemption: resources cannot be forcibly taken. 4) Circular Wait: a circular chain of processes each waiting for the next. ALL four must hold for deadlock to occur." },
{ id:34, q:"What is deadlock prevention?", a:"Deadlock prevention eliminates one of the four Coffman conditions to ensure deadlock cannot occur.", exp:"Methods: Eliminate Hold&Wait (request all resources at once). Allow Preemption (forcibly take resources). Eliminate Circular Wait (impose ordering on resource types). These methods are conservative and may reduce resource utilization." },
{ id:35, q:"What is deadlock avoidance?", a:"Deadlock avoidance uses knowledge of future resource requests to ensure the system never enters an unsafe state.", exp:"The Banker's Algorithm is the classic deadlock avoidance algorithm. The system keeps track of available resources and simulates granting requests — only granting if the resulting state is safe (a safe sequence exists)." },
{ id:36, q:"What is the Banker's Algorithm?", a:"The Banker's Algorithm is a resource allocation and deadlock avoidance algorithm that tests for safe state before granting resources.", exp:"It simulates allocation of all possible resources and checks if all processes can still complete. A 'safe sequence' exists if each process can be satisfied by available + resources released by preceding processes. If no safe sequence exists, the state is unsafe." },
{ id:37, q:"What is deadlock detection and recovery?", a:"Deadlock detection finds existing deadlocks; recovery breaks them by aborting processes or preempting resources.", exp:"Detection: use a resource allocation graph or wait-for graph; look for cycles. Recovery methods: 1) Process termination (abort all or one at a time). 2) Resource preemption (take resources from processes). Recovery can cause starvation if same process always chosen." },
{ id:38, q:"What is a resource allocation graph (RAG)?", a:"A RAG is a directed graph used to describe deadlocks, with vertices representing processes and resources, and edges representing requests/assignments.", exp:"Request edge: P→R (process wants resource). Assignment edge: R→P (resource assigned to process). If graph has no cycle, no deadlock. If cycle exists and each resource has one instance, deadlock guaranteed. Multiple instances require further analysis." },
{ id:39, q:"What is starvation?", a:"Starvation is a situation where a process is indefinitely denied necessary resources, typically because higher-priority processes keep getting scheduled.", exp:"Differs from deadlock: in starvation, resources are available but not allocated to the waiting process. Common in priority scheduling. Solution: Aging (gradually increasing priority of waiting processes)." },
{ id:40, q:"What is livelock?", a:"Livelock is a situation where processes keep changing state in response to each other without making progress.", exp:"Like two people in a corridor both stepping aside in the same direction repeatedly. Unlike deadlock (processes are blocked), livelocked processes are active but not progressing. Example: collision avoidance in networking protocols." },
{ id:41, q:"What is Peterson's solution?", a:"Peterson's solution is a software-based algorithm providing mutual exclusion for two processes using shared variables 'flag' and 'turn'.", exp:"Each process sets its flag[i]=true (wants to enter) and turn=j (gives priority to other). It waits while flag[j]==true AND turn==j. Satisfies all three requirements: mutual exclusion, progress, bounded waiting. Not practical for hardware with modern CPU optimizations." },
{ id:42, q:"What is the producer-consumer problem?", a:"A classic synchronization problem where a producer generates data and a consumer uses it via a shared bounded buffer.", exp:"Producer must not add to a full buffer; consumer must not remove from an empty buffer. Solution uses semaphores: empty (initialized to N), full (initialized to 0), and mutex (initialized to 1). Demonstrates semaphore use for synchronization." },
{ id:43, q:"What is the readers-writers problem?", a:"A synchronization problem where multiple readers can read simultaneously, but writers need exclusive access.", exp:"First readers-writers: readers have priority — writer may starve. Second: writers have priority — readers may starve. Solution uses semaphores or read-write locks. Real-world relevance: database systems." },
{ id:44, q:"What is the dining philosophers problem?", a:"Five philosophers sit at a table; each needs two forks to eat but only one fork is between each pair — a classic synchronization and deadlock problem.", exp:"Naive solution: each picks left fork, then right → deadlock. Solutions: allow only 4 philosophers to sit at once, use an arbitrator, or odd philosophers pick left first while even pick right first. Demonstrates deadlock avoidance." },
{ id:45, q:"What is spinlock?", a:"A spinlock is a lock where the thread repeatedly checks (spins) until the lock becomes available, without sleeping.", exp:"Advantage: no context switch overhead, so efficient for short waits. Disadvantage: wastes CPU cycles (busy waiting) for longer waits. Used in OS kernel code on multiprocessors where wait times are very short." },

// ==================== SECTION 3: MEMORY MANAGEMENT ====================
{ id:46, q:"What is memory management?", a:"Memory management is the OS function of controlling and coordinating computer memory, allocating portions to processes and freeing it when no longer needed.", exp:"Goals: maximize memory utilization, provide isolation between processes, support virtual memory. Techniques: partitioning, paging, segmentation, virtual memory." },
{ id:47, q:"What is logical (virtual) address vs physical address?", a:"A logical address is generated by the CPU and refers to a location in the process's virtual address space; a physical address is the actual location in RAM.", exp:"The Memory Management Unit (MMU) translates logical to physical addresses at runtime. This abstraction allows processes to have contiguous virtual address spaces even when physical memory is fragmented." },
{ id:48, q:"What is memory partitioning?", a:"Memory partitioning divides RAM into fixed or variable sections to allocate to processes.", exp:"Fixed partitioning: equal or unequal fixed-size partitions. Leads to internal fragmentation. Variable partitioning: partitions created dynamically to fit each process. Leads to external fragmentation. Compaction can reduce external fragmentation." },
{ id:49, q:"What is fragmentation?", a:"Fragmentation is wasted memory space. Internal fragmentation is unused space inside allocated memory; external fragmentation is free space scattered outside allocated blocks.", exp:"Internal: process allocated more than it needs (fixed partitions). External: total free memory is sufficient but not contiguous (variable partitions). Solutions: paging eliminates external fragmentation; compaction reduces it for variable partitioning." },
{ id:50, q:"What is paging?", a:"Paging divides physical memory into fixed-size frames and logical memory into same-size pages, eliminating external fragmentation.", exp:"Page size = frame size (typically 4KB). The OS maintains a page table mapping page numbers to frame numbers. When a process accesses a logical address, the MMU looks up the frame in the page table. Eliminates external fragmentation but causes internal fragmentation (last page may not be full)." },
{ id:51, q:"What is a page table?", a:"A page table is a data structure that maps virtual page numbers to physical frame numbers.", exp:"Each process has its own page table. The page table is stored in memory and its base address stored in the Page Table Base Register (PTBR). Accessing a page requires two memory accesses: one for page table, one for data. TLB caches recent translations." },
{ id:52, q:"What is TLB (Translation Lookaside Buffer)?", a:"A TLB is a high-speed hardware cache that stores recent virtual-to-physical address translations to speed up paging.", exp:"On a memory access, the MMU first checks the TLB (TLB hit = fast). If not found (TLB miss), the page table is consulted and the translation is loaded into the TLB. Effective Access Time (EAT) = hit_rate × (TLB access + memory) + miss_rate × (TLB access + 2 × memory)." },
{ id:53, q:"What is segmentation?", a:"Segmentation divides memory into variable-sized logical segments corresponding to program components (code, stack, heap, data).", exp:"Each segment has a base address and a limit. The OS maintains a segment table. Unlike paging (physical division), segmentation follows the logical structure of the program. Can cause external fragmentation. Often combined with paging." },
{ id:54, q:"What is virtual memory?", a:"Virtual memory allows a process to execute even if it is not completely in physical memory, using disk as an extension of RAM.", exp:"Only the needed parts (pages) are loaded into memory. The rest reside on disk (swap space). Allows processes larger than physical memory. Implemented using demand paging. Benefits: larger address space, process isolation, efficient memory use." },
{ id:55, q:"What is demand paging?", a:"Demand paging loads pages into memory only when they are needed (on demand), rather than loading the entire process.", exp:"A page fault occurs when the CPU accesses a page not in memory. The OS handles it: suspends the process, finds a free frame, loads the page from disk, updates the page table, and resumes the process. Minimizes memory usage." },
{ id:56, q:"What is a page fault?", a:"A page fault occurs when a process accesses a virtual page that is not currently loaded in physical memory.", exp:"Steps: 1) CPU accesses address, MMU detects page not present (valid bit=0). 2) Trap to OS. 3) OS checks if address is valid. 4) OS finds free frame. 5) OS loads page from disk. 6) Update page table. 7) Restart the faulting instruction. Page faults are expensive — disk access takes milliseconds." },
{ id:57, q:"What is page replacement?", a:"Page replacement selects a victim page to swap out when a page fault occurs and no free frames are available.", exp:"The OS must choose which page to evict. Goal: minimize future page faults. Key algorithms: FIFO, LRU, Optimal (OPT), LRU Approximation (Clock algorithm). The replaced page is written to disk if it was modified (dirty bit set)." },
{ id:58, q:"What is FIFO page replacement?", a:"FIFO replaces the page that has been in memory the longest.", exp:"Simple to implement using a queue. Suffers from Belady's Anomaly: adding more frames can increase page faults. Not optimal because oldest page may be heavily used. Example: page string 1,2,3,4,1,2,5,1,2,3,4,5 with 3 frames gives 9 faults." },
{ id:59, q:"What is LRU page replacement?", a:"Least Recently Used (LRU) replaces the page that has not been used for the longest time.", exp:"Based on temporal locality: recently used pages likely to be used again. Optimal in theory but expensive to implement (needs tracking usage time of each page). Approximated by the Clock algorithm or reference bits." },
{ id:60, q:"What is the Optimal (OPT) page replacement algorithm?", a:"OPT replaces the page that will not be used for the longest time in the future.", exp:"Guarantees minimum page faults. Impossible to implement in practice (requires future knowledge). Used as a benchmark to evaluate other algorithms. For the page string 7,0,1,2,0,3,0,4,2,3,0,3,2 with 3 frames, OPT gives 9 faults." },
{ id:61, q:"What is Belady's Anomaly?", a:"Belady's Anomaly is the phenomenon where increasing the number of page frames can increase the number of page faults for the FIFO algorithm.", exp:"Counter-intuitive: more memory → more faults. Happens because FIFO doesn't consider recency or frequency. LRU and OPT do NOT suffer from Belady's Anomaly. Algorithms that do not suffer from it are called stack algorithms." },
{ id:62, q:"What is thrashing?", a:"Thrashing occurs when a process spends more time paging (swapping pages in and out) than executing.", exp:"Happens when a process doesn't have enough frames for its working set. The CPU becomes idle while waiting for pages; the OS loads more processes, worsening the situation. Solutions: Working Set Model, Page Fault Frequency (PFF) based allocation." },
{ id:63, q:"What is the Working Set Model?", a:"The Working Set Model is a strategy that tracks the set of pages a process has used in the last Δ time units (the working set window) and ensures all these pages are in memory.", exp:"Working set size varies over time. If sum of all working sets > available frames, suspend a process. Prevents thrashing by ensuring each process has enough frames. Δ is the working set window parameter." },
{ id:64, q:"What is memory compaction?", a:"Compaction relocates processes in memory to consolidate free space into one large contiguous block.", exp:"Solves external fragmentation in variable partitioning. Requires relocatable addresses (dynamic relocation). Expensive operation — all processes must be paused and relocated. Not applicable to paged systems (already handle fragmentation)." },
{ id:65, q:"What is swapping?", a:"Swapping is the process of moving an entire process from main memory to disk (swap space) and back to free up RAM.", exp:"Medium-term scheduler decides which process to swap. Allows more processes than physical memory can hold. High overhead due to disk I/O. Modern systems use page-level swapping (paging) rather than whole-process swapping." },

// ==================== SECTION 4: FILE SYSTEMS ====================
{ id:66, q:"What is a file system?", a:"A file system is the OS component that manages how data is stored, organized, retrieved, and named on storage devices.", exp:"Provides abstraction over physical storage. Manages files, directories, metadata, and access control. Examples: FAT32, NTFS, ext4, HFS+. A file system defines directory structure, naming rules, metadata, and methods for allocating space." },
{ id:67, q:"What is a file?", a:"A file is a named collection of related information stored on secondary storage.", exp:"Files have attributes: name, type, size, location, creation/modification time, permissions, owner. The OS provides file operations: create, delete, open, close, read, write, seek, get/set attributes." },
{ id:68, q:"What is a directory?", a:"A directory is a container that organizes files and other directories, providing a hierarchical namespace.", exp:"Types: Single-level directory (all files in one directory), Two-level (separate per user), Tree-structured (most common — hierarchical), Acyclic Graph (allows sharing via links), General Graph (can have cycles — needs garbage collection)." },
{ id:69, q:"What is an inode?", a:"An inode (index node) is a data structure in Unix/Linux file systems that stores metadata about a file and pointers to its data blocks.", exp:"Inode stores: file size, owner, permissions, timestamps, link count, and block pointers (direct, single-indirect, double-indirect, triple-indirect). The inode number, not the filename, uniquely identifies a file. Multiple filenames (hard links) can point to the same inode." },
{ id:70, q:"What is file allocation?", a:"File allocation refers to how disk blocks are assigned to files.", exp:"Three main methods: 1) Contiguous — all blocks in a row (fast access, external fragmentation). 2) Linked — blocks scattered, each points to next (no fragmentation, slow random access). 3) Indexed — an index block holds all block pointers (fast random access, overhead)." },
{ id:71, q:"What is contiguous allocation?", a:"Contiguous allocation assigns consecutive disk blocks to a file.", exp:"Advantages: simple, fast sequential and random access. Disadvantages: external fragmentation, need to know file size in advance, difficult to grow files. Used in some CD-ROM file systems." },
{ id:72, q:"What is linked allocation?", a:"Linked allocation stores files in scattered blocks, each containing a pointer to the next block.", exp:"Advantages: no external fragmentation, files can grow easily. Disadvantages: slow random access (must traverse chain), pointer overhead per block, reliability (lost pointer = lost data). FAT uses a table version of linked allocation." },
{ id:73, q:"What is indexed allocation?", a:"Indexed allocation uses a special index block for each file that contains pointers to all of the file's data blocks.", exp:"Advantages: fast random access, no external fragmentation. Disadvantages: index block overhead, file size limited by index block size. UNIX inodes use a multi-level indexed structure for large files." },
{ id:74, q:"What is the FAT file system?", a:"File Allocation Table (FAT) is a simple file system using a table to link disk clusters belonging to each file.", exp:"FAT12/FAT16/FAT32 differ in address size. The FAT table maps cluster number to next cluster (or EOF/bad cluster). Simple and widely compatible. FAT32 max file size: 4GB. No journaling, limited security features." },
{ id:75, q:"What is NTFS?", a:"New Technology File System (NTFS) is Microsoft's advanced file system for Windows, supporting large files, security, compression, encryption, and journaling.", exp:"Uses Master File Table (MFT) — stores all file metadata. Supports ACLs for security, transparent compression/encryption, alternate data streams, and journaling for crash recovery. Max file size: 16TB." },
{ id:76, q:"What is ext4?", a:"ext4 (Fourth Extended Filesystem) is the default Linux file system with journaling, large volume support, and improved performance over ext3.", exp:"Supports volumes up to 1EB, files up to 16TB. Uses extents (contiguous block ranges) for efficiency. Has journaling (metadata + data), delayed allocation, and multiblock allocation. Backward compatible with ext3." },
{ id:77, q:"What is journaling in a file system?", a:"Journaling records changes to the file system in a log (journal) before committing them, ensuring consistency after crashes.", exp:"If a crash occurs mid-write, the OS can replay or undo the journal to restore consistency. Three modes: writeback (metadata only, fastest), ordered (metadata after data, default in ext3/4), data (both metadata and data journaled, safest but slowest)." },
{ id:78, q:"What is a hard link?", a:"A hard link is a directory entry that associates a filename directly with an inode, creating multiple names for the same file.", exp:"Deleting one hard link doesn't remove the file (inode persists until link count reaches 0). All hard links are equal. Cannot cross file systems or link to directories (usually). Hard links share same inode number." },
{ id:79, q:"What is a symbolic (soft) link?", a:"A symbolic link is a special file containing a path to another file or directory.", exp:"Unlike hard links, symlinks can cross file systems and point to directories. If the target is deleted, the symlink becomes dangling (broken). Symlinks have their own inode. Similar to shortcuts in Windows." },
{ id:80, q:"What are file permissions in Unix/Linux?", a:"Unix file permissions define read (r), write (w), and execute (x) rights for owner, group, and others.", exp:"Represented as 9 bits: rwxrwxrwx. Octal: chmod 755 = rwxr-xr-x. Special bits: setuid (run as owner), setgid (run as group), sticky bit (only owner can delete in shared directories). Managed with chmod, chown, chgrp." },
{ id:81, q:"What is a mount point?", a:"A mount point is a directory in the file system where an additional file system is attached (mounted).", exp:"In Linux, storage devices are mounted at directories (e.g., /mnt/usb). The mounted file system's root appears as that directory. The original directory contents are hidden until the device is unmounted. /etc/fstab defines automatic mounts." },
{ id:82, q:"What is disk scheduling?", a:"Disk scheduling algorithms decide the order in which disk I/O requests are serviced to optimize seek time and throughput.", exp:"Algorithms: FCFS (simple, poor performance), SSTF (shortest seek time first, may starve), SCAN/Elevator (sweeps back and forth), C-SCAN (circular SCAN), C-LOOK (only goes to last request). SCAN/C-SCAN provide more uniform service times." },
{ id:83, q:"What is RAID?", a:"Redundant Array of Independent Disks (RAID) combines multiple disk drives for redundancy, performance, or both.", exp:"RAID 0: striping (performance, no redundancy). RAID 1: mirroring (full redundancy, 50% capacity). RAID 5: striping with distributed parity (good performance + single-disk fault tolerance). RAID 6: double parity (two disk faults). RAID 10: mirror+stripe." },
{ id:84, q:"What is a buffer cache?", a:"A buffer cache is a region of memory used by the OS to cache disk blocks, reducing I/O operations.", exp:"When a file is read, its blocks are cached. Future reads serve from cache (much faster). Write-through: writes go to disk immediately. Write-back: writes to cache, flushed to disk periodically. The 'dirty' flag marks modified blocks." },
{ id:85, q:"What is the Virtual File System (VFS)?", a:"VFS is an abstraction layer in the OS that provides a uniform interface to different file system types.", exp:"Applications call standard file operations (open, read, write). VFS translates these to the specific file system's operations (ext4, FAT, NFS, etc.). Allows mounting multiple file systems simultaneously in a unified namespace." },

// ==================== SECTION 5: I/O MANAGEMENT ====================
{ id:86, q:"What is I/O management?", a:"I/O management is the OS function of controlling all input/output operations between the computer and peripheral devices.", exp:"The OS provides device drivers, handles interrupts, buffers data, manages device queues, and presents a uniform device interface. Goals: efficiency, generality, and device independence." },
{ id:87, q:"What is a device driver?", a:"A device driver is software that provides an interface between the OS and a hardware device.", exp:"Drivers translate OS commands (read/write) into device-specific commands. Each device has its own driver. Drivers run in kernel mode for performance and hardware access. Bad drivers are a leading cause of OS crashes." },
{ id:88, q:"What is DMA (Direct Memory Access)?", a:"DMA allows hardware devices to transfer data directly to/from memory without CPU involvement.", exp:"Without DMA, the CPU must supervise every byte transfer (programmed I/O). With DMA: CPU sets up DMA controller (source, destination, count), DMA transfers data, then raises an interrupt when done. Frees CPU for other work during large transfers." },
{ id:89, q:"What is an interrupt?", a:"An interrupt is a signal to the CPU from hardware or software indicating that an event needs immediate attention.", exp:"Hardware interrupts: from devices (disk ready, keyboard press). Software interrupts (traps): from processes (system calls, exceptions). Interrupt handling: save CPU state, jump to interrupt handler (ISR), handle event, restore state, resume. Enables asynchronous I/O." },
{ id:90, q:"What is polling vs interrupt-driven I/O?", a:"Polling continuously checks device status (busy waiting); interrupt-driven I/O lets the device notify the CPU when it's ready.", exp:"Polling wastes CPU cycles but has lower latency for fast devices. Interrupts free the CPU for other work but have overhead (saving/restoring state). DMA + interrupts used for large data transfers. Polling used in RTOS for predictability." },
{ id:91, q:"What is buffering in I/O?", a:"Buffering uses temporary storage (buffer) to hold data in transit between I/O devices and applications.", exp:"Reasons: speed mismatch (disk vs CPU), different data sizes (byte vs block). Types: single buffer, double buffer (producer/consumer can work simultaneously), circular buffer. The OS kernel maintains I/O buffers." },
{ id:92, q:"What is spooling?", a:"Spooling (Simultaneous Peripheral Operations Online) queues jobs for devices that cannot handle simultaneous requests, such as printers.", exp:"Jobs sent to the printer are stored in a spool (disk queue). The print daemon serves them one at a time. Multiple users can 'print' simultaneously (jobs queued). Allows overlapping of I/O with computation." },
{ id:93, q:"What is a block device vs character device?", a:"Block devices (disks) transfer data in fixed-size blocks and support random access; character devices (keyboards, serial ports) transfer data byte by byte sequentially.", exp:"Block devices: disk, SSD, USB drives — accessed via buffer cache. Character devices: keyboard, mouse, terminal — accessed directly byte-by-byte. Network devices form a third category (packet-oriented)." },
{ id:94, q:"What is memory-mapped I/O?", a:"Memory-mapped I/O maps device registers into the processor's address space so that the CPU reads/writes devices using normal memory instructions.", exp:"No special I/O instructions needed. Device registers appear as memory locations. CPU reads/writes these locations to control devices. Used widely in modern architectures. Alternative: port-mapped I/O uses separate I/O address space (IN/OUT instructions on x86)." },
{ id:95, q:"What is I/O scheduling?", a:"I/O scheduling determines the order in which I/O requests are processed to optimize throughput and minimize latency.", exp:"For disk I/O, scheduling reduces seek time (mechanical movement). Algorithms: SSTF (greedy seek time minimization), SCAN/Elevator (sweeps). For SSDs, seek time is negligible so simpler scheduling or FIFO suffices." },

// ==================== SECTION 6: STORAGE MANAGEMENT ====================
{ id:96, q:"What is secondary storage?", a:"Secondary storage is non-volatile, persistent storage such as hard disk drives (HDD) and solid-state drives (SSD) used to store data permanently.", exp:"Unlike RAM (volatile, fast, expensive), secondary storage retains data without power. Slower than RAM but orders of magnitude cheaper per bit. The OS manages secondary storage through file systems and disk management." },
{ id:97, q:"What is the structure of a hard disk drive (HDD)?", a:"An HDD consists of platters, read/write heads, tracks, sectors, and cylinders.", exp:"Platters: rotating magnetic disks. Tracks: concentric circles on each platter. Sectors: smallest addressable unit (512B or 4KB). Cylinders: same track on all platters. Seek time: moving head to track. Rotational latency: waiting for sector to rotate under head. Transfer time: actual data transfer." },
{ id:98, q:"What is an SSD?", a:"A Solid-State Drive (SSD) uses flash memory (NAND) chips to store data with no moving parts.", exp:"Much faster than HDD (no seek time or rotational latency). More durable, silent, lower power. Expensive per GB. Limited write cycles (wear leveling extends life). Uses FTL (Flash Translation Layer) to manage block-level writes. NVMe SSDs use PCIe for even higher speed." },
{ id:99, q:"What is disk formatting?", a:"Disk formatting divides the disk into sectors and tracks and prepares it for use by a file system.", exp:"Low-level formatting: physical structure (sectors, headers). Partition: divide disk into logical units. High-level formatting: create file system structures (boot block, free space management, root directory). Must be done before installing an OS or creating partitions." },
{ id:100, q:"What is a partition?", a:"A partition is a logical division of a physical disk that the OS treats as a separate storage unit.", exp:"Allows multiple OS installations, file system types, or storage pools on one disk. Managed by partition table (MBR: up to 4 primary, GPT: up to 128). Each partition can have its own file system. Linux partitions: /dev/sda1, /dev/sda2, etc." },

// ==================== SECTION 7: SECURITY ====================
{ id:101, q:"What is OS security?", a:"OS security protects system resources, data, and users from unauthorized access, modification, or disruption.", exp:"Covers authentication, authorization, access control, encryption, auditing, and secure communication. Security mechanisms include user authentication, file permissions, process isolation, and network firewalls." },
{ id:102, q:"What is authentication?", a:"Authentication verifies the identity of a user or process attempting to access the system.", exp:"Methods: Something you know (password, PIN), Something you have (smart card, token), Something you are (biometrics — fingerprint, iris). Multi-factor authentication (MFA) combines two or more. The OS stores password hashes, not plain text." },
{ id:103, q:"What is authorization?", a:"Authorization determines what an authenticated user or process is permitted to do.", exp:"After authentication proves WHO you are, authorization decides WHAT you can do. Implemented through access control lists (ACLs), capability lists, and role-based access control (RBAC). The principle of least privilege: grant minimum permissions needed." },
{ id:104, q:"What is an Access Control List (ACL)?", a:"An ACL is a list associated with a resource that specifies which users or processes have which permissions on that resource.", exp:"Example: file ACL might list: Alice:read/write, Bob:read, Others:none. OS checks ACL on each access. More flexible than Unix permissions (which only have owner/group/others). Windows NTFS uses ACLs extensively." },
{ id:105, q:"What is the principle of least privilege?", a:"The principle of least privilege states that a subject should have only the minimum permissions necessary to perform its task.", exp:"Reduces attack surface: a compromised process with limited privileges can do less damage. Applied to users, processes, and services. Example: a web server should not run as root. Sudo in Linux grants temporary elevated privileges rather than always running as root." },
{ id:106, q:"What is a virus?", a:"A virus is malicious code that attaches itself to legitimate programs and replicates when executed, potentially causing damage.", exp:"Unlike worms, viruses need a host program and user action to spread. Types: file virus, boot sector virus, macro virus. Prevention: antivirus software, OS updates, and not executing untrusted code." },
{ id:107, q:"What is a worm?", a:"A worm is self-replicating malware that spreads across networks without user interaction or a host program.", exp:"Exploits network vulnerabilities to copy itself. Can consume bandwidth and system resources. Examples: Morris Worm (1988), WannaCry (2017). Prevention: patching, firewalls, network monitoring." },
{ id:108, q:"What is a Trojan horse?", a:"A Trojan horse is malware disguised as legitimate software that performs malicious actions when executed.", exp:"Unlike viruses/worms, Trojans don't self-replicate. They trick users into running them. Common payloads: backdoors, keyloggers, ransomware droppers. Prevention: download from trusted sources, verify signatures." },
{ id:109, q:"What is a buffer overflow attack?", a:"A buffer overflow attack writes data beyond a buffer's boundary, overwriting adjacent memory including return addresses to hijack control flow.", exp:"Attacker overflows a stack buffer to overwrite the return address with a pointer to malicious code (shellcode). Defenses: stack canaries, ASLR (Address Space Layout Randomization), DEP/NX (non-executable stack), safe library functions." },
{ id:110, q:"What is ASLR?", a:"Address Space Layout Randomization (ASLR) randomizes the memory addresses used by a process to make exploit development harder.", exp:"Without ASLR, exploit writers know where the stack, heap, and libraries are. With ASLR, addresses change each run. Makes buffer overflow exploits unreliable. Combined with DEP (prevents code execution in data regions) provides strong protection." },

// ==================== SECTION 8: LINUX/UNIX SPECIFICS ====================
{ id:111, q:"What is the Unix philosophy?", a:"The Unix philosophy: write programs that do one thing well, write programs that work together, write programs that handle text streams.", exp:"Coined by Doug McIlroy. Encourages simplicity, modularity, and composability. Programs communicate via pipes (|). Contrasts with monolithic applications. This philosophy influenced Linux, macOS, and modern DevOps tooling." },
{ id:112, q:"What is a Unix process hierarchy?", a:"In Unix, all processes form a tree rooted at 'init' (PID 1), with each process (except init) having exactly one parent.", exp:"init/systemd starts all system services. Parents create children via fork(). When a child dies before its parent reaps it, it becomes a zombie. When parent dies first, child is adopted by init. PID 1 periodically reaps orphaned zombie processes." },
{ id:113, q:"What is fork() system call?", a:"fork() creates a new process (child) as an exact copy of the calling process (parent).", exp:"After fork(): both processes continue from the same point. Child gets PID 0 return; parent gets child's PID. They have separate address spaces (copy-on-write). exec() is usually called by the child to run a different program. Together, fork+exec is how new programs start in Unix." },
{ id:114, q:"What is exec() system call?", a:"exec() replaces the current process's memory image with a new program, loaded from a file.", exp:"The process retains its PID but gets new code, data, stack, and heap. Used after fork() to run a different program. Family: execl, execv, execle, execve, execlp, execvp. The shell uses fork+exec to run commands." },
{ id:115, q:"What is a zombie process?", a:"A zombie process is a process that has completed execution but still has an entry in the process table because its parent hasn't yet read its exit status.", exp:"The child's entry (exit code, timing) is kept until the parent calls wait(). Zombies don't consume resources (no memory/CPU) but do occupy a PID slot. Many zombies can exhaust PID space. A parent that ignores SIGCHLD or never waits creates zombies." },
{ id:116, q:"What is an orphan process?", a:"An orphan process is a process whose parent has terminated while the child is still running.", exp:"Orphans are re-parented to init/systemd (PID 1), which will call wait() for them. This prevents them from becoming permanent zombies. Daemons are intentionally orphaned — they fork and the parent exits, leaving the child as a daemon adopted by init." },
{ id:117, q:"What is a daemon?", a:"A daemon is a background process in Unix/Linux that runs continuously without direct user interaction, providing system services.", exp:"Examples: sshd (SSH), httpd (web server), cron (scheduled tasks), syslogd (logging). Daemons are orphaned intentionally, close standard I/O, create their own session (setsid()), and usually run as specific users (not root)." },
{ id:118, q:"What are Unix signals?", a:"Signals are software interrupts sent to processes to notify them of events.", exp:"Common signals: SIGTERM (15, graceful shutdown), SIGKILL (9, force kill, cannot be caught), SIGINT (2, Ctrl+C), SIGHUP (1, hangup/reload), SIGSEGV (11, segfault). Processes can install signal handlers. SIGKILL and SIGSTOP cannot be caught or ignored." },
{ id:119, q:"What is IPC (Inter-Process Communication)?", a:"IPC mechanisms allow processes to exchange data and synchronize.", exp:"Types: Pipes (anonymous, between related processes), Named pipes/FIFOs (between unrelated processes), Shared memory (fastest), Message queues, Semaphores, Sockets (over network or local). Shared memory needs synchronization; message passing is safer but slower." },
{ id:120, q:"What is a pipe in Unix?", a:"A pipe is a unidirectional communication channel connecting the stdout of one process to the stdin of another.", exp:"Anonymous pipes work between parent-child processes. Created with pipe() system call. In shell: cmd1 | cmd2. Named pipes (mkfifo) allow unrelated processes to communicate. Pipes have limited buffer; writer blocks when full, reader blocks when empty." },
{ id:121, q:"What is the difference between /bin, /usr/bin, and /sbin?", a:"/bin: essential user command binaries needed during boot; /usr/bin: user commands not needed during boot; /sbin: system administration commands typically run as root.", exp:"Historical Unix separation: /bin and /sbin on root partition (available early boot), /usr on separate partition (mounted later). Modern Linux often makes /bin → /usr/bin symlink. Examples — /bin: ls, cp, sh; /sbin: fdisk, ifconfig; /usr/bin: python, gcc." },
{ id:122, q:"What is /proc in Linux?", a:"/proc is a virtual filesystem in Linux that exposes kernel and process information as files.", exp:"Files in /proc don't exist on disk — they're generated by the kernel on read. Examples: /proc/cpuinfo (CPU info), /proc/meminfo (memory), /proc/[PID]/ (per-process info). Allows userspace tools to inspect kernel state without special calls." },
{ id:123, q:"What is cron?", a:"Cron is a Unix daemon that executes scheduled commands at specified times defined in crontab files.", exp:"Crontab format: minute hour day-of-month month day-of-week command. Example: 0 2 * * * /backup.sh runs backup at 2 AM daily. Each user has their own crontab. System crontab: /etc/crontab. Modern systems use systemd timers as well." },
{ id:124, q:"What is chmod?", a:"chmod (change mode) changes the file access permissions of files and directories.", exp:"Symbolic: chmod u+x file (add execute for user). Octal: chmod 755 file = rwxr-xr-x (owner=7=rwx, group=5=r-x, others=5=r-x). 777=full permissions, 644=rw-r--r-- (common for files), 755 (common for directories)." },
{ id:125, q:"What is the difference between su and sudo?", a:"su switches to another user's full session (usually root); sudo runs a single command with another user's (usually root's) privileges.", exp:"su requires the target user's password. sudo requires the requesting user's own password and checks /etc/sudoers for permission. sudo is safer: logs all commands, grants minimum privilege, doesn't require root password to be shared." },

// ==================== SECTION 9: WINDOWS SPECIFICS ====================
{ id:126, q:"What is the Windows Registry?", a:"The Windows Registry is a hierarchical database storing configuration settings for the OS, hardware, user preferences, and applications.", exp:"Organized into hives: HKEY_LOCAL_MACHINE (system/hardware), HKEY_CURRENT_USER (per-user settings), HKEY_CLASSES_ROOT (file associations), HKEY_USERS, HKEY_CURRENT_CONFIG. Edited with regedit. Corrupted registry can prevent Windows from booting." },
{ id:127, q:"What is the Windows Boot Process?", a:"Windows boots via: BIOS/UEFI → MBR/GPT → Windows Boot Manager → Windows Boot Loader → NT Kernel (ntoskrnl.exe) → Session Manager (smss.exe) → Winlogon.", exp:"UEFI replaces legacy BIOS. Boot Manager (bootmgr) reads the BCD (Boot Configuration Data) store. Boot Loader (winload.efi) loads the kernel. Kernel initializes hardware, loads drivers. smss starts subsystems and the login process." },
{ id:128, q:"What is NTFS permissions vs Share permissions?", a:"NTFS permissions apply locally to files/folders; Share permissions apply when accessing resources over the network.", exp:"When accessing a shared folder over the network, BOTH permissions apply — the more restrictive combination is effective. NTFS permissions persist locally regardless of access method; Share permissions only apply to network access. Best practice: use Full Control share permissions and restrict via NTFS." },
{ id:129, q:"What is the Windows Task Manager?", a:"Task Manager is a system utility showing running processes, CPU/memory/disk/network usage, services, and startup programs.", exp:"Key tabs: Processes (running apps and background processes with resource usage), Performance (graphs), Startup (manage auto-start programs), Services. Used to kill hung processes, monitor resource usage, and manage services." },
{ id:130, q:"What is a Windows service?", a:"A Windows service is a long-running executable that performs specific functions and can be started automatically at boot without user interaction.", exp:"Similar to Unix daemons. Managed via Services (services.msc), Task Manager, or SC command. Have startup types: Automatic, Automatic (Delayed), Manual, Disabled. Examples: Windows Update, Print Spooler, Windows Defender." },

// ==================== SECTION 10: ADVANCED TOPICS ====================
{ id:131, q:"What is virtual machine (VM)?", a:"A virtual machine is a software emulation of a complete computer system that runs on top of physical hardware.", exp:"A hypervisor creates and manages VMs. Each VM has virtual CPU, memory, storage, and network. VMs are isolated from each other. Benefits: server consolidation, easy backup/clone, testing. Examples: VMware, VirtualBox, Hyper-V, KVM." },
{ id:132, q:"What is a hypervisor?", a:"A hypervisor (VMM — Virtual Machine Monitor) is software that creates and manages virtual machines.", exp:"Type 1 (bare-metal): runs directly on hardware (VMware ESXi, Microsoft Hyper-V, KVM). Type 2 (hosted): runs on top of a host OS (VMware Workstation, VirtualBox). Type 1 is faster and used in production; Type 2 for development and testing." },
{ id:133, q:"What is a container vs virtual machine?", a:"Containers share the host OS kernel and isolate processes using namespaces/cgroups; VMs have complete guest OS isolation with a hypervisor.", exp:"Containers: lighter (MB), faster startup (seconds), less isolation. VMs: heavier (GB), slower startup (minutes), full OS isolation. Docker uses containers. Kubernetes orchestrates containers. Containers ideal for microservices; VMs for full OS isolation." },
{ id:134, q:"What is Docker?", a:"Docker is a platform for building, shipping, and running applications in lightweight containers.", exp:"Containers package code + dependencies. Docker daemon manages containers. Images are blueprints; containers are running instances. Docker Hub shares images. Key commands: docker run, build, pull, push, ps, stop. Uses Linux namespaces and cgroups." },
{ id:135, q:"What are Linux namespaces?", a:"Linux namespaces isolate process views of system resources so processes see separate instances of global resources.", exp:"Types: PID (separate process trees), Network (separate network stacks), Mount (separate filesystem views), UTS (separate hostname), IPC (separate IPC resources), User (separate user/group IDs). Containers use namespaces for isolation." },
{ id:136, q:"What are cgroups (control groups)?", a:"Cgroups are a Linux kernel feature that limit, account for, and isolate the resource usage (CPU, memory, disk I/O) of process groups.", exp:"Allow setting resource limits per group: max CPU%, memory limit, I/O bandwidth. Docker and Kubernetes use cgroups to enforce container resource limits. Hierarchical: subgroups inherit parent limits." },
{ id:137, q:"What is POSIX?", a:"POSIX (Portable Operating System Interface) is a set of IEEE standards defining a compatible interface between operating systems.", exp:"Ensures software portability between Unix-like systems. Defines APIs for system calls (file I/O, process management, threads), shell commands, and utilities. Linux is mostly POSIX-compliant; macOS is POSIX-certified. Allows 'write once, run anywhere' for system software." },
{ id:138, q:"What is the boot process?", a:"The boot process loads the OS from storage into memory and initializes the system.", exp:"Steps: Power on → BIOS/UEFI (POST, hardware init) → Boot device selection → Bootloader (GRUB/Windows Boot Manager) → Kernel load and init → Init system (systemd/init) → Services start → Login prompt/desktop." },
{ id:139, q:"What is GRUB?", a:"GRUB (GRand Unified Bootloader) is the most common Linux bootloader that loads the OS kernel.", exp:"Allows multi-boot (choose between multiple OS/kernels). Stage 1: loaded from MBR. Stage 2: loads from filesystem, shows menu, loads kernel. Config: /etc/default/grub and /boot/grub/grub.cfg. GRUB 2 is current version." },
{ id:140, q:"What is systemd?", a:"systemd is the modern Linux init system and service manager that replaces SysV init, managing boot, services, logging, and more.", exp:"Unit files define services, sockets, timers, mount points. Parallel startup for faster boot. Journald for logging. Key commands: systemctl start/stop/enable/disable/status. Controversial for violating Unix philosophy (does too much) but widely adopted." },
{ id:141, q:"What is the difference between concurrency and parallelism?", a:"Concurrency is dealing with multiple tasks (possibly interleaved on one core); parallelism is physically executing multiple tasks simultaneously on multiple cores.", exp:"Concurrency: logical — tasks make progress but may not run simultaneously. Parallelism: physical — tasks literally run at same time (multicore). A single-core CPU can be concurrent (timesharing) but not parallel. Both aim to improve performance but require different design." },
{ id:142, q:"What is multiprocessing?", a:"Multiprocessing uses multiple CPUs/cores to execute multiple processes truly in parallel.", exp:"Symmetric Multiprocessing (SMP): all CPUs share one OS and memory — most common today. Asymmetric: master CPU runs OS, others run user tasks. Modern CPUs have multiple cores, each capable of running processes in parallel. OS scheduler distributes processes across cores." },
{ id:143, q:"What is NUMA (Non-Uniform Memory Access)?", a:"NUMA is a computer memory architecture where memory access time depends on the memory location relative to the processor.", exp:"In NUMA systems, each processor has local memory (fast access) and remote memory (slower, accessed via interconnect). Important for performance: processes should access their local memory. Linux NUMA-aware scheduler tries to keep processes near their memory." },
{ id:144, q:"What is cache memory?", a:"Cache memory is fast, small memory between the CPU and main RAM that stores frequently accessed data to reduce access latency.", exp:"Hierarchy: L1 (fastest, KB, per-core), L2 (MB, per-core or shared), L3 (MB-GB, shared across cores), RAM, Disk. Cache works on temporal locality (recently used data) and spatial locality (nearby data). Cache miss sends CPU to next level." },
{ id:145, q:"What is the memory hierarchy?", a:"The memory hierarchy organizes memory types by speed, size, and cost from fastest/smallest/most-expensive (registers) to slowest/largest/cheapest (disk).", exp:"Registers → L1 Cache → L2 Cache → L3 Cache → RAM → SSD → HDD → Network Storage. Each level is 10–1000× slower than previous but larger. OS and hardware automatically manage data movement between levels to optimize performance." },
{ id:146, q:"What is thrashing in CPU context?", a:"CPU thrashing occurs when context switching overhead dominates, leaving little time for actual process execution.", exp:"If too many processes compete for CPU with very short quanta, most time is spent saving/restoring context rather than running. Solution: increase quantum size, reduce number of active processes. Related but distinct from memory thrashing (page fault storm)." },
{ id:147, q:"What is an interrupt handler (ISR)?", a:"An Interrupt Service Routine (ISR) is the code that runs in response to a hardware or software interrupt.", exp:"When interrupt occurs: hardware saves CPU state, looks up ISR address in interrupt vector table, jumps to ISR. ISR handles the event (e.g., copies keyboard character to buffer), then returns. Must be fast — other interrupts may be disabled during ISR execution." },
{ id:148, q:"What is the interrupt vector table?", a:"The interrupt vector table is a data structure mapping interrupt numbers to their handler (ISR) addresses.", exp:"Each interrupt has a number (0–255 on x86). The table stores the address of the handler for each interrupt. Timer: interrupt 0, keyboard: interrupt 1, etc. Protected by the OS — user programs cannot modify it directly." },
{ id:149, q:"What is a trap?", a:"A trap is a software-generated interrupt caused by an error (e.g., division by zero) or a deliberate system call.", exp:"Traps are synchronous (caused by the current instruction) unlike hardware interrupts (asynchronous). Exception traps: segfault (SIGSEGV), illegal instruction, overflow. System call trap: process requests OS service. The OS handles traps in kernel mode." },
{ id:150, q:"What is an exception?", a:"An exception is an unexpected event during program execution (like divide by zero, invalid memory access) that requires OS intervention.", exp:"The CPU generates an exception when it detects an error. The OS's exception handler runs, takes appropriate action (signal to process, kill process, or recover). Different from interrupts (external) — exceptions come from within the executing program." },

// SECTION 11 - MORE ADVANCED TOPICS
{ id:151, q:"What is a semaphore vs mutex?", a:"A mutex is owned (only the locker can unlock) and used for mutual exclusion; a semaphore has a count and is used for signaling and resource counting.", exp:"Mutex: binary, ownership semantics, used to protect critical sections. Semaphore: integer count, no ownership, used for signaling (producer/consumer) or counting resources. Using a mutex for signaling causes bugs; semaphores for critical sections can allow wrong thread to unlock." },
{ id:152, q:"What is a condition variable?", a:"A condition variable allows threads to sleep waiting for a condition to become true, releasing the mutex while waiting.", exp:"Used with a mutex. wait(cv, lock): atomically releases lock and sleeps. signal(cv): wakes one waiter. broadcast(cv): wakes all. Pattern: lock mutex → while(!condition) wait(cv, mutex) → do work → unlock mutex. 'While' not 'if' protects against spurious wakeups." },
{ id:153, q:"What is a read-write lock?", a:"A read-write lock (rwlock) allows multiple concurrent readers but only one exclusive writer.", exp:"Multiple threads can hold the read lock simultaneously. Only one thread can hold the write lock (exclusive). Writers must wait for all readers to finish. Improves performance when reads are more frequent than writes. pthread_rwlock_rdlock/wrlock." },
{ id:154, q:"What is the difference between stack and heap memory?", a:"Stack: automatically managed, LIFO, stores local variables and function call frames; Heap: manually managed (or GC), stores dynamically allocated objects.", exp:"Stack: fixed size, fast allocation (just decrement SP), automatically reclaimed on function return. Heap: grows dynamically, slower (malloc/new), programmer responsible for freeing (or GC handles it). Stack overflow: recursion too deep. Heap fragmentation from many alloc/free cycles." },
{ id:155, q:"What is memory-mapped files?", a:"Memory-mapped files map a file's contents into a process's virtual address space, allowing file I/O via memory operations.", exp:"mmap() in Unix. Access file data as if it were memory — OS handles paging to/from disk. Multiple processes can share the same mapping. Faster for large files vs sequential read/write. Used for shared memory IPC, loading executables/libraries." },
{ id:156, q:"What is copy-on-write (COW)?", a:"Copy-on-write is an optimization where forked processes initially share the parent's pages; copies are made only when a process tries to write.", exp:"After fork(), child and parent share the same physical pages (marked read-only). When either tries to write, a page fault occurs, the OS copies that page, and the write succeeds. Saves memory and time for fork+exec pattern (exec discards all pages anyway)." },
{ id:157, q:"What is huge pages?", a:"Huge pages are large memory pages (2MB or 1GB) instead of standard 4KB pages, reducing TLB pressure for large-memory applications.", exp:"Fewer TLB entries needed to map large memory regions → fewer TLB misses. Benefit for large in-memory databases (Redis, Oracle). Linux: HugePages and Transparent Huge Pages (THP) automatically collapse small pages into huge ones." },
{ id:158, q:"What is OOM killer in Linux?", a:"The OOM (Out Of Memory) killer is a Linux kernel mechanism that terminates processes when the system runs out of memory.", exp:"When memory is exhausted and allocation fails, the kernel selects and kills a process to free memory. Selection based on oom_score (considers memory use, runtime, nice value). Processes can adjust their oom_score_adj. Critical processes can be protected." },
{ id:159, q:"What is ELF format?", a:"ELF (Executable and Linkable Format) is the standard binary file format for executables, shared libraries, and object files on Unix/Linux.", exp:"ELF header: magic number, architecture, entry point. Program headers: segments (LOAD, DYNAMIC). Section headers: .text (code), .data (initialized data), .bss (uninitialized), .plt/.got (dynamic linking). Replaced COFF/a.out on Unix." },
{ id:160, q:"What is dynamic linking vs static linking?", a:"Static linking includes all library code into the executable; dynamic linking loads shared libraries at runtime.", exp:"Static: larger executable, no external dependencies, faster startup, no version conflicts. Dynamic: smaller executable, multiple programs share one copy of library, security patches applied to library affect all users, may have missing/version conflicts (DLL hell on Windows, .so on Linux)." },
{ id:161, q:"What is a loader?", a:"A loader is the OS component that reads an executable file from disk and loads it into memory to prepare it for execution.", exp:"Steps: validate executable (ELF/PE), allocate memory, copy code and data segments, set up stack, resolve dynamic links (dynamic linker), jump to entry point. The OS loader runs before the program's main() function." },
{ id:162, q:"What is a linker?", a:"A linker combines compiled object files and libraries into a single executable file, resolving symbolic references.", exp:"Static linker runs at compile time. Dynamic linker (ld.so on Linux) runs at load time for shared libraries. Resolves symbol references between modules. Handles relocation (adjusting addresses). GNU linker: ld. LLVM linker: lld." },
{ id:163, q:"What is Address Space Layout Randomization (ASLR)?", a:"ASLR randomizes the base addresses of executable, stack, heap, and libraries in a process's address space on each execution.", exp:"Prevents attackers from predicting memory locations for exploits. Linux ASLR: /proc/sys/kernel/randomize_va_space. Effectiveness reduced by info leaks. Combined with DEP/NX and stack canaries provides defense-in-depth against memory corruption attacks." },
{ id:164, q:"What is SMEP/SMAP?", a:"SMEP (Supervisor Mode Execution Prevention) and SMAP (Supervisor Mode Access Prevention) are CPU features preventing the kernel from executing or accessing user-space memory.", exp:"SMEP: kernel cannot execute code in user-space pages — prevents kernel code injection attacks. SMAP: kernel cannot read/write user-space pages without explicit permission (stac/clac instructions) — prevents kernel from being tricked into using attacker-controlled data." },
{ id:165, q:"What is Spectre and Meltdown?", a:"Spectre and Meltdown are CPU hardware vulnerabilities (2018) that exploit speculative execution to leak sensitive memory across security boundaries.", exp:"Meltdown: user process reads kernel memory via speculative execution + cache side channel. Spectre: tricks other processes into leaking memory. Mitigations: kernel page-table isolation (KPTI/KAISER) for Meltdown, retpoline for Spectre, with significant performance impact (5–30%)." },
{ id:166, q:"What is a system boot sector?", a:"The boot sector is the first sector (512 bytes) of a bootable device containing the Master Boot Record (MBR) or partition boot record.", exp:"MBR: 446 bytes bootstrap code + 64-byte partition table + 2-byte signature (0x55AA). BIOS reads MBR into memory at 0x7C00 and executes it. MBR code loads the bootloader. GPT replaces MBR on modern systems (supports >2TB disks, up to 128 partitions)." },
{ id:167, q:"What is UEFI vs BIOS?", a:"UEFI (Unified Extensible Firmware Interface) is the modern replacement for BIOS, offering faster boot, large disk support, secure boot, and a GUI.", exp:"BIOS: 16-bit, slow, limited to 2TB disks (MBR), no built-in network. UEFI: 64-bit, faster POST, supports disks >2TB (GPT), Secure Boot (verifies bootloader signature), pre-boot network (PXE). Most PCs since 2012 use UEFI." },
{ id:168, q:"What is Secure Boot?", a:"Secure Boot is a UEFI feature that ensures the bootloader is signed by a trusted key, preventing unauthorized code from running during boot.", exp:"The firmware checks the bootloader's digital signature against keys stored in NVRAM. Prevents boot-level rootkits. Linux requires signed bootloaders (shim + GRUB). Can be disabled in UEFI settings. Controversial: limits user control but improves security." },
{ id:169, q:"What is a rootkit?", a:"A rootkit is malware designed to hide itself and other malware from the OS and security tools, typically gaining persistent privileged access.", exp:"Kernel rootkits modify the OS kernel (most dangerous). User-mode rootkits modify user-space utilities (ps, ls). Bootkit: infects boot process, runs before OS. Detection: offline scanning, Tripwire (file integrity), hypervisor-based detection. Very difficult to remove — usually requires reinstall." },
{ id:170, q:"What is SELinux?", a:"Security-Enhanced Linux (SELinux) is a Linux kernel security module that implements Mandatory Access Control (MAC) policies.", exp:"Developed by NSA. Every process and file has a security context (label). Policy rules define allowed operations: source_label → target_label:action. Modes: enforcing (denies and logs), permissive (logs only), disabled. Used in RHEL/CentOS/Fedora. AppArmor is an alternative." },
{ id:171, q:"What is virtual memory vs physical memory?", a:"Virtual memory is the logical address space a process uses; physical memory is the actual RAM chips.", exp:"Virtual memory can be larger than physical (pages swapped to disk). Each process has its own virtual address space (isolation). The MMU translates virtual to physical addresses. The OS manages the mapping and handles page faults." },
{ id:172, q:"What is a page directory?", a:"A page directory is the top-level data structure in a multi-level page table hierarchy, mapping virtual addresses to page tables.", exp:"On x86 (32-bit): two-level: page directory → page tables → frames. On x86-64: four-level (PML4 → PDPT → PD → PT → frame). The CR3 register holds the physical address of the current process's page directory/PML4 table." },
{ id:173, q:"What is the difference between cooperative and preemptive multitasking?", a:"Cooperative: processes voluntarily yield the CPU; preemptive: the OS can forcibly interrupt a process.", exp:"Cooperative (Windows 3.x): one bad program can freeze the system (doesn't yield). Preemptive (Windows 95+, all modern OS): timer interrupts trigger the scheduler, ensuring fair CPU sharing. Preemptive requires synchronization to protect shared data." },
{ id:174, q:"What is a gang scheduling?", a:"Gang scheduling (co-scheduling) schedules related threads of a parallel program to run simultaneously on multiple processors.", exp:"Important for parallel programs that communicate (e.g., via message passing) — if one thread runs while its partner is suspended, it wastes time waiting for the partner's messages. Reduces synchronization wait by running communicating threads together." },
{ id:175, q:"What is load balancing in OS?", a:"Load balancing distributes processes/threads across multiple CPU cores to maximize performance and prevent any one core from being overloaded.", exp:"Push migration: overloaded processor pushes tasks to idle processors. Pull migration: idle processor pulls tasks from busy ones. The Linux CFS scheduler does load balancing periodically. NUMA-aware load balancing considers memory locality." },
// SECTION 12
{ id:176, q:"What is the Completely Fair Scheduler (CFS) in Linux?", a:"CFS is the default Linux process scheduler that aims to give each process a fair share of CPU time using a virtual runtime (vruntime).", exp:"Each process has a vruntime (CPU time used, scaled by priority). The scheduler always runs the process with the lowest vruntime (using a red-black tree). Nice value affects the rate at which vruntime advances. This ensures proportional fairness without strict quantum expiry." },
{ id:177, q:"What is nice value in Linux?", a:"The nice value is a number (-20 to +19) that influences a process's scheduling priority in Linux.", exp:"Lower nice = higher priority (gets more CPU). Higher nice = lower priority (yields to others). Default: 0. Only root can set negative values. In CFS, nice value affects the rate vruntime accumulates — nicer processes accumulate faster, getting less CPU share." },
{ id:178, q:"What is /etc/fstab?", a:"/etc/fstab is a configuration file listing filesystems to be automatically mounted at boot.", exp:"Each line: device, mount point, filesystem type, options, dump frequency, fsck order. Example: UUID=abc /home ext4 defaults 0 2. Modern systems also use systemd automount units. Incorrect fstab can prevent booting." },
{ id:179, q:"What is the difference between a hard disk and a solid state drive from OS perspective?", a:"From the OS perspective, both present a block device interface, but SSDs have different performance characteristics (no seek time, faster reads) and require special handling (TRIM).", exp:"SSDs don't benefit from seek-time-optimizing disk schedulers (SCAN). Linux uses 'none' or 'mq-deadline' for SSDs. TRIM command tells the SSD which blocks are freed so it can erase them proactively, maintaining write performance." },
{ id:180, q:"What is journaling vs log-structured file systems?", a:"Journaling adds a write-ahead log to a traditional file system; log-structured file systems write all data and metadata as sequential log entries.", exp:"Journaling (ext3/4, NTFS): logs changes before applying; replays on crash. Log-structured (LFS, F2FS for flash): all writes sequential — great for SSDs and flash. Garbage collection reclaims stale log entries. Log-structured better for write-heavy workloads on flash." },
{ id:181, q:"What is the difference between process scheduling and thread scheduling?", a:"Process scheduling allocates CPU to processes; thread scheduling allocates CPU to threads, which may be within the same process.", exp:"User-level threads: kernel sees only the process; thread library schedules threads (fast context switch, one block blocks all). Kernel-level threads: kernel manages each thread (true parallelism, expensive context switch). Linux: 1:1 model — each thread is a kernel task." },
{ id:182, q:"What is the global vs local scheduling?", a:"Global scheduling considers all threads/processes system-wide; local scheduling only considers threads within one process.", exp:"Global: Linux CFS — all threads compete globally for CPU. Local: some RTOS or user-level thread libraries schedule threads within a process without kernel visibility. Global scheduling better utilizes multiprocessors; local gives more predictable within-process behavior." },
{ id:183, q:"What is NUMA-aware scheduling?", a:"NUMA-aware scheduling assigns processes to CPUs that are physically close to the memory they use, reducing cross-NUMA memory access latency.", exp:"In NUMA systems, accessing remote memory (other socket's RAM) takes 2–3× longer. The scheduler tries to keep processes on the same NUMA node as their allocated memory. Linux numactl and taskset tools control NUMA placement." },
{ id:184, q:"What is a tick in the OS kernel?", a:"A kernel tick is a periodic timer interrupt (typically 100–1000 Hz) that drives the scheduler and timekeeping.", exp:"Each tick: update jiffies (tick counter), run scheduler (check if current process should yield), update statistics. Higher HZ: more responsive but more overhead. Tickless kernel (CONFIG_HZ_DYNAMIC): skips ticks when system is idle, saving power." },
{ id:185, q:"What is the difference between a monolithic kernel and a microkernel?", a:"Monolithic kernel: all OS services run in kernel space; microkernel: only minimal services (IPC, scheduling, basic memory) run in kernel, rest in user space.", exp:"Monolithic (Linux, Windows): fast (no user/kernel transitions for device drivers), large, bugs crash the whole OS. Microkernel (MINIX, QNX): more reliable (driver crash doesn't crash kernel), easier to extend, but slower (IPC overhead). Hybrid kernels (macOS XNU, Windows NT) mix approaches." },
{ id:186, q:"What is an exokernel?", a:"An exokernel is an experimental OS architecture that exposes hardware resources directly to applications, providing only protection and multiplexing.", exp:"Philosophy: eliminate abstractions — let applications manage their own resources (memory allocation algorithm, scheduling). Enables better optimization. MIT's Exokernel project. Not widely deployed but influenced research. Unikernels are a related concept." },
{ id:187, q:"What is a unikernel?", a:"A unikernel is a single-purpose OS image where an application and the OS libraries it needs are compiled into one bootable image, without general-purpose OS overhead.", exp:"No process separation, no multi-user, no unneeded drivers. Very small and fast boot. Used in cloud (run ML model, web server as unikernel). Examples: MirageOS (OCaml), Unikraft. Security: tiny attack surface. Less flexible than containers." },
{ id:188, q:"What is eBPF?", a:"eBPF (Extended Berkeley Packet Filter) is a Linux kernel technology that allows running sandboxed programs in the kernel without modifying kernel source or loading modules.", exp:"Originally for network packet filtering, now used for tracing, performance monitoring, security (blocking syscalls). Programs are verified (safety checked) then JIT-compiled. Used by Cilium (networking), Falco (security), BPFTrace (tracing). Revolutionizing Linux observability." },
{ id:189, q:"What is POSIX threads (pthreads)?", a:"POSIX threads (pthreads) is the POSIX standard API for multithreaded programming in C on Unix systems.", exp:"Key functions: pthread_create (create thread), pthread_join (wait for thread), pthread_mutex_lock/unlock, pthread_cond_wait/signal. Each thread has own stack; shares global data with other threads. Available on Linux, macOS, and other POSIX systems." },
{ id:190, q:"What is a futex?", a:"A futex (fast userspace mutex) is a Linux kernel mechanism that provides efficient synchronization by avoiding kernel calls when there's no contention.", exp:"In the uncontended case, locking is done purely in userspace (atomic instruction — no syscall). Only when there's contention does the futex call the kernel (FUTEX_WAIT/WAKE) to block/wake threads. pthread_mutex uses futexes internally. Orders of magnitude faster than pure kernel semaphores." },
{ id:191, q:"What is the process address space layout?", a:"A process's virtual address space is typically divided into: text (code), data (initialized globals), BSS (uninitialized globals), heap (grows up), stack (grows down), and mmap region.", exp:"Low address: text segment (read-only code). Above that: data + BSS. Heap starts above BSS, grows upward. Stack starts at top, grows downward. mmap region (shared libraries, file mappings) in between. The gap between heap and stack is a large unmapped region." },
{ id:192, q:"What is memory protection?", a:"Memory protection prevents processes from accessing each other's memory, enforced by the MMU and OS.", exp:"Each process has its own virtual address space — can't access others' memory directly. Page table entries have protection bits (read/write/execute). Attempts to access invalid pages trigger a segmentation fault (SIGSEGV). Kernel memory is mapped but protected from user access." },
{ id:193, q:"What is copy semantics vs reference semantics in OS context?", a:"Copy semantics: passing data copies it (processes have independent copies); reference semantics: passing a reference means both see the same data.", exp:"IPC via message passing uses copy semantics (safe, no aliasing). Shared memory uses reference semantics (efficient but needs synchronization). fork() uses copy-on-write — appears like copy semantics but defers actual copying until modification." },
{ id:194, q:"What is named pipe vs anonymous pipe?", a:"Anonymous pipes connect related processes (parent-child); named pipes (FIFOs) have a filesystem name and connect unrelated processes.", exp:"Anonymous pipe: created with pipe(), exists only while processes hold it open. Named pipe (FIFO): created with mkfifo, persists as a filesystem entry. Both are unidirectional. Multiple writers to a FIFO are serialized. Used in Unix shell pipelines and IPC." },
{ id:195, q:"What is a Unix domain socket?", a:"A Unix domain socket is a communication endpoint for IPC between processes on the same machine, similar to network sockets but using file system paths.", exp:"Faster than TCP loopback (no TCP/IP stack overhead). Full-duplex, bidirectional. Used by Docker (docker.sock), databases (PostgreSQL, MySQL), desktop environments (D-Bus). Supports sending file descriptors between processes (SCM_RIGHTS)." },
{ id:196, q:"What is shared memory IPC?", a:"Shared memory IPC allows multiple processes to access the same region of physical memory for the fastest possible IPC.", exp:"System V shared memory: shmget/shmat/shmdt/shmctl. POSIX shared memory: shm_open/mmap. Fastest IPC mechanism — no data copying. Requires explicit synchronization (semaphores, mutexes) to prevent race conditions. Used in databases, scientific computing." },
{ id:197, q:"What is a message queue?", a:"A message queue is an IPC mechanism that allows processes to send and receive messages in a decoupled, asynchronous manner.", exp:"System V: msgget/msgsnd/msgrcv. POSIX: mq_open/mq_send/mq_receive. Messages have type/priority. Sender and receiver don't need to run simultaneously. Kernel buffers messages. Limits on message size and queue length. Used in microservices, event-driven systems." },
{ id:198, q:"What is an event-driven OS?", a:"An event-driven OS or programming model processes events (I/O completion, signals, timers) using callbacks or event loops rather than blocking.", exp:"Node.js's event loop, select/epoll/kqueue in OS kernels. Efficient for I/O-bound workloads (servers handling thousands of connections). Avoids thread-per-connection overhead. The OS provides efficient event notification via epoll (Linux), kqueue (BSD/macOS), IOCP (Windows)." },
{ id:199, q:"What is epoll?", a:"epoll is a Linux kernel I/O event notification mechanism that efficiently monitors many file descriptors for readiness.", exp:"Improvement over select/poll which scan all FDs on each call. epoll maintains a kernel-side set of FDs to watch. epoll_wait returns only the ready ones — O(ready) vs O(total). Edge-triggered (ET) vs level-triggered (LT). Used by Nginx, Redis, and virtually all high-performance Linux servers." },
{ id:200, q:"What is io_uring?", a:"io_uring is a modern Linux asynchronous I/O interface (Linux 5.1+) that uses shared ring buffers between kernel and userspace for very low-overhead async I/O.", exp:"Two ring buffers: submission queue (userspace → kernel: I/O requests) and completion queue (kernel → userspace: results). Zero-copy, minimal syscalls. Can batch hundreds of I/O operations per syscall. Faster than epoll + non-blocking I/O. Used in high-performance databases and servers." },

// Sections 13-20 (201-500+)
{ id:201, q:"What is the fork-exec model?", a:"The fork-exec model creates a child process (fork) then replaces its image with a new program (exec) — the Unix way of launching new programs.", exp:"fork() duplicates the parent. exec() replaces the child with desired program. Shell uses this: sh → fork → child sh → exec → ls. The two-step model gives the shell time to set up redirections, environment variables between fork and exec." },
{ id:202, q:"What is posix_spawn?", a:"posix_spawn is a POSIX API that creates a new process more efficiently than fork+exec, particularly on systems without copy-on-write.", exp:"Combines fork+exec into one call, reducing overhead. Useful on embedded systems or when fork's full copy is expensive. Supports file action setup (redirect, close FDs) and attribute setting (scheduling, signal masks) without the fork+exec dance." },
{ id:203, q:"What is vfork?", a:"vfork is a system call similar to fork but the child shares the parent's address space and the parent is suspended until the child calls exec or _exit.", exp:"Faster than fork (no virtual address space copy or COW setup). Dangerous: child must not modify parent's data. Intended only for immediately followed exec. Modern fork with COW makes vfork's advantage smaller, but it's still used in performance-critical code." },
{ id:204, q:"What is clone() system call in Linux?", a:"clone() is a Linux-specific system call that creates a new process or thread with fine-grained control over which resources are shared.", exp:"More flexible than fork/pthread_create. Flags control what's shared: CLONE_THREAD (thread, shared memory), CLONE_NEWPID (new PID namespace), CLONE_NEWNET (new network namespace), etc. Containers use clone() with namespace flags to create isolated environments." },
{ id:205, q:"What is a kernel thread?", a:"A kernel thread is a thread scheduled by the OS kernel that runs entirely in kernel space to perform background OS tasks.", exp:"Examples: kswapd (memory reclaim), kworker (workqueue processing), ksoftirqd (soft interrupt processing), migration (load balancing). Visible in 'ps aux' with names in brackets (e.g., [kswapd0]). Have kernel stacks and can be scheduled independently." },
{ id:206, q:"What is a soft interrupt (softirq)?", a:"A softirq is a deferred interrupt processing mechanism in the Linux kernel that handles interrupt work that can be delayed.", exp:"Hardware interrupts must be fast (critical section, other interrupts disabled). Expensive work (TCP/IP processing, disk I/O completion) is deferred to softirqs, which run with interrupts enabled. Types: NET_TX, NET_RX, BLOCK, TIMER, TASKLET. Processed by ksoftirqd or on return from interrupt." },
{ id:207, q:"What is a tasklet in Linux kernel?", a:"A tasklet is a form of softirq in Linux used by device drivers for deferred interrupt processing that cannot run concurrently with itself.", exp:"Simpler than softirqs (cannot run simultaneously on different CPUs for same tasklet type). Used in device drivers for 'bottom half' processing. DECLARE_TASKLET macro. Being deprecated in favor of threaded IRQs. Run in interrupt context — cannot sleep." },
{ id:208, q:"What is a workqueue in Linux kernel?", a:"A workqueue is a kernel mechanism for deferring work to a kernel thread, allowing the work to sleep (unlike softirqs/tasklets).", exp:"Work items can sleep, do memory allocation, use mutexes — unlike interrupts. The kernel maintains worker thread pools. INIT_WORK, schedule_work macros. Used when deferred work might block (e.g., USB device probe, network setup)." },
{ id:209, q:"What is a spinlock vs mutex in kernel?", a:"In the kernel: spinlocks are used in interrupt context (cannot sleep); mutexes can sleep and are for process context.", exp:"Kernel spinlock: disables preemption, busy-waits — suitable for very short critical sections and IRQ handlers. Kernel mutex: can sleep, used for longer critical sections where sleeping is acceptable. Using a mutex in interrupt context = BUG (IRQ handlers cannot schedule)." },
{ id:210, q:"What is RCU (Read-Copy-Update)?", a:"RCU is a Linux kernel synchronization mechanism that allows multiple concurrent readers without locks, while writers create a new version and wait for existing readers to finish.", exp:"Readers: completely lock-free (just rcu_read_lock/unlock which only disables preemption). Writers: copy-modify-publish the new version, then wait for a grace period (all pre-existing readers finish) before freeing the old version. Extremely fast reads. Used extensively in Linux networking and VFS." },
{ id:211, q:"What is memory barrier?", a:"A memory barrier is a hardware or compiler instruction that enforces ordering of memory operations, preventing reordering by CPU or compiler.", exp:"CPUs and compilers reorder operations for performance. Without barriers, locks break. Types: read barrier (all reads before are complete), write barrier (all writes before are committed), full barrier (both). In Linux: smp_rmb(), smp_wmb(), smp_mb(). Essential for lock-free programming." },
{ id:212, q:"What is cache coherency?", a:"Cache coherency ensures that all CPU cores see a consistent view of memory even though each has its own cache.", exp:"When one core writes to a memory location, other cores' caches with that location must be invalidated or updated. Protocols: MESI (Modified, Exclusive, Shared, Invalid). Cache coherency is transparent to software but affects performance — false sharing causes unnecessary invalidations." },
{ id:213, q:"What is false sharing?", a:"False sharing occurs when two threads modify different variables that happen to be in the same cache line, causing unnecessary cache invalidations and performance degradation.", exp:"Cache lines are typically 64 bytes. If thread A writes variable X and thread B writes variable Y, and X and Y are in the same cache line, each write invalidates the other's cache. Fix: pad structures so hot variables are in separate cache lines (alignas(64))." },
{ id:214, q:"What is the Meltdown vulnerability in detail?", a:"Meltdown exploits out-of-order execution to allow a user process to read kernel memory by measuring cache state after a faulting memory access.", exp:"CPU speculatively executes load of kernel address, data enters cache. Then fault occurs, speculative result discarded. But cache state remains! Attacker uses timing side-channel to infer the cached value. Mitigation: KPTI — unmap kernel pages from user address space, expensive on each syscall." },
{ id:215, q:"What is KPTI (Kernel Page-Table Isolation)?", a:"KPTI maintains separate page tables for user and kernel mode, with the user-mode table containing minimal kernel mappings to mitigate Meltdown.", exp:"Before KPTI: kernel mapped in every process's page table (just protected). After KPTI: user-mode page table has only the kernel code needed for entering/exiting kernel mode. Performance cost: 5–30% on syscall-heavy workloads due to TLB flushes on every kernel entry." },
{ id:216, q:"What is the difference between process migration and thread migration?", a:"Process migration moves an entire process to another machine; thread migration moves a thread to another CPU/core.", exp:"Process migration: for load balancing in distributed systems (checkpoint, transfer, restart). Thread migration: within a multiprocessor, the scheduler moves threads between cores for load balancing (transparent to software). Process migration is expensive; thread migration is kernel-managed." },
{ id:217, q:"What is checkpoint and restore?", a:"Checkpoint saves the complete state of a running process to disk; restore recreates it from that state.", exp:"Used for: fault tolerance (resume after crash), migration (move to another machine), debugging (replay), long-running jobs (HPC). Linux CRIU (Checkpoint/Restore In Userspace) checkpoints containers. Must save: memory, registers, file descriptors, network connections, etc." },
{ id:218, q:"What is swap space?", a:"Swap space is disk space used as an extension of physical RAM, where pages are stored when memory is full.", exp:"Linux: swap partition or swap file (mkswap/swapon). Windows: pagefile.sys. When RAM is full, the kernel swaps out cold pages to swap. Swapping to disk is very slow (milliseconds vs nanoseconds for RAM). Rule of thumb: swap = 1–2× RAM. SSDs make swap less painful." },
{ id:219, q:"What is the difference between swapping and paging?", a:"Swapping moves entire processes to disk; paging moves individual pages.", exp:"Early OS used whole-process swapping. Modern OS use page-level swapping (demand paging) — only unused pages are moved to disk, much more efficient. The terms are often used interchangeably in modern contexts (Linux 'swapping' = paging to swap space)." },
{ id:220, q:"What is kernel preemption?", a:"Kernel preemption allows the kernel to preempt a running kernel thread in favor of a higher-priority process, improving latency.", exp:"Non-preemptible kernel (old Linux): kernel code runs to completion, real-time tasks delayed. Preemptible kernel (CONFIG_PREEMPT): kernel can be preempted at most points. Fully preemptible (PREEMPT_RT patch): even spinlocks become preemptible — needed for hard real-time Linux." },
{ id:221, q:"What is an interrupt affinity?", a:"Interrupt affinity pins hardware interrupt handling to specific CPU cores, reducing cache bouncing and improving interrupt processing performance.", exp:"/proc/irq/N/smp_affinity bitmask sets which CPUs handle interrupt N. irqbalance daemon automatically distributes interrupts. Network cards can use multi-queue (RSS) to distribute packets across multiple interrupts on different CPUs." },
{ id:222, q:"What is CPU affinity?", a:"CPU affinity binds a process or thread to specific CPUs, ensuring it always runs on the same core(s) for cache warmth and predictability.", exp:"Linux: taskset command or sched_setaffinity(). Useful for real-time tasks, benchmark repeatability, NUMA optimization. Container orchestrators (Kubernetes) use CPU pinning for latency-sensitive workloads. Opposite: CPU isolation (isolcpus kernel parameter) reserves CPUs for specific tasks." },
{ id:223, q:"What is perf in Linux?", a:"perf is the Linux performance analysis tool using kernel performance counters (PMCs) to measure CPU cycles, cache misses, branch mispredictions, and more.", exp:"Commands: perf stat (count events), perf record (sample call stacks), perf report (analyze samples). Uses hardware PMCs (Performance Monitoring Counters) built into CPUs. Can profile user + kernel code. Foundation for many profiling tools (Flame Graphs, etc.)." },
{ id:224, q:"What is strace?", a:"strace is a Linux debugging tool that traces system calls and signals made by a process.", exp:"Shows every syscall with arguments and return values. Useful for debugging: what files is a program opening? Why is it failing? Example: strace -e openat ls shows file open calls. Adds significant overhead — not for production profiling. ltrace traces library calls." },
{ id:225, q:"What is the difference between I/O bound and CPU bound processes?", a:"I/O bound processes spend most time waiting for I/O; CPU bound processes spend most time computing.", exp:"I/O bound: web servers, databases, file processing — spend time waiting for network/disk. CPU bound: video encoding, scientific computing, ML training — keep the CPU busy. Scheduling: I/O bound processes need fast response (get CPU quickly on I/O completion); CPU bound processes can wait longer." },
{ id:226, q:"What is the idle process in Windows/Linux?", a:"The idle process/thread runs when no other processes are ready to execute, keeping the CPU occupied and enabling power saving (HLT instruction).", exp:"Windows: System Idle Process (PID 0) — its CPU% shows CPU idle time. Linux: swapper/idle threads (PID 0 per CPU). Idle threads execute HLT or MWAIT to enter CPU power-saving C-states. CPU usage shown as idle in top/htop." },
{ id:227, q:"What is a zombie vs sleeping process?", a:"Zombie: process exited but parent hasn't read exit status (dead but in table). Sleeping: process is alive but waiting for a resource or event.", exp:"Zombie (Z in ps): takes process table slot but no memory/CPU. Sleeping/waiting: may be interruptible sleep (woken by signal) or uninterruptible sleep (D state in ps — waiting for disk I/O). D state processes can't be killed — may indicate stuck I/O. Many D-state processes often means disk/NFS problem." },
{ id:228, q:"What is the difference between blocked and sleeping state?", a:"These are often synonymous: a blocked/sleeping process is waiting for an event (I/O completion, signal, timer) and is not eligible for CPU scheduling.", exp:"Linux ps shows: S (interruptible sleep), D (uninterruptible sleep), T (stopped). Interruptible can be woken by signals. Uninterruptible (D) cannot — waiting for kernel I/O. Stopped (T): received SIGSTOP or being traced by debugger." },
{ id:229, q:"What is the ready queue?", a:"The ready queue is the list of processes that are loaded into memory and waiting to execute on the CPU.", exp:"The short-term scheduler selects from the ready queue. Implemented as a priority queue (priority scheduling), FIFO (FCFS), or sorted tree (CFS). Processes enter the ready queue when they are new, complete I/O, or are preempted. The scheduler dispatches the selected process to the CPU." },
{ id:230, q:"What is dispatch latency?", a:"Dispatch latency is the time it takes for the OS to stop one process and start another — the overhead of a context switch.", exp:"Includes: saving context of current process, selecting next process (scheduler), loading context of next process. Typically microseconds. Measured and minimized in RTOS. Preemptive kernels have lower dispatch latency for high-priority tasks. PREEMPT_RT aims for sub-100μs latency." },
{ id:231, q:"What is convoy effect?", a:"The convoy effect in FCFS scheduling occurs when many short processes queue behind one long process, causing high average wait times.", exp:"Example: 1 CPU-bound process + many I/O-bound processes. CPU-bound holds CPU for long burst; I/O-bound processes wait. When CPU-bound finally does I/O, all others complete quickly, then CPU-bound gets CPU again — convoy cycles. SJF and Round Robin solve this." },
{ id:232, q:"What is starvation vs indefinite postponement?", a:"Starvation: process waits indefinitely because other processes always get priority. Indefinite postponement: process keeps being moved to back of queue without guarantee of ever running.", exp:"In priority scheduling: high-priority stream prevents low-priority from running (starvation). Aging solves it by gradually raising priority of waiting processes. In priority+preemption: a low-priority process may be preempted each time it starts (indefinite postponement)." },
{ id:233, q:"What is the response time vs turnaround time?", a:"Response time: time from submission to first response. Turnaround time: total time from submission to completion.", exp:"For interactive systems, response time matters most (user wants quick feedback). For batch systems, turnaround time matters. Turnaround = waiting time + execution time. For time-sharing, first response (not completion) defines user experience. Round Robin minimizes response time." },
{ id:234, q:"What is throughput in OS scheduling?", a:"Throughput is the number of processes completed per unit time — a measure of how much useful work the CPU is doing.", exp:"Higher throughput = more processes completed. Trade-off with latency: optimizing for throughput may increase individual response times. SJF maximizes throughput for a given workload. Context switch overhead reduces throughput. Batch systems prioritize throughput over response time." },
{ id:235, q:"What is CPU burst vs I/O burst?", a:"A CPU burst is a period during which a process uses the CPU continuously; an I/O burst is a period during which the process waits for I/O.", exp:"Process execution alternates between CPU bursts and I/O bursts. CPU-bound: long CPU bursts, few I/O bursts. I/O-bound: short CPU bursts, many I/O bursts. Burst length distribution is key to scheduler design. Most real processes are I/O-bound with short CPU bursts (exponential distribution)." },
{ id:236, q:"What is exponential averaging for CPU burst prediction?", a:"Exponential averaging (aging) predicts next CPU burst length by weighing recent history more than past history.", exp:"Formula: τ_{n+1} = α × t_n + (1-α) × τ_n. t_n = actual nth burst. τ_n = predicted nth burst. α=0.5 (typical). With α=0.5, half weight on latest burst, half on all history. Used by SJF to estimate burst lengths without future knowledge. α closer to 1 gives more weight to recent." },
{ id:237, q:"What is the difference between hard and soft real-time systems?", a:"Hard real-time: missing a deadline is a system failure. Soft real-time: missing a deadline degrades quality but system continues.", exp:"Hard: airbag systems, pacemakers, flight control — missing deadline = catastrophe. Soft: video streaming, VoIP — late frames reduce quality but don't cause catastrophic failure. Hard RTOS uses fixed-priority preemptive scheduling (Rate Monotonic, EDF). Soft RTOS may use priority scheduling with guarantees." },
{ id:238, q:"What is Rate Monotonic Scheduling (RMS)?", a:"RMS is a real-time scheduling algorithm that assigns higher priority to processes with shorter periods (more frequent tasks).", exp:"Optimal static-priority scheduling for independent periodic tasks. Task with period T gets priority inversely proportional to T. If sum(Ci/Ti) ≤ n(2^(1/n)-1) (utilization bound), all deadlines will be met. For n→∞, bound approaches ln(2) ≈ 0.693." },
{ id:239, q:"What is Earliest Deadline First (EDF)?", a:"EDF is a dynamic real-time scheduling algorithm that always schedules the process with the nearest deadline.", exp:"Theoretically optimal for preemptive uniprocessors — achieves 100% CPU utilization while meeting all deadlines (if feasible at all). Dynamic priority changes as deadlines approach. More complex to implement than RMS. Used in Linux SCHED_DEADLINE policy." },
{ id:240, q:"What is the difference between preemptive and non-preemptive kernel?", a:"Preemptive kernel: kernel code can be preempted by a higher-priority process; non-preemptive: kernel code runs to completion.", exp:"Non-preemptive: simpler synchronization (kernel sections safe from preemption), worse latency for real-time tasks. Preemptive: better latency but requires spinlocks/mutexes in kernel to protect shared kernel data structures. Linux became preemptible with 2.6 kernel." },
{ id:241, q:"What is a page frame?", a:"A page frame is a fixed-size block of physical memory into which a virtual page can be mapped.", exp:"Page size = frame size (e.g., 4KB). Physical memory consists of N frames. The OS maintains a free frame list. When a page fault occurs, a free frame is chosen; if none available, a victim frame is selected for replacement." },
{ id:242, q:"What is page table walk?", a:"A page table walk is the process of traversing multi-level page table structures to translate a virtual address to a physical address.", exp:"On x86-64 (4-level): virtual address split into PML4 index, PDPT index, PD index, PT index, and page offset. Each level indexes into a table to get the next table's physical address. 4 memory accesses in worst case (without TLB). Hardware PTW handles this automatically." },
{ id:243, q:"What is the dirty bit in page tables?", a:"The dirty bit (modified bit) is a flag in a page table entry indicating the page has been written to and must be saved to disk before the frame can be reused.", exp:"Hardware sets dirty bit on any write to the page. On page replacement: if dirty, write to swap before reusing frame. If clean, just discard (reload from original file if needed). Dirty bit tracking saves disk writes — clean pages are free to evict without I/O." },
{ id:244, q:"What is the accessed bit (reference bit) in page tables?", a:"The accessed (reference) bit is set by hardware when a page is read or written, used by page replacement algorithms to determine which pages are active.", exp:"LRU approximation uses reference bits. Clock algorithm: scans pages; if referenced, clear bit and skip; if not referenced, replace it. Aging algorithm: periodic interrupt shifts bits right, ORs current reference bit into MSB — page with lowest value is coldest." },
{ id:245, q:"What is inverted page table?", a:"An inverted page table has one entry per physical frame (not per virtual page), mapping frame to (process, virtual page) pair.", exp:"Reduces page table size — proportional to physical memory, not virtual address space size. Lookup: hash the (PID, virtual page) to find frame. Problem: slow lookup (hash collision chains). Used in IBM POWER, HP PA-RISC. TLB caches translations to reduce lookup frequency." },
{ id:246, q:"What is demand segmentation?", a:"Demand segmentation loads only the needed segments of a program into memory, similar to demand paging but at segment granularity.", exp:"A segment (code, stack, data, library) is loaded only when first accessed. Segments can be shared between processes (shared library segment loaded once). Segments have variable size unlike pages. Combined with paging in most modern systems (paged segmentation)." },
{ id:247, q:"What is a segmentation fault?", a:"A segmentation fault (SIGSEGV) occurs when a process accesses memory outside its valid virtual address space or violates memory protection.", exp:"Causes: null pointer dereference, buffer overflow (accessing beyond array bounds), stack overflow (deep recursion), use-after-free (accessing freed memory). The MMU detects invalid/protected access, raises exception, OS sends SIGSEGV to process, default action: terminate + core dump." },
{ id:248, q:"What is the stack in process memory?", a:"The stack is the LIFO region of process memory that stores local variables, function parameters, and return addresses for function calls.", exp:"Grows downward (lower addresses). Each function call pushes a stack frame containing: return address, saved registers, local variables. Stack pointer (SP/RSP) tracks top. Stack overflow: too deep recursion or too large local arrays exhaust stack space (causes SIGSEGV)." },
{ id:249, q:"What is the heap in process memory?", a:"The heap is the dynamically growing memory region from which processes allocate and free memory at runtime (malloc/free, new/delete).", exp:"Grows upward (higher addresses). Managed by heap allocator library (glibc malloc, tcmalloc, jemalloc). malloc calls brk() or mmap() to get more memory from OS. Fragmentation, memory leaks, and double-free are common heap-related bugs." },
{ id:250, q:"What is brk() and sbrk()?", a:"brk()/sbrk() are system calls that change the end of a process's data segment (heap top), effectively growing or shrinking the heap.", exp:"brk(addr) sets the end of the heap to addr. sbrk(increment) increments heap by given amount, returning old end. Modern allocators use mmap() for large allocations and brk for small ones. Understanding brk helps with memory profiling and allocator internals." },

// Section 15: More questions 251-350
{ id:251, q:"What is mmap() system call?", a:"mmap() creates a memory mapping — either a file-backed mapping or anonymous mapping — in the process's virtual address space.", exp:"File-backed: file contents accessible as memory, changes optionally written back. Anonymous: like malloc — gets zeroed pages. Shared: multiple processes see same physical memory. Private: copy-on-write semantics. Used for file I/O, shared memory, loading libraries, dynamic memory." },
{ id:252, q:"What is the difference between anonymous and file-backed mmap?", a:"File-backed mmap maps a file into memory; anonymous mmap allocates zeroed pages not backed by any file.", exp:"File-backed: changes can be flushed to file (msync). Anonymous: backed by swap space when paged out. Private anonymous mmap is how malloc gets large memory from OS. Shared anonymous mmap is used for IPC between processes created by fork." },
{ id:253, q:"What is the page cache in Linux?", a:"The page cache is kernel memory used to cache filesystem data (file contents) to avoid repeated disk reads.", exp:"When a file is read, its data is cached in page cache. Future reads served from cache (fast). Writes to files update page cache (write-back or write-through). Page cache competes with process memory for RAM. Linux uses all free memory for page cache; reclaims when processes need memory." },
{ id:254, q:"What is the buddy system allocator?", a:"The buddy system is a memory allocation algorithm that divides memory into blocks of sizes that are powers of 2, and maintains free lists for each size.", exp:"To allocate 2^k: find smallest free block ≥ 2^k. If too big, split into two buddies. When freeing, coalesce with buddy if both free. Fast allocation/deallocation, minimal external fragmentation, but internal fragmentation from power-of-2 rounding. Used in Linux kernel page allocator." },
{ id:255, q:"What is the slab allocator?", a:"The slab allocator is a kernel memory allocator that pre-allocates caches of frequently used objects to reduce allocation time and fragmentation.", exp:"Object caches (slabs) for specific types: inode, task_struct, etc. On allocation: grab from slab (fast, no initialization needed). On deallocation: return to slab. Reduces fragmentation and initialization overhead. Linux SLUB is the modern slab implementation. kmalloc/kfree use it." },
{ id:256, q:"What is internal fragmentation in slab?", a:"In slab allocation, internal fragmentation occurs when the allocated object is smaller than the slab's object size, wasting memory.", exp:"Slabs are sized for specific object types, so within a slab, waste is minimal. But generic kmalloc has size classes (8, 16, 32, 64... bytes) — allocating 33 bytes gets a 64-byte slot, wasting 31 bytes. Generally much less waste than buddy system for kernel objects." },
{ id:257, q:"What is huge page TLB optimization?", a:"Using huge pages reduces the number of TLB entries needed to cover a given amount of memory, reducing TLB misses.", exp:"4KB pages: 1TB RAM needs 256M page table entries. 2MB huge pages: same RAM needs 512K entries — all fit in TLB. Databases, JVMs, and HPC workloads benefit greatly. Linux THP (Transparent Huge Pages) automatically uses huge pages when possible." },
{ id:258, q:"What is memory overcommit?", a:"Memory overcommit allows the OS to allocate more virtual memory than physical RAM + swap, assuming processes won't use all their allocations simultaneously.", exp:"Linux overcommits by default (most processes request more than they use). Overcommit ratios: 0 (heuristic), 1 (always allow), 2 (never allow more than RAM+swap). If overcommit leads to actual memory exhaustion, OOM killer activates. Controversial — can lead to unexpected kills." },
{ id:259, q:"What is /proc/meminfo?", a:"/proc/meminfo is a Linux virtual file providing real-time memory statistics including total, free, cached, and swap memory.", exp:"Key fields: MemTotal (physical RAM), MemFree (completely unused), MemAvailable (can be freed for apps = free + reclaimable cache), Cached (page cache), SwapTotal/SwapFree, Dirty (modified pages not yet written). Used by free, htop, and monitoring tools." },
{ id:260, q:"What is the difference between free memory and available memory?", a:"Free memory is completely unused RAM; available memory includes free plus memory that can be reclaimed from caches to serve new requests.", exp:"In Linux, 'free' memory appears low because unused RAM is used as page cache (performance optimization). 'Available' gives a realistic picture of what can be given to new processes. 'free -h' shows both. A system with low free but high available is NOT actually low on memory." },
{ id:261, q:"What is a file descriptor?", a:"A file descriptor is a non-negative integer that serves as a handle for an open file, socket, pipe, or other I/O resource in Unix.", exp:"0=stdin, 1=stdout, 2=stderr. Created by open(), socket(), pipe(). Inherited by child processes (fork). Closed by close(). The kernel maintains a file descriptor table per process. /proc/PID/fd/ shows open file descriptors. ulimit -n sets max FDs per process." },
{ id:262, q:"What is the open file table?", a:"The open file table is a kernel data structure maintaining the state of each open file instance — file position, access mode, and inode pointer.", exp:"Per-process FD table → system-wide open file table → inode table. Multiple FDs (even across processes) can share an open file table entry (via dup/fork). File position is per-open-file-table entry, not per inode. This is why dup2 shares position but open() creates a new entry." },
{ id:263, q:"What is dup() and dup2() system calls?", a:"dup() creates a copy of a file descriptor; dup2(oldfd, newfd) creates a copy with a specific number, closing newfd if open.", exp:"Used for I/O redirection: dup2(file_fd, 1) makes stdout point to a file. Common shell redirection implementation: open file, dup2 to stdout/stderr, close original fd. Both FDs refer to the same open file table entry (share file position and flags)." },
{ id:264, q:"What is select() system call?", a:"select() allows a program to monitor multiple file descriptors, waiting until one or more are ready for I/O.", exp:"Takes three sets of FDs to monitor (read, write, except), and a timeout. Returns the number of ready FDs. Limitation: max 1024 FDs (FD_SETSIZE), O(n) scan on each call. Replaced by poll() (no FD limit) and epoll (O(ready) scan). Widely portable (POSIX)." },
{ id:265, q:"What is the difference between poll() and select()?", a:"poll() is similar to select() but uses an array of pollfd structures instead of bitmasks, removing the 1024 FD limit.", exp:"select(): 3 bitmask sets, max 1024 FDs by default, modifies the sets on return. poll(): array of {fd, events, revents} — no hard limit, doesn't modify input. Both scan all FDs on each call: O(n). Neither scales well for thousands of connections — use epoll/kqueue instead." },
{ id:266, q:"What is the C10K problem?", a:"The C10K problem (circa 1999) refers to the challenge of handling 10,000 simultaneous connections on a web server efficiently.", exp:"Traditional thread-per-connection: 10K threads × stack memory = impractical. Solution: event-driven I/O (epoll/kqueue) with non-blocking sockets. One thread handles thousands of connections. Nginx, Node.js, and Go's runtime were designed around this. Now solved; modern servers handle C1M (million) connections." },
{ id:267, q:"What is a blocking vs non-blocking socket?", a:"Blocking socket: read/write blocks until data is available or written; non-blocking socket returns immediately with EAGAIN/EWOULDBLOCK if no data.", exp:"Blocking: simpler code, wastes thread while waiting. Non-blocking: efficient with event loop (epoll — only process FDs that are ready). Non-blocking I/O + epoll is the basis of high-performance servers. O_NONBLOCK flag set via fcntl()." },
{ id:268, q:"What is zero-copy I/O?", a:"Zero-copy I/O transfers data between devices and memory without copying it through the CPU, reducing overhead.", exp:"Traditional file send: disk→kernel buffer→user buffer→kernel socket buffer→NIC. With sendfile(): disk→kernel buffer→NIC (2 fewer copies, no user-kernel context switch). splice() and io_uring further optimize. Critical for high-throughput servers (Nginx, Kafka use sendfile)." },
{ id:269, q:"What is sendfile() system call?", a:"sendfile() is a Linux syscall that efficiently copies data from one file descriptor to another entirely in kernel space, avoiding user-space copies.", exp:"sendfile(out_fd, in_fd, offset, count) — typically socket and file FD. Kernel copies from page cache to socket buffer without user-space involvement. Also used to copy between files. Major performance improvement for web servers sending static files. sendmmsg() extends to multiple messages." },
{ id:270, q:"What is the difference between synchronous and asynchronous I/O?", a:"Synchronous I/O blocks the calling thread until the operation completes; asynchronous I/O allows the thread to continue while the operation proceeds in the background.", exp:"Sync: read() blocks until data arrives. Async: aio_read() returns immediately; completion notified via signal or callback. Async I/O is complex but enables high concurrency without threads. io_uring (Linux 5.1) provides a modern, efficient async I/O API." },
{ id:271, q:"What is the kernel's role in network I/O?", a:"The kernel manages network I/O through the network stack — handling protocol processing, buffering, socket management, and interfacing with NICs.", exp:"Application writes to socket → TCP/IP stack in kernel → NIC driver → hardware. Kernel manages: socket buffers (sk_buff), TCP state machines, congestion control, interrupt handling (NAPI for high-speed NICs). Kernel bypass (DPDK, RDMA) moves processing to user space for extreme performance." },
{ id:272, q:"What is a socket buffer (sk_buff) in Linux?", a:"sk_buff (socket buffer or skb) is the primary data structure for network packets in the Linux kernel network stack.", exp:"Contains: packet data (headroom+data+tailroom), protocol headers, metadata. Passed through network stack layers without copying data (pointer manipulation moves layer boundaries). Memory-efficient but complex. sk_buff size is crucial for network performance tuning." },
{ id:273, q:"What is NAPI (New API) in Linux networking?", a:"NAPI is a Linux interrupt mitigation technique that switches from interrupt-driven to polling mode during high packet rates.", exp:"At low rates: traditional interrupt per packet (low latency). At high rates: interrupt storms overwhelm CPU. NAPI: after first interrupt, disable and poll until budget consumed. Reduces interrupt overhead under load. Throttles receive rate to prevent CPU overload. All modern Linux NIC drivers use NAPI." },
{ id:274, q:"What is TCP segmentation offload (TSO)?", a:"TSO allows the NIC hardware to segment large TCP sends, reducing CPU overhead by sending larger chunks to the NIC.", exp:"Without TSO: kernel segments 1MB send into 1448-byte TCP segments (GSO=Generic Segmentation Offload in software). With TSO: kernel sends one large skb, NIC hardware segments it. Reduces CPU cycles for high-throughput TCP. Modern NICs support TSO, GSO used for software emulation." },
{ id:275, q:"What is IOMMU?", a:"IOMMU (Input-Output Memory Management Unit) provides memory protection for DMA by translating device addresses to physical addresses.", exp:"Without IOMMU: a compromised DMA device can access any physical memory. With IOMMU: each device has its own address space; the IOMMU enforces access limits. Also enables SR-IOV (hardware virtualization of PCIe devices). Essential for secure device passthrough in VMs." },
{ id:276, q:"What is the scheduler's quantum (time slice)?", a:"The scheduler's quantum is the maximum time a process can run before the CPU scheduler checks if preemption is needed.", exp:"Small quantum (1ms): responsive, high context switch overhead. Large quantum (100ms): less overhead, less responsive. Linux CFS doesn't use fixed quanta — it targets a 'scheduling latency' (6ms by default) divided among runnable tasks. Windows uses ~15ms quantum for foreground threads." },
{ id:277, q:"What is priority inversion?", a:"Priority inversion occurs when a high-priority process is blocked waiting for a resource held by a low-priority process, while medium-priority processes run instead.", exp:"Classic example: Mars Pathfinder reset (1997) — high-priority task waiting for bus mutex held by low-priority task, which was preempted by medium-priority task indefinitely. Solution: priority inheritance (low-priority process inherits high-priority while holding the resource). Priority ceiling protocol also solves it." },
{ id:278, q:"What is priority inheritance?", a:"Priority inheritance temporarily elevates the priority of a process holding a resource to match the highest-priority process waiting for that resource.", exp:"Prevents priority inversion. When HP waits for resource held by LP, LP's priority is raised to HP's level. When LP releases resource, priority reverts. pthread_mutexattr_setprotocol(PTHREAD_PRIO_INHERIT). Used in RTOS and Android to prevent priority inversion issues." },
{ id:279, q:"What is the ceiling priority protocol?", a:"The priority ceiling protocol assigns each mutex a ceiling priority equal to the highest priority of any process that may lock it, preventing priority inversion and deadlock.", exp:"A process can lock a mutex only if its priority > all ceilings of currently locked mutexes. Guarantees deadlock freedom (can't hold lower-ceiling lock while waiting for higher-ceiling one). More conservative than priority inheritance but provides stronger guarantees." },
{ id:280, q:"What is a real-time clock (RTC) vs system clock?", a:"RTC is battery-backed hardware that keeps time when the system is off; system clock is software maintained by the OS using timer interrupts from boot.", exp:"RTC: accurate but drifts, low resolution (1-second). On boot, OS reads RTC to initialize system time. System clock: maintained in memory, synchronized via NTP (Network Time Protocol) to correct drift. hwclock syncs between RTC and system clock. Monotonic clock doesn't change with NTP corrections." },
{ id:281, q:"What is NTP (Network Time Protocol)?", a:"NTP synchronizes computer clocks over a network to within milliseconds of a reference time server.", exp:"Hierarchical: stratum 0 (atomic clocks, GPS) → stratum 1 (servers directly synced) → stratum 2+ (clients synced to stratum above). NTP calculates network delay and clock offset, adjusts gradually (slewing) to avoid time jumps. ntpd or chrony daemon. Critical for distributed systems, logs, SSL certificates." },
{ id:282, q:"What is monotonic clock vs wall clock?", a:"Wall clock measures absolute real time; monotonic clock measures elapsed time since an unspecified point and never goes backward.", exp:"Wall clock can jump backward (NTP corrections, DST). Monotonic clock always increases. For measuring elapsed time (timeouts, profiling): use monotonic. For displaying to user/logs: use wall clock. POSIX: clock_gettime(CLOCK_MONOTONIC) vs CLOCK_REALTIME. Go's time.Now() vs time.Since()." },
{ id:283, q:"What is a high-resolution timer?", a:"A high-resolution timer provides sub-millisecond precision timing for time-sensitive applications.", exp:"Traditional kernel timers have ~1ms resolution (HZ=1000). POSIX high-res timer: clock_nanosleep(CLOCK_MONOTONIC). Linux hrtimer subsystem provides nanosecond-resolution timers. Critical for RTOS, audio, multimedia, and precision measurement applications. PREEMPT_RT improves timer accuracy." },
{ id:284, q:"What is the tickless kernel?", a:"A tickless kernel (CONFIG_NO_HZ) skips periodic timer interrupts when the CPU is idle, saving power.", exp:"Traditional kernel: timer fires HZ times/second even when idle (unnecessary wake-ups reduce sleep state quality). Dynamic ticks: next timer interrupt scheduled only when needed. Reduces power consumption significantly on idle CPUs. Critical for mobile (Android) and laptop battery life." },
{ id:285, q:"What is a power state (C-state)?", a:"C-states (CPU sleep states) are CPU low-power modes ranging from C0 (active) to deep sleep states (C6+) with increasing power savings and increasing wake-up latency.", exp:"C0: running. C1: halt (immediate wake). C1E: enhanced halt. C3/C6/C7: deep sleep, lower power, longer wake latency. OS manages C-state transitions via ACPI. Deep C-states save more power but add latency to wake. RTOS may limit C-states to reduce wake latency." },
{ id:286, q:"What is ACPI?", a:"Advanced Configuration and Power Interface (ACPI) is a standard for hardware device configuration and power management by the OS.", exp:"Defines tables (DSDT, SSDT) describing system hardware in AML bytecode. The OS ACPI driver interprets these. Manages: power states (S0-S5 system, C0-C6 CPU), thermal management, hardware device detection. Replaced APM. Linux uses kernel ACPI drivers; Windows has built-in ACPI support." },
{ id:287, q:"What is power management in OS?", a:"Power management reduces energy consumption through various strategies including CPU frequency scaling, sleep states, disk spin-down, and display dimming.", exp:"CPU: DVFS (Dynamic Voltage and Frequency Scaling) — lower freq = lower power. RAM: self-refresh mode. Disk: spin down when idle. Drivers request power states. The governor (ondemand, powersave, performance) controls CPU frequency. Critical for mobile and laptop battery life." },
{ id:288, q:"What is CPU frequency scaling (DVFS)?", a:"DVFS (Dynamic Voltage and Frequency Scaling) dynamically adjusts CPU frequency and voltage based on load, saving power at low load.", exp:"Linux cpufreq subsystem. Governors: performance (max freq), powersave (min freq), ondemand (scale to load), schedutil (CFS-integrated). Reducing frequency by 2× reduces power by 8× (power ∝ f × V² for CMOS). ARM big.LITTLE combines high-efficiency and high-performance cores." },
{ id:289, q:"What is CPU hotplug?", a:"CPU hotplug allows CPUs to be brought online or offline at runtime without rebooting, used for power management and hardware failure handling.", exp:"Linux: echo 0 > /sys/devices/system/cpu/cpu1/online (offline cpu1). When a CPU goes offline: its processes migrated, IRQ affinity updated, memory reconfigured. Used by mobile OS to power off cores at low load. Also handles hardware CPU failures in servers." },
{ id:290, q:"What is NUMA balancing?", a:"NUMA balancing (Linux AutoNUMA) automatically migrates processes and their memory pages to the same NUMA node to reduce remote memory accesses.", exp:"Linux periodically scans process memory pages, marks them as inaccessible, and records which NUMA node the fault comes from. If a process consistently faults on remote pages, the kernel migrates those pages to the local node. Trade-off: migration cost vs reduced latency." },
{ id:291, q:"What is the difference between /dev/urandom and /dev/random?", a:"/dev/random blocks when entropy pool is low; /dev/urandom never blocks and uses a CSPRNG fed by the entropy pool.", exp:"Entropy collected from hardware events (keystrokes, mouse, disk I/O). /dev/random (old behavior): blocks if entropy too low — can stall. /dev/urandom: always fast, uses ChaCha20 CSPRNG seeded from entropy pool. Linux 5.6+: /dev/random no longer blocks after boot initialization. Use /dev/urandom or getrandom() syscall." },
{ id:292, q:"What is getrandom() system call?", a:"getrandom() is a Linux system call that fills a buffer with cryptographically secure random bytes from the kernel's CSPRNG.", exp:"Advantages over /dev/urandom: blocks until CSPRNG is seeded (avoids early-boot randomness issues), atomic (unaffected by file descriptor limits), simpler. Added in Linux 3.17. OpenSSL, glibc use it. GRND_NONBLOCK flag returns EAGAIN if not yet seeded." },
{ id:293, q:"What is a namespace in Linux?", a:"Linux namespaces isolate system resources so processes in different namespaces have separate views of those resources.", exp:"Types: PID (isolated process trees), Network (separate network stack), Mount (separate filesystem view), UTS (separate hostname/domain), IPC (separate IPC resources), User (separate UID/GID mappings), Cgroup (separate cgroup hierarchy), Time (separate system time). Docker uses all except Time." },
{ id:294, q:"What is a PID namespace?", a:"A PID namespace creates an isolated process ID space where processes inside see themselves starting from PID 1, while the host OS uses different PIDs.", exp:"Process in PID namespace has two PIDs: one inside namespace (e.g., 1) and one outside (e.g., 12345). Used by containers — each container has its own init (PID 1). Nested PID namespaces possible. Created with CLONE_NEWPID flag or unshare -p." },
{ id:295, q:"What is a network namespace?", a:"A network namespace gives a process group its own network stack — separate interfaces, routing tables, iptables rules, and port space.", exp:"Containers use network namespaces for isolation. A veth (virtual Ethernet) pair connects namespace to host. Each namespace can have a full network stack. Docker creates a network namespace per container and connects with veth pairs through a bridge (docker0)." },
{ id:296, q:"What is chroot?", a:"chroot changes the apparent root directory for a process, restricting its file system view to a subtree.", exp:"chroot /jail starts a process that sees /jail as /. Cannot access files outside /jail. Predecessor to containers. Limitation: doesn't isolate processes, network, users — only filesystem. A privileged process can still escape. Full container security requires namespaces + cgroups." },
{ id:297, q:"What is seccomp?", a:"Seccomp (Secure Computing Mode) is a Linux kernel feature that restricts which system calls a process can make.", exp:"seccomp-bpf: specify allowed syscalls via BPF filter. On disallowed syscall: kill process (SECCOMP_RET_KILL), return error (SECCOMP_RET_ERRNO), or trap to handler (SECCOMP_RET_TRAP). Docker, Chrome, Android all use seccomp to limit attack surface. A compromised process can't escape via obscure syscalls." },
{ id:298, q:"What is capabilities in Linux?", a:"Linux capabilities divide root's privileges into distinct units that can be independently granted to processes, instead of all-or-nothing root access.", exp:"Examples: CAP_NET_BIND_SERVICE (bind ports <1024), CAP_SYS_PTRACE (ptrace), CAP_NET_RAW (raw sockets). Containers use capabilities to give specific privileges without full root. setuid programs can be replaced with capabilities (e.g., ping needs CAP_NET_RAW, not root)." },
{ id:299, q:"What is AppArmor?", a:"AppArmor is a Linux MAC (Mandatory Access Control) security module that confines programs to specific files, capabilities, and network access via profiles.", exp:"Profile-based: each program gets a profile defining allowed files, capabilities, network. Two modes: enforce (deny+log violations), complain (log only). Simpler than SELinux. Default in Ubuntu/Debian. Docker uses AppArmor profiles (docker-default) for container confinement." },
{ id:300, q:"What is a control group (cgroup) v2?", a:"cgroups v2 is the unified Linux cgroup hierarchy that provides resource limiting, prioritization, accounting, and control for process groups.", exp:"Unified hierarchy (vs v1's multiple hierarchies). Controllers: cpu (shares/quota/period), memory (limit, swap), io (weight, bps limit), pids (max count). Interface: /sys/fs/cgroup/. Kubernetes, Docker use cgroups to enforce container resource limits. systemd manages cgroups for services." },

// Section 16: Questions 301-400
{ id:301, q:"What is a file lock?", a:"A file lock prevents simultaneous conflicting access to a file by multiple processes.", exp:"POSIX locks: fcntl(F_SETLK) — advisory, per-process. BSD flock() — per-file-descriptor. Linux mandatory locks (rarely used). Advisory: processes cooperate by checking locks. Mandatory: kernel enforces. Databases use file locks for concurrent access control. Lock files (/var/run/*.pid) indicate running daemons." },
{ id:302, q:"What is the difference between advisory and mandatory file locking?", a:"Advisory locking relies on all processes voluntarily checking and respecting locks; mandatory locking is enforced by the kernel on all access.", exp:"Advisory (POSIX default): a process not using fcntl() can still read/write despite active lock — full cooperation needed. Mandatory (Linux: mount -o mand, setgid+no-execute bit): kernel blocks conflicting opens/reads/writes even from non-participating processes. Rarely used; can cause issues." },
{ id:303, q:"What is inotify?", a:"inotify is a Linux kernel subsystem that provides file system event monitoring — notifying applications when files/directories change.", exp:"Watch FDs created with inotify_create(). Add watches with inotify_add_watch() for events: IN_CREATE, IN_DELETE, IN_MODIFY, IN_CLOSE_WRITE. Used by IDEs (reload on change), build systems (make triggers), backup tools, antivirus. inotifywait command for shell scripts." },
{ id:304, q:"What is fanotify?", a:"fanotify is a Linux file system notification API that provides event notification and the ability to allow or deny access to files.", exp:"Unlike inotify (notification only), fanotify can grant/deny file access (file-access permission events). Used by antivirus scanners (scan before allowing open), file integrity monitoring. More powerful and complex than inotify. Requires CAP_SYS_ADMIN." },
{ id:305, q:"What is the difference between ext3 and ext4?", a:"ext4 is an improvement over ext3 with larger volume/file sizes, extents, delayed allocation, multiblock allocation, and faster fsck.", exp:"ext4 improvements: max volume 1EB (vs 16TB), max file 16TB (vs 2TB), extents (contiguous ranges) replace indirect blocks (faster large files), delayed allocation reduces fragmentation, faster journal checksum, dir_index (htree) improves large directory performance, faster e2fsck." },
{ id:306, q:"What is an extent in file systems?", a:"An extent is a contiguous range of blocks described by (start_block, length), replacing the traditional block pointer lists for efficient large file handling.", exp:"Traditional: each 4KB block needs a separate pointer (1TB file = 256M pointers). Extents: a contiguous 1TB file needs ONE extent descriptor. ext4, XFS, Btrfs, NTFS use extents. Reduces metadata overhead and fragmentation. Random writes still fragment; defrag tool consolidates." },
{ id:307, q:"What is XFS?", a:"XFS is a high-performance 64-bit journaling file system developed by SGI, known for excellent parallelism and large file performance.", exp:"Features: extent-based allocation, B-tree indexed allocation groups for parallelism, delayed allocation, 64-bit addressing (8EB max). Excellent for large files and high-throughput workloads. Default FS for RHEL 7+. xfs_repair for recovery, xfs_freeze for snapshots. No online shrinking." },
{ id:308, q:"What is Btrfs?", a:"Btrfs (B-tree file system) is a modern Linux copy-on-write (COW) file system with built-in RAID, snapshots, compression, and deduplication.", exp:"COW: writes go to new locations, old data preserved (enables snapshots). Snapshots: instant, space-efficient. RAID 0/1/5/6/10 built-in. Online resize, defrag, balance. Transparent compression (zlib, zstd, lzo). Still maturing — RAID 5/6 not production-ready. Used in openSUSE, Fedora by default." },
{ id:309, q:"What is ZFS?", a:"ZFS is an advanced file system and logical volume manager with integrated RAID-Z, checksums, snapshots, deduplication, and self-healing.", exp:"Originally Sun/Solaris, ported to Linux (OpenZFS). Features: 128-bit addressing, end-to-end checksums (detects/repairs bit rot), RAID-Z (software RAID), snapshots, clones, ARC (adaptive replacement cache), deduplication. Robust for NAS/storage servers. OpenZFS on Linux via DKMS module." },
{ id:310, q:"What is copy-on-write file system?", a:"A COW file system never modifies data in-place; writes create new copies, preserving old data until explicitly discarded.", exp:"Benefits: atomic writes (always consistent), instant snapshots (just save block map), no write holes. Btrfs, ZFS, APFS use COW. Downside: write amplification (need to update metadata tree), fragmentation over time. Snapshots are free space-efficient — only store changed blocks." },
{ id:311, q:"What is a snapshot in file systems?", a:"A snapshot is a point-in-time view of a file system, capturing its state at a moment for backup or rollback.", exp:"With COW: snapshot is instant and space-efficient (shares unchanged blocks with live FS). Traditional snapshot: requires full copy or redirect-on-write. LVM snapshots, Btrfs snapshots, ZFS snapshots. Used for backup, VM state saves, database backup consistency." },
{ id:312, q:"What is deduplication in storage?", a:"Deduplication identifies and eliminates duplicate data blocks, storing only one copy and referencing it multiple times.", exp:"Inline dedup: detect during write (CPU overhead but immediate savings). Post-process dedup: runs after write (less latency impact). ZFS/Btrfs dedup uses hash tables. Benefit: 30–80% space savings for VMs, backups. Cost: requires large RAM for dedup tables." },
{ id:313, q:"What is data compression in file systems?", a:"File system compression transparently compresses file data before writing to disk, saving space with minimal application changes.", exp:"Btrfs supports zlib (best ratio), lzo (fastest), zstd (balanced). ZFS supports lz4, gzip, zstd. Compression ratio depends on data (text compresses 3–10×, already compressed data like JPEG gains nothing). CPU overhead usually outweighed by reduced I/O. Improves performance on CPU-bound systems with fast disks." },
{ id:314, q:"What is POSIX file locking semantics?", a:"POSIX file locks (fcntl) are advisory, per-process, byte-range locks that are inherited by fork but released when any FD to the file is closed.", exp:"The 'close on any FD' semantic is tricky: if process opens file twice, locking via fd1 and closing fd2 releases the lock (counterintuitive!). Linux OFD (Open File Description) locks (F_OFD_SETLK) fix this — per-FD not per-process. Important for databases and NFS locking correctness." },
{ id:315, q:"What is the difference between block and character devices in Linux?", a:"Block devices (disks) support random access in fixed-size blocks and use a buffer cache; character devices support sequential byte access directly.", exp:"/dev/sda (block), /dev/tty (character), /dev/null (character). Block devices: can be formatted with file systems, go through buffer cache. Character devices: direct access, no caching, used for terminals, serial ports, audio. In stat output: 'b' for block, 'c' for character." },
{ id:316, q:"What is devtmpfs?", a:"devtmpfs is a virtual filesystem that automatically populates /dev with device nodes managed by the kernel, replacing static /dev.", exp:"The kernel populates device nodes automatically as devices are detected. udev then applies naming rules and permissions. On boot: kernel mounts devtmpfs to /dev early, populating it with initial devices. This eliminates need for pre-created static device files and supports hotplug." },
{ id:317, q:"What is udev?", a:"udev is the Linux device manager that dynamically creates/removes device files in /dev, handles firmware loading, and applies persistent naming rules.", exp:"Runs in userspace. Listens to kernel uevent notifications. Rules in /etc/udev/rules.d/ define device naming, permissions, symlinks. Enables persistent device names (e.g., /dev/disk/by-id/) regardless of detection order. Integrated with systemd as systemd-udevd." },
{ id:318, q:"What is sysfs?", a:"sysfs (/sys) is a virtual filesystem exporting kernel objects (devices, drivers, buses) as files, enabling userspace to read/write kernel attributes.", exp:"Each kernel object (device, driver, module) has a directory in sysfs. Attributes are read/written as files. Used by udev, power management tools, CPU frequency governors. Examples: /sys/class/net/eth0 (network interfaces), /sys/devices/system/cpu/cpu0 (CPU info)." },
{ id:319, q:"What is procfs?", a:"procfs (/proc) is a virtual filesystem providing a kernel and process information interface to userspace.", exp:"Per-process info: /proc/PID/ (status, maps, fd/, cmdline, environ). System info: /proc/cpuinfo, /proc/meminfo, /proc/net/, /proc/sys/ (tunable kernel parameters). /proc/sys/vm/swappiness, /proc/sys/net/ipv4/*. Writable entries allow kernel tuning (sysctl)." },
{ id:320, q:"What is sysctl?", a:"sysctl is an interface for reading and modifying kernel parameters at runtime via /proc/sys/ hierarchy.", exp:"sysctl -w net.ipv4.ip_forward=1 (enable IP forwarding). Persistent settings in /etc/sysctl.conf or /etc/sysctl.d/. Key parameters: vm.swappiness (swap tendency), net.core.somaxconn (listen backlog), kernel.pid_max (max PIDs), vm.overcommit_memory. Critical for performance tuning." },
{ id:321, q:"What is the Linux boot sequence in detail?", a:"BIOS/UEFI → bootloader (GRUB) → kernel decompression → kernel init → driver init → mount root FS → init/systemd → services → login.", exp:"1) BIOS POST + boot device selection. 2) GRUB loads kernel+initramfs. 3) Kernel decompresses itself. 4) Kernel detects hardware, loads drivers. 5) Mounts initramfs as temporary root. 6) initramfs finds real root device. 7) Pivot to real root. 8) Exec /sbin/init or systemd. 9) systemd starts units in dependency order." },
{ id:322, q:"What is initramfs/initrd?", a:"initramfs is a minimal temporary filesystem loaded into memory at boot, used to mount the real root filesystem.", exp:"The kernel can't mount real root if drivers (disk controllers, crypto for encrypted disks, LVM, RAID) aren't loaded. initramfs provides a minimal init environment with necessary modules. After real root is mounted, init is replaced (pivot_root or switch_root) with the real one." },
{ id:323, q:"What is the difference between initrd and initramfs?", a:"initrd is a block device image mounted as a RAM disk; initramfs is a cpio archive extracted directly into ramfs, simpler and more flexible.", exp:"initrd: kernel mounts it as block device, requires pivot_root. initramfs: kernel extracts cpio directly to rootfs (tmpfs), uses switch_root. initramfs is the modern approach — no block device overhead, no pivot_root needed, easier to create. mkinitramfs/dracut create it." },
{ id:324, q:"What is dracut?", a:"dracut is a framework for generating initramfs images that support modular hooks for different boot scenarios (LVM, RAID, encrypted disks, network boot).", exp:"Used in RHEL/Fedora/openSUSE. Module-based: each feature (lvm, crypt, network, NFS) is a module. dracut -f regenerates initramfs. Contrast with mkinitramfs (Debian/Ubuntu). Supports emergency shell, shutdown hooks, and network PXE boot." },
{ id:325, q:"What is PXE (Preboot Execution Environment)?", a:"PXE enables computers to boot over a network by downloading a bootloader and OS from a server instead of local storage.", exp:"BIOS/UEFI gets IP via DHCP, TFTP downloads bootloader. Bootloader downloads kernel+initramfs. initramfs mounts root via NFS, iSCSI, or HTTP. Used for diskless workstations, OS deployment (imaging), network recovery. Standard in enterprise IT for automated provisioning." },
{ id:326, q:"What is GPT (GUID Partition Table)?", a:"GPT is a modern disk partitioning scheme that supports disks >2TB, up to 128 partitions, and includes checksums and backup partition table.", exp:"Replaces MBR (limited to 2TB, 4 primary partitions). GPT uses 128-bit GUIDs for partition identification. Header and partition entries are checksummed. Backup GPT at end of disk. Required for UEFI boot. gdisk/parted manage GPT. MBR kept for compatibility (Protective MBR)." },
{ id:327, q:"What is LVM (Logical Volume Manager)?", a:"LVM provides a layer of abstraction over physical storage, allowing flexible management of logical volumes independent of physical disk layout.", exp:"Physical Volumes (PVs, physical disks/partitions) → Volume Groups (VGs, pools of storage) → Logical Volumes (LVs, virtual partitions). Benefits: online resize, snapshots, RAID, migration between disks. Commands: pvcreate, vgcreate, lvcreate, lvextend, lvreduce." },
{ id:328, q:"What is LVM thin provisioning?", a:"LVM thin provisioning creates logical volumes larger than available space, allocating real space only as data is written.", exp:"A thin pool allocates blocks on demand. Multiple VMs/containers can share a pool without pre-allocating full disk space. Space-efficient snapshots (only changed blocks). Risk: pool runs out if actual usage exceeds physical space. Used by Docker's devicemapper storage driver." },
{ id:329, q:"What is iSCSI?", a:"iSCSI is a network protocol that transports SCSI storage commands over TCP/IP, enabling servers to use remote block storage as if it were local.", exp:"iSCSI initiator (client) connects to iSCSI target (storage server) over network. Appears as a local block device (/dev/sdX). Used in SANs for server storage. CHAP authentication, IPsec encryption. Competes with Fibre Channel (FC). Linux: open-iscsi initiator, tgtd target daemon." },
{ id:330, q:"What is NFS (Network File System)?", a:"NFS is a distributed file system protocol allowing clients to access files on remote servers as if they were local.", exp:"Server exports directories; clients mount them. NFSv4 added security (Kerberos), stateful protocol, better performance. Linux: nfs-utils package; /etc/exports for server config. Mount: mount -t nfs server:/path /mnt. Drawbacks: latency, disconnected operation limitations, POSIX compliance issues." },
{ id:331, q:"What is SMB/CIFS?", a:"SMB (Server Message Block) / CIFS is a network file sharing protocol primarily used by Windows for file, printer, and named pipe sharing.", exp:"SMB2/SMB3 are modern versions with better performance and security. Linux Samba implements SMB server and client. Used for Windows file shares, NAS devices (Synology, QNAP). smbclient for CLI access, CIFS filesystem driver (//server/share) for mounting." },
{ id:332, q:"What is a union file system?", a:"A union file system merges multiple directories into a single virtual view, with upper layers overriding lower ones on a copy-on-write basis.", exp:"OverlayFS (Linux kernel): lower layer (read-only base), upper layer (read-write changes), work dir. Reads: lower layer if not in upper. Writes: copy to upper layer first (copy-on-write). Docker uses OverlayFS for layers — base image (lower) + container layer (upper). Also: AUFS, UnionFS." },
{ id:333, q:"What is OverlayFS?", a:"OverlayFS is a Linux union filesystem that overlays one directory tree (upper) on another (lower), presenting a merged view with copy-on-write semantics.", exp:"Docker's default storage driver. Base image layers are lower (read-only). Container layer is upper (read-write). Changes to read-only files are copied to upper layer first. Efficient: no actual copy until modification. Multiple containers share same base image lower layers." },
{ id:334, q:"What is a tmpfs?", a:"tmpfs is a virtual memory filesystem that stores files in RAM (and swap), providing extremely fast storage for temporary data.", exp:"Size is dynamic (grows/shrinks with usage). Data lost on unmount/reboot. Mounted by default at /tmp, /dev/shm, /run. /dev/shm used for POSIX shared memory. tmpfs automatically uses swap when RAM is insufficient. Faster than any disk-based FS for temporary files." },
{ id:335, q:"What is ramfs vs tmpfs?", a:"ramfs is an older simple RAM-based filesystem with no swap support or size limit; tmpfs adds size limits and swap backing.", exp:"ramfs: can grow until system runs out of memory (dangerous — no limits). tmpfs: can be limited with size= mount option, pages can be swapped out. tmpfs is always preferred. ramfs historically used for initrd. Both backed by kernel page cache but tmpfs has better management." },
{ id:336, q:"What is the difference between hard disk formatting and file system creation?", a:"Low-level formatting writes sector structure; partitioning divides disk into logical areas; high-level formatting (mkfs) creates a file system on a partition.", exp:"Low-level format: done at factory; writes sector headers, error correction. Partitioning (fdisk/gdisk): creates partition table. mkfs.ext4/mkfs.xfs: creates FS structures (superblock, inode table, block groups). Users typically only do mkfs. 'Quick format' (Windows) only recreates FS metadata, not overwriting data." },
{ id:337, q:"What is the superblock in a file system?", a:"The superblock is a critical data structure containing essential metadata about the entire file system — its type, size, block size, free space, and state.", exp:"Stored near the beginning of the partition (and in backup locations). Contains: magic number (FS type), block count, free blocks, inode count, free inodes, last mount time, last write time, FS state (clean/dirty). Corruption = unreadable FS. e2fsck reads it to check/repair ext4." },
{ id:338, q:"What is fsck?", a:"fsck (file system check) is a utility that checks and repairs file system consistency after a crash or error.", exp:"Runs automatically at boot if FS was not cleanly unmounted (dirty bit set) or after a certain number of mounts. For ext4: e2fsck -f /dev/sda1. For xfs: xfs_repair. Should not run on mounted FS (except xfs_repair online). Journaling reduces the need for full fsck scans." },
{ id:339, q:"What is the difference between sync and fsync?", a:"sync flushes all dirty buffers for all files system-wide; fsync(fd) ensures a specific file's data and metadata are durable on disk.", exp:"write() → kernel page cache → (periodic) flush to disk. fsync(fd) forces immediate flush to physical disk (important for crash consistency). fdatasync() flushes data only (not metadata — faster). sync() flushes everything. Databases must fsync after commit to guarantee durability." },
{ id:340, q:"What is write-back caching?", a:"Write-back caching holds dirty pages in memory and writes them to disk asynchronously, improving write performance at the cost of potential data loss on crash.", exp:"Opposite: write-through (write to disk immediately, slower). Linux uses write-back by default. Dirty pages flushed when: page cache pressure, dirty_ratio exceeded, periodic flusher (pdflush/flusher threads). Risk: crash before flush = data loss. Mitigated by journaling and fsync." },
{ id:341, q:"What is the difference between ext4 ordered and writeback journal mode?", a:"In ordered mode, data is written before metadata journal entry; in writeback, metadata journaled but data writes may be reordered arbitrarily.", exp:"Data journal (safest): both data and metadata in journal. Ordered (default): data written to disk first, then metadata journaled — no old data appears in new files after crash. Writeback (fastest): only metadata journaled, data may be stale — possible to see garbage in new file regions after crash." },
{ id:342, q:"What is the difference between mount and bind mount?", a:"Regular mount attaches a device/filesystem; bind mount attaches a directory from one location to another in the namespace.", exp:"mount /dev/sda1 /mnt: mounts device. mount --bind /src /dst: makes /src accessible at /dst too (same filesystem, same data). Used in chroot setup, containers, namespace isolation. Changes in either location are reflected in both (same inodes). --rbind includes subdirectory mounts." },
{ id:343, q:"What is a loopback device?", a:"A loopback (loop) device maps a regular file as a block device, allowing file system images to be mounted as if they were disk partitions.", exp:"losetup /dev/loop0 disk.img; mount /dev/loop0 /mnt. Allows creating and mounting ISO files, VM disk images. Used by snap packages (each .snap is squashfs mounted via loop). Linux auto-creates loop devices for mount -o loop. Max devices controlled by max_loop parameter." },
{ id:344, q:"What is squashfs?", a:"SquashFS is a read-only compressed file system commonly used for live CDs, embedded systems, and Linux snap packages.", exp:"Compressed with gzip, lzo, lz4, zstd, xz. Read-only — perfect for immutable content like OS images. mksquashfs creates, unsquashfs extracts. Used in: Ubuntu live ISO, OpenWrt firmware, Snap packages (/snap/), Docker build layers. Low memory footprint, decompresses on-demand." },
{ id:345, q:"What is FUSE (Filesystem in Userspace)?", a:"FUSE allows non-root users to implement file systems in userspace without modifying kernel code.", exp:"A FUSE daemon handles filesystem operations; the FUSE kernel module forwards VFS calls to it via /dev/fuse. Examples: sshfs (mount remote files over SSH), s3fs (mount S3 bucket), encfs (encrypted FS), ntfs-3g (NTFS on Linux). Lower performance than in-kernel FS but more flexible and safer." },
{ id:346, q:"What is NVMe?", a:"NVMe (Non-Volatile Memory Express) is a host controller interface and storage protocol designed for SSDs connecting via PCIe.", exp:"Legacy SSDs used SATA/AHCI (designed for spinning disks, 1 queue, 32 commands). NVMe: up to 65,535 queues × 65,535 commands — designed for flash parallelism. Much lower latency (μs vs ms). NVMe SSDs plug into PCIe slots or M.2 connectors. Read: 3–7 GB/s vs SATA's 600MB/s." },
{ id:347, q:"What is SCSI and its relevance to modern storage?", a:"SCSI (Small Computer System Interface) is a standard for connecting storage devices; its command set (SCSI commands) remains the dominant storage abstraction even for modern SAS, iSCSI, and NVMe.", exp:"Physical SCSI replaced by SAS (Serial Attached SCSI) for enterprise, iSCSI over network, virtio-scsi in VMs. The SCSI command set (READ(10), WRITE(10), INQUIRY) underlies Linux's SCSI subsystem which abstracts all block devices. lsscsi lists SCSI devices." },
{ id:348, q:"What is I/O scheduler in Linux?", a:"The Linux I/O scheduler orders block device requests to improve throughput and reduce latency, operating between the VFS and block device driver.", exp:"Schedulers: noop/none (FIFO, for fast SSDs/NVMe), deadline/mq-deadline (minimizes starvation, good for real-time), CFQ/bfq (fair queuing per process, good for desktops), kyber (low-latency for fast SSDs). Set per device: echo mq-deadline > /sys/block/sda/queue/scheduler." },
{ id:349, q:"What is CFQ (Completely Fair Queuing) I/O scheduler?", a:"CFQ is a Linux I/O scheduler that allocates time slices to each process's I/O requests fairly, preventing starvation and improving interactivity.", exp:"Each process gets an I/O queue with a time slice. Disk-access pattern classified (sequential vs random). Groups with lower I/O get priority. Good for desktop systems with mixed workloads. Replaced by BFQ (Budget Fair Queuing) in modern Linux, which also considers I/O size budgets." },
{ id:350, q:"What is the Multi-Queue Block Layer (blk-mq)?", a:"blk-mq is the modern Linux block I/O framework with multiple submission queues mapped to CPU cores, replacing the single-queue approach for NVMe and fast SSDs.", exp:"Old block layer: single lock, single queue — bottleneck for fast SSDs. blk-mq: per-CPU software queues → multiple hardware queues (NVMe supports up to 65K). Lock-free submission, much higher IOPS. All modern schedulers (mq-deadline, kyber, bfq) work on top of blk-mq." },

// Section 17: More questions 351-450
{ id:351, q:"What is a block group in ext4?", a:"ext4 divides the disk into block groups, each containing a superblock copy, group descriptors, data bitmap, inode bitmap, inode table, and data blocks.", exp:"Keeps inode and its data blocks nearby (reduces seek time). Block group size = 8 × block size (32MB for 4KB blocks). The allocator tries to keep related files in the same block group. Backup superblocks in groups 1, 3, 5, 7... provide recovery options." },
{ id:352, q:"What is the difference between metadata and data in a file system?", a:"Data is the file content; metadata is information about the file — name, size, permissions, timestamps, location of data blocks.", exp:"Metadata: inode (size, permissions, timestamps, block pointers), directory entries (filename → inode). Data: actual file bytes. File systems journal metadata by default (performance). Journaling data too (data=journal mode) is slower but safer. Applications must fsync to guarantee data durability." },
{ id:353, q:"What is disk striping?", a:"Disk striping (RAID 0) distributes data across multiple disks in fixed-size chunks, allowing parallel reads and writes for improved performance.", exp:"4KB stripe written across N disks: each disk gets 4KB/N stripe unit. Read/write throughput scales with number of disks. No redundancy: any disk failure = data loss. Used for temporary/scratch data, swap, where performance > durability. RAID 10 adds mirroring to striping." },
{ id:354, q:"What is RAID 5 in detail?", a:"RAID 5 stripes data across N disks with distributed parity, allowing single-disk fault tolerance with better space efficiency than RAID 1.", exp:"N disks: (N-1) effective capacity. Parity block rotated across drives. Can survive 1 disk failure: rebuild by XORing remaining disks. Write penalty: read-modify-write for parity update. Minimum 3 disks. Rebuild time risks second failure. RAID 6 adds second parity for 2-disk tolerance." },
{ id:355, q:"What is the write hole in RAID 5?", a:"The write hole is a RAID 5 vulnerability where a power failure during a write leaves data and parity inconsistent, potentially corrupting data on rebuild.", exp:"RAID 5 must update data stripe and parity. If power fails between these writes: data or parity might be updated but not both → inconsistent. On rebuild after disk failure, incorrect parity could reconstruct wrong data. Solutions: write-ahead journal (ZFS RAID-Z avoids this with its COW design)." },
{ id:356, q:"What is the role of the OS in CPU management?", a:"The OS manages CPU usage through scheduling, deciding which process gets CPU time, for how long, and on which core, while also handling exceptions and interrupts.", exp:"CPU management includes: process/thread scheduling (policy + mechanism), context switching, interrupt handling, exception handling, CPU power management (frequency scaling, C-states), CPU affinity and NUMA topology management, performance monitoring via PMCs." },
{ id:357, q:"What is the overhead of a system call?", a:"A system call involves mode switch (user→kernel), argument validation, kernel work, and return mode switch — typically 100–1000 nanoseconds.", exp:"Steps: trap instruction, save user registers, switch to kernel stack, look up syscall table, execute handler, restore registers, switch back to user mode, return. KPTI adds TLB flush overhead. Expensive for latency-critical code. Mitigation: vDSO (virtual dynamic shared object) for simple syscalls (gettimeofday) done in userspace." },
{ id:358, q:"What is vDSO (Virtual Dynamic Shared Object)?", a:"vDSO is a small shared library mapped into process address space by the kernel to provide fast implementations of certain syscalls without mode switching.", exp:"Functions like gettimeofday(), clock_gettime(), getcpu() are called millions/second — full syscall overhead unacceptable. vDSO maps read-only kernel data (timekeeping, CPU number) into user address space. clock_gettime(CLOCK_REALTIME) reads directly from vDSO — 10ns instead of 100ns syscall." },
{ id:359, q:"What is the difference between a driver and a firmware?", a:"A driver is OS software that controls a device; firmware is software embedded in the device itself that implements the device's own logic.", exp:"Driver (OS side): translates OS commands (read/write) to device-specific protocol. Firmware (device side): runs on device's microcontroller, implements device behavior. Example for NVMe SSD: Linux nvme.ko driver handles OS interface; SSD firmware handles wear leveling, garbage collection, error correction inside the device." },
{ id:360, q:"What is an IRQ (Interrupt Request)?", a:"An IRQ is a hardware signal from a device to the CPU requesting immediate attention (service).", exp:"Each device has an IRQ number (PIC/APIC). Keyboard: IRQ 1, Timer: IRQ 0, Network: IRQ 9 (varies). When device fires IRQ, CPU finishes current instruction, saves state, jumps to interrupt handler. /proc/interrupts shows IRQ counters. MSI (Message Signaled Interrupts) — PCIe devices use memory writes instead of physical IRQ lines." },
{ id:361, q:"What is the difference between a hard interrupt and a soft interrupt?", a:"A hard interrupt (hardware IRQ) is triggered by hardware devices; a soft interrupt (softirq) is triggered by software to defer work from hardware interrupt context.", exp:"Hard IRQ: hardware raises interrupt line → CPU runs ISR with interrupts (partially) disabled — must be very fast. Soft IRQ: deferred work (NET_RX, BLOCK, TIMER) runs after hard IRQ returns with interrupts enabled — can do more work. This two-level interrupt handling keeps hard IRQ latency low." },
{ id:362, q:"What is interrupt coalescing?", a:"Interrupt coalescing (IRQ moderation) delays raising interrupts until multiple events have occurred or a timeout expires, reducing interrupt rate.", exp:"High-speed NICs can generate millions of interrupts/second — overwhelms CPU. Coalescing: wait for N packets or T microseconds before interrupting. Trade-off: higher throughput (fewer interrupts) vs higher latency (delayed notification). ethtool -C eth0 rx-usecs 50 rx-frames 64 sets coalescing parameters." },
{ id:363, q:"What is the difference between process isolation and sandboxing?", a:"Process isolation prevents processes from accessing each other's memory via OS mechanisms; sandboxing additionally restricts which system calls and resources a process can access.", exp:"Process isolation: virtual address spaces, kernel mode protection. Sandboxing (stronger): seccomp (restrict syscalls), namespaces (restrict resource visibility), cgroups (limit resource usage), AppArmor/SELinux (MAC). Chrome: each tab is sandboxed. Docker: containerization is sandboxing via namespaces+cgroups." },
{ id:364, q:"What is the difference between a trusted and untrusted execution environment?", a:"A trusted execution environment (TEE) is an isolated secure enclave where sensitive code/data are protected from the main OS; untrusted environment is the normal OS.", exp:"TEE examples: Intel SGX (enclave memory encrypted, inaccessible to OS), ARM TrustZone (two worlds: secure/normal). Used for key storage, DRM, biometric data. Even a compromised OS can't read SGX enclave memory. Trade-off: limited functionality, complex programming model." },
{ id:365, q:"What is SGX (Software Guard Extensions)?", a:"Intel SGX allows user-space applications to create enclaves — isolated memory regions that are encrypted and inaccessible to the OS, hypervisor, or other processes.", exp:"Enclave memory (EPC) is encrypted with a hardware key. Even root/hypervisor cannot read it. Used for confidential computing, key management, DRM. Attack: Spectre-like side channels (SGAxe, LVI attacks). Deprecated in consumer Intel CPUs after security issues. AMD SEV-SNP offers similar for VMs." },
{ id:366, q:"What is AMD SEV (Secure Encrypted Virtualization)?", a:"AMD SEV encrypts VM memory with keys managed by the AMD Secure Processor, preventing the hypervisor from accessing guest VM memory.", exp:"SEV: per-VM encryption key, protects from hypervisor. SEV-ES: encrypts CPU registers on VM exit. SEV-SNP: adds integrity protection against hypervisor memory remapping. Used for confidential cloud computing — cloud provider can't read tenant's VM memory. AMD EPYC server CPUs support SEV." },
{ id:367, q:"What is a hypervisor type 1 vs type 2?", a:"Type 1 (bare-metal) hypervisor runs directly on hardware; Type 2 (hosted) hypervisor runs on top of a host OS.", exp:"Type 1: VMware ESXi, Microsoft Hyper-V, Xen, KVM (technically hybrid — Linux kernel IS the hypervisor). Direct hardware access: better performance. Used in data centers. Type 2: VMware Workstation, VirtualBox, QEMU. Runs as process in host OS. Easier to use, lower performance. Good for development." },
{ id:368, q:"What is KVM (Kernel-based Virtual Machine)?", a:"KVM is a Linux kernel module that turns Linux into a bare-metal hypervisor, allowing hardware-accelerated VMs using Intel VT-x/AMD-V.", exp:"KVM: /dev/kvm device, Linux manages VMs as processes (qemu-kvm). VMs use hardware virtualization (VT-x/AMD-V) for near-native CPU performance. Linux for VM scheduling, memory management. QEMU provides device emulation. Used by OpenStack, oVirt, Proxmox. Performance close to Type 1." },
{ id:369, q:"What is hardware virtualization (VT-x/AMD-V)?", a:"Hardware virtualization adds CPU instructions (VMENTER/VMEXIT on Intel VT-x) that efficiently switch between host and guest OS contexts with hardware support.", exp:"Without HW virt: hypervisor must trap and emulate privileged instructions (slow). With VT-x/AMD-V: guest OS runs at hardware speed; only truly privileged operations trigger VM exits. Extended Page Tables (EPT) provide hardware-accelerated nested paging for guest→physical address translation." },
{ id:370, q:"What is para-virtualization?", a:"Para-virtualization modifies the guest OS to use hypercalls instead of hardware instructions, improving VM performance by avoiding expensive hardware emulation.", exp:"Full virtualization: unmodified guest OS, full emulation of hardware — compatible but slow. Para-virtualization: guest OS calls hypervisor (hypercall) instead of hardware instruction — faster but requires guest modification. Xen para-virtualized drivers, virtio (Linux paravirt device standard)." },
{ id:371, q:"What is virtio?", a:"virtio is a standard for paravirtualized I/O devices in virtual machines, providing efficient network, disk, and other device access without full hardware emulation.", exp:"Virtual NIC (virtio-net), virtual disk (virtio-blk), random number generator (virtio-rng). Guest driver communicates via virtio protocol (ring buffers in shared memory) rather than emulating real hardware. Much faster than emulated e1000 NIC or IDE disk. Used by KVM, Xen, and cloud hypervisors." },
{ id:372, q:"What is live migration of VMs?", a:"Live migration moves a running VM from one physical host to another with minimal downtime by copying memory pages while the VM continues running.", exp:"Process: 1) Pre-copy: iteratively copy dirty pages to destination. 2) Suspend: briefly stop VM when change rate is low. 3) Copy final pages + CPU state. 4) Resume on destination. Downtime: milliseconds to seconds. Used for host maintenance, load balancing. Requires shared or replicated storage (NFS, Ceph)." },
{ id:373, q:"What is memory ballooning in VMs?", a:"Memory ballooning allows the hypervisor to reclaim RAM from a guest VM dynamically using a balloon driver inside the guest.", exp:"Hypervisor inflates balloon: guest driver allocates and pins RAM, effectively giving it back to host. Guest uses less actual RAM. Used for VM memory overcommit on the hypervisor — total VM RAM can exceed host RAM. VMware Tools and virtio-balloon implement this. VMs may swap to compensate for balloon inflation." },
{ id:374, q:"What is CPU steal time?", a:"CPU steal time is the percentage of time a VM's virtual CPU is ready to run but waiting because the hypervisor gave the physical CPU to another VM.", exp:"High steal time means the VM is CPU-starved by hypervisor overcommit. Visible in top output ('%st' column). Affects latency-sensitive applications. Indicates host is over-provisioned. Solutions: reduce VM density, move to less-loaded host, or use CPU reservations/limits in the hypervisor." },
{ id:375, q:"What is QEMU?", a:"QEMU is an open-source machine emulator and virtualizer that can emulate various CPU architectures and hardware devices.", exp:"Two modes: full system emulation (emulates entire computer, any arch), user-mode emulation (run foreign binaries, e.g., ARM binary on x86). When combined with KVM: hardware-accelerated same-arch virtualization. QEMU provides device emulation (virtio, emulated NIC, disk) while KVM handles CPU/memory virtualization." },
{ id:376, q:"What is a memory leak?", a:"A memory leak occurs when a program repeatedly allocates memory but fails to free it, causing progressively increasing memory usage until exhausted.", exp:"In C: malloc without free. In C++: new without delete. Java/GC languages: objects referenced longer than needed (logical leak). Detection: Valgrind, AddressSanitizer. Memory profilers: heaptrack, massif. Long-running processes (daemons, servers) most affected. OOM killer eventually kills the leaking process." },
{ id:377, q:"What is use-after-free?", a:"Use-after-free is a memory error where a program accesses heap memory after it has been freed, causing undefined behavior, crashes, or security vulnerabilities.", exp:"Freed memory may be reallocated. Accessing it reads another object's data (data corruption) or an attacker's planted data (exploit). Defenses: AddressSanitizer (marks freed memory as poisoned), memory safe languages (Rust, Java). Leading source of browser and kernel security vulnerabilities." },
{ id:378, q:"What is stack smashing?", a:"Stack smashing is a buffer overflow attack that overwrites adjacent stack memory, typically overwriting the function return address to redirect execution.", exp:"A local buffer overflow writes beyond the buffer into the saved return address on the stack. When the function returns, it jumps to the attacker's code. Defenses: stack canaries (StackGuard), ASLR, safe functions (strncpy instead of strcpy), GCC -fstack-protector, shadow stacks (Intel CET)." },
{ id:379, q:"What is heap spraying?", a:"Heap spraying is an exploit technique that fills large amounts of heap memory with shellcode and NOP sleds, increasing the probability of a controlled jump landing in the exploit.", exp:"Attacker uses JavaScript/Flash to allocate many heap objects containing the payload. With ASLR, exact heap address is unknown, but with enough spraying, a range is covered. NOP sled slides into shellcode. Defenses: ASLR, heap address randomization, JIT randomization." },
{ id:380, q:"What is return-oriented programming (ROP)?", a:"ROP is an exploit technique that chains existing code fragments ('gadgets') ending in RET instructions to perform arbitrary computation without injecting new code.", exp:"DEP/NX prevents executing injected code. ROP bypasses this by reusing existing code. Gadgets: short instruction sequences in executable memory. Chained via stack frames. Defenses: Control Flow Integrity (CFI) restricts valid RET targets, shadow stacks, ASLR. Very common in modern exploits." },
{ id:381, q:"What is Control Flow Integrity (CFI)?", a:"CFI is a security technique that restricts the set of valid targets for indirect calls and returns, preventing ROP and code-reuse attacks.", exp:"Forward-edge CFI (indirect calls): check that target is a valid function with compatible signature. Backward-edge CFI (returns): shadow stack ensures RET goes to actual call site. Intel CET provides hardware shadow stack. LLVM CFI, Microsoft CIG (Control Guard) implement software CFI. Significantly raises exploit bar." },
{ id:382, q:"What is Address Space Layout Randomization effectiveness?", a:"ASLR's effectiveness depends on the entropy (randomness) of addresses — low entropy (32-bit) can be brute-forced; 64-bit systems provide 28+ bits of entropy making brute force impractical.", exp:"32-bit: ~12 bits of ASLR entropy → 4096 attempts could guess. 64-bit: 28+ bits → 256M+ attempts. Info-leak vulnerabilities can reveal addresses (defeating ASLR). Brute forcing remote services detectable. Combined with CFI, stack canaries, and DEP provides strong defense-in-depth." },
{ id:383, q:"What is kernel hardening?", a:"Kernel hardening reduces the attack surface and prevents exploitation of kernel vulnerabilities through additional security mechanisms.", exp:"Techniques: KASLR (kernel ASLR), SMEP/SMAP, stack canaries in kernel (CONFIG_STACKPROTECTOR), control flow integrity, read-only kernel memory, minimal kernel attack surface (disable unused features), kernel lockdown mode, seccomp for system call filtering." },
{ id:384, q:"What is KASLR?", a:"Kernel Address Space Layout Randomization randomizes the kernel's base address in memory on each boot to make kernel exploits harder.", exp:"Without KASLR: kernel always at known address — exploits can use kernel code/data addresses directly. With KASLR: kernel loaded at random offset — attackers need an info leak to find kernel addresses. /proc/kallsyms (limited to root). Side-channel attacks (DragonBlood, etc.) can sometimes defeat KASLR." },
{ id:385, q:"What is the purpose of /etc/passwd and /etc/shadow?", a:"/etc/passwd stores user account information (readable by all); /etc/shadow stores hashed passwords (readable only by root).", exp:"/etc/passwd: username:x:UID:GID:GECOS:home:shell (x means password in shadow). /etc/shadow: username:hash:last_change:min_age:max_age:warn:inactive:expire. Password stored as $algorithm$salt$hash. Hashing algorithms: SHA-512 ($6$), bcrypt ($2b$). getent passwd reads both." },
{ id:386, q:"What is PAM (Pluggable Authentication Modules)?", a:"PAM is a flexible authentication framework that allows OS authentication to be configured through modules without recompiling applications.", exp:"Applications call PAM API; PAM consults /etc/pam.d/service configuration to run authentication modules. Modules: pam_unix (traditional password), pam_ldap (LDAP), pam_google_authenticator (TOTP 2FA), pam_limits (resource limits), pam_tally2 (lockout). Enables per-application authentication policies." },
{ id:387, q:"What is LDAP in OS context?", a:"LDAP (Lightweight Directory Access Protocol) provides centralized user authentication and directory services, allowing OS login with centralized credentials.", exp:"Enterprise environments: accounts stored in LDAP (OpenLDAP, Active Directory). Linux clients: sssd (System Security Services Daemon) or nss-ldapd. /etc/nsswitch.conf: passwd: files ldap. Users can log in with LDAP credentials across all Linux servers without local accounts." },
{ id:388, q:"What is Kerberos in OS context?", a:"Kerberos is a network authentication protocol using tickets and a trusted Key Distribution Center (KDC) to provide strong mutual authentication.", exp:"Used in enterprise (Active Directory). Login obtains TGT (Ticket Granting Ticket) from KDC. Service access: exchange TGT for service ticket. Avoids sending passwords over network. Single Sign-On (SSO): authenticate once, access all Kerberized services. kinit/klist/kdestroy commands." },
{ id:389, q:"What is /etc/sudoers?", a:"/etc/sudoers defines who can run which commands as which users with sudo, and whether a password is required.", exp:"Syntax: user/group ALL=(user)=(NOPASSWD:) commands. Example: alice ALL=(ALL) NOPASSWD: /sbin/reboot. %wheel ALL=(ALL) ALL (any command for wheel group). visudo edits safely (validates syntax). Include /etc/sudoers.d/. Defaults: require_tty, logfile, timestamp_timeout." },
{ id:390, q:"What is the setuid bit?", a:"The setuid bit on an executable causes the program to run with the file owner's permissions rather than the executing user's permissions.", exp:"Example: /usr/bin/passwd has setuid root — allows users to change their own password (which requires writing /etc/shadow owned by root). Risk: setuid root programs are high-value targets. find / -perm -4000 finds setuid files. Modern Linux uses capabilities instead of setuid where possible." },
{ id:391, q:"What is the sticky bit?", a:"The sticky bit on a directory prevents users from deleting files owned by others in that directory, even if they have write permission to the directory.", exp:"Classic use: /tmp has permissions 1777 (sticky bit set). All users can create files in /tmp but only the file owner (or root) can delete them. Without sticky bit, write permission to /tmp would allow any user to delete others' files. chmod +t /tmp." },
{ id:392, q:"What is umask?", a:"umask is a value that determines the default permissions of newly created files and directories by masking (removing) bits from the maximum permissions.", exp:"Default file permissions: 666 (rw-rw-rw-). Default dir: 777. umask 022: 666-022=644 (rw-r--r--) for files, 777-022=755 (rwxr-xr-x) for dirs. Set in shell profile. A umask of 027 would give 640 files (no world access). More secure environments use 077." },
{ id:393, q:"What is POSIX Access Control Lists (ACLs)?", a:"POSIX ACLs extend the traditional Unix permission model to allow per-user and per-group permissions on any file, beyond just owner/group/others.", exp:"setfacl -m u:alice:r-- file (give alice read). setfacl -m g:dev:rw- file. getfacl file shows ACLs. Files with ACLs show a '+' in ls -l. Mask entry limits effective permissions for named users/groups. Requires FS support and acl mount option. More granular than traditional permissions." },
{ id:394, q:"What is chattr and lsattr?", a:"chattr changes extended file attributes in Linux; lsattr lists them. Attributes like immutable (+i) prevent files from being modified or deleted even by root.", exp:"chattr +i /etc/resolv.conf: makes file immutable (no write, delete, rename — even root). chattr +a /var/log/app.log: append-only (can add to file but not modify/delete). Used to protect critical configs, logs. lsattr to check. Even root needs -i removed to modify (must chattr -i first)." },
{ id:395, q:"What is an audit log in OS?", a:"An audit log records security-relevant system events (logins, privilege use, file access, system calls) for security monitoring and forensic analysis.", exp:"Linux: auditd — audit daemon records events to /var/log/audit/audit.log. Rules in /etc/audit/rules.d/ define what to audit. ausearch/aureport query logs. auditctl adds rules at runtime. Example: audit all writes to /etc/passwd. Required for PCI-DSS, HIPAA compliance." },
{ id:396, q:"What is SELinux type enforcement?", a:"SELinux type enforcement defines rules specifying which source types (process domains) can perform which operations on which target types (file/resource types).", exp:"Every process has a domain type; every file has a type. Rules: allow domain_t file_t:file { read write }. Only explicitly allowed operations permitted (default deny). Policy violations denied and logged (AVC: Access Vector Cache denials). Confined applications: httpd_t can only access web content types." },
{ id:397, q:"What is mandatory access control vs discretionary access control?", a:"DAC (traditional Unix): resource owner decides permissions. MAC (SELinux, AppArmor): security policy enforced by system regardless of owner's wishes.", exp:"DAC: chmod, chown — user controls their own files, can share freely. Vulnerable: malicious setuid program can change permissions. MAC: security administrator defines policy, users cannot override it. Compromised process still confined by MAC policy. Defense-in-depth against privilege escalation." },
{ id:398, q:"What is ptrace system call?", a:"ptrace is a system call that allows one process (debugger) to observe and control another process's execution, memory, and registers.", exp:"Used by gdb, strace, ltrace, perf. Operations: attach to process, read/write memory and registers, intercept syscalls, single-step. Powerful but dangerous: a process with ptrace access can completely control another. Protected by YAMA LSM (ptrace_scope). Seccomp can block ptrace from containers." },
{ id:399, q:"What is core dump?", a:"A core dump is a file containing a copy of a process's memory at the time of a crash, used for post-mortem debugging.", exp:"Generated on fatal signals (SIGSEGV, SIGABRT, SIGQUIT). Enabled via ulimit -c unlimited or coredump_filter. Analyzed with gdb or lldb: 'gdb program core'. Contains: memory, registers, stack traces. systemd-coredump captures and stores core dumps. Controlled via /proc/sys/kernel/core_pattern." },
{ id:400, q:"What is the Linux Audit Framework?", a:"The Linux Audit Framework provides comprehensive system call auditing, recording security-relevant events to help meet compliance requirements and detect intrusions.", exp:"Components: audit kernel module (intercepts syscalls), auditd daemon (writes events to log), audisp dispatcher (plugins for forwarding). Rules: -w /etc/passwd -p wa (watch file for writes/attr changes), -a always,exit -F arch=b64 -S execve (audit all program executions). Required for government/compliance." },

// Section 18: Questions 401-500+
{ id:401, q:"What is CPU pinning?", a:"CPU pinning dedicates specific CPU cores to specific VMs or processes, ensuring they always run on the same cores for predictable performance.", exp:"Eliminates CPU migration overhead, improves cache utilization, enables NUMA locality. Used for VMs in KVM (vcpupin), containers (cpuset cgroup), DPDK network processing. Reduces 'noisy neighbor' interference. taskset -c 0,1 ./program pins a process to cores 0 and 1." },
{ id:402, q:"What is DPDK?", a:"Data Plane Development Kit (DPDK) is a framework for fast packet processing in userspace, bypassing the kernel network stack.", exp:"The kernel network stack adds 100+ μs latency per packet. DPDK: poll-mode drivers run in userspace, dedicated CPU cores, huge pages for DMA, zero-copy. Enables millions of packets per second per core. Used in telco (5G), network functions, NFV. Intel-originated, now open source." },
{ id:403, q:"What is RDMA (Remote Direct Memory Access)?", a:"RDMA allows direct memory access from one computer's RAM to another over a network without involving the CPU or OS on either end.", exp:"Traditional: app → syscall → kernel → NIC driver → network → receiver NIC → kernel → app. RDMA: app → NIC → network → receiver NIC → app (kernel and CPU bypassed on both sides). Ultra-low latency (μs), high throughput. Used in HPC (MPI), distributed databases (Apache Arrow Flight). InfiniBand, RoCE protocols." },
{ id:404, q:"What is the difference between process and thread performance?", a:"Threads are cheaper to create/destroy and communicate (shared memory) than processes (separate address spaces, IPC needed), but processes offer better isolation.", exp:"Thread creation: ~10μs (stack allocation, TCB setup). Process creation (fork): ~100μs (address space copy setup, COW). Thread context switch: ~1μs (same address space, no TLB flush). Process context switch: ~5–10μs (different address space, TLB flush on non-PCID CPUs). Threads win on overhead; processes on safety." },
{ id:405, q:"What is the N:M threading model?", a:"N:M (hybrid) threading maps N user-level threads onto M kernel threads, combining benefits of user-level (fast context switch) and kernel-level (true parallelism) threading.", exp:"M2 (old Solaris), Go's goroutine scheduler use N:M. User-level threads scheduled by user library within M kernel threads. Kernel threads run on multiple CPUs (true parallelism). When a kernel thread blocks, others continue. Complex to implement correctly. Linux uses 1:1 (each pthread = kernel thread)." },
{ id:406, q:"What are green threads?", a:"Green threads are user-level threads scheduled by a runtime library rather than the OS kernel, enabling lightweight concurrency without OS involvement.", exp:"Java originally used green threads (pre-1.3). Very fast context switch (no syscall). Problem: blocking syscall blocks entire process (no CPU overlap). Modern: Go's goroutines are green threads on M:N scheduler with goroutine-aware syscall wrapping. Python asyncio and gevent also use green-thread-like models." },
{ id:407, q:"What is coroutine?", a:"A coroutine is a generalization of a subroutine that can suspend execution and yield control, resuming later — cooperative multitasking within a single thread.", exp:"Coroutines explicitly yield to each other (cooperative, not preemptive). Used in async programming (async/await), game loops, event processing. Python asyncio, JavaScript promises, Go channels, Kotlin coroutines. More explicit than threads, no race conditions (single-threaded), but must yield for concurrency." },
{ id:408, q:"What is the event loop?", a:"An event loop is a programming construct that repeatedly checks for and dispatches events or messages in a program.", exp:"Single thread monitors event queue. Events: I/O completion, timer expiry, user input. Handlers run to completion (no preemption). Non-blocking I/O + callbacks. JavaScript (browsers, Node.js), Python asyncio, Redis use event loops. Scalable for I/O-bound workloads; not suited for CPU-bound (blocks the loop)." },
{ id:409, q:"What is async/await?", a:"async/await is syntax for asynchronous programming that allows writing asynchronous code in a sequential-looking style using coroutines.", exp:"async function/task can be suspended at await points. The event loop or scheduler runs other tasks while waiting. Python 3.5+: async def, await. JavaScript: async/await. Rust: async/await with futures. C#: Task async/await. Improves readability over callback chains ('callback hell')." },
{ id:410, q:"What is futures and promises in OS/system programming context?", a:"A future/promise is an object representing the result of an asynchronous operation that may not have completed yet.", exp:"Future: read-only placeholder. Promise: writable side (resolved with value). Used in async frameworks: Rust futures, C++ std::future, Java CompletableFuture. io_uring returns completions that can be treated as futures. Enables composable async operations without blocking threads." },
{ id:411, q:"What is the actor model?", a:"The actor model is a concurrency paradigm where actors are independent units that communicate exclusively via message passing, with no shared mutable state.", exp:"Actors: encapsulate state, process messages sequentially, can create new actors, send messages. No race conditions (no shared memory). Erlang/Elixir use actors natively. Akka (JVM). Easier to reason about than shared-memory concurrency. Trade-off: message overhead, not ideal for high-throughput shared data." },
{ id:412, q:"What is lock-free programming?", a:"Lock-free programming uses atomic CPU instructions (compare-and-swap) instead of locks to implement concurrent data structures without blocking.", exp:"CAS (Compare-and-Swap): atomically compare memory value, update if matches. lock-free: at least one thread makes progress (no global lock). Wait-free: every thread makes progress in bounded steps. Used in high-performance queues (LMAX Disruptor), reference counting, memory allocators. Complex to implement correctly." },
{ id:413, q:"What is compare-and-swap (CAS)?", a:"CAS is an atomic CPU instruction that compares a memory location's value to an expected value and, if they match, replaces it with a new value — atomically.", exp:"Used for lock-free algorithms. C++: std::atomic::compare_exchange_strong. x86: CMPXCHG instruction. ABA problem: value changes A→B→A, CAS succeeds but state may be different. Solutions: tagged pointers (version counter), hazard pointers, RCU. Foundation of lock-free data structures." },
{ id:414, q:"What is the ABA problem in concurrent programming?", a:"The ABA problem occurs when a value changes from A to B and back to A between two reads; a CAS operation sees A and proceeds, unaware of the intermediate change.", exp:"Example: lock-free stack, pop reads top=A. Another thread pops A, pushes B, then pushes A (same pointer, different logical state). First thread's CAS(A→new) succeeds but list is corrupted. Solutions: versioned pointers (include a counter in the pointer), hazard pointers, double-compare-and-swap (DCAS)." },
{ id:415, q:"What is memory ordering in concurrent programming?", a:"Memory ordering specifies constraints on how memory operations (loads/stores) by one thread appear to other threads, from relaxed (no guarantees) to sequential consistency.", exp:"C++ memory orders: relaxed (no ordering guarantees, just atomicity), acquire (see all writes before release in other thread), release (publish writes), seq_cst (total global order — strongest, most expensive). ARM and x86 differ in memory model. Use weakest ordering that preserves correctness." },
{ id:416, q:"What is sequential consistency?", a:"Sequential consistency is a memory model where operations appear to execute in some total global order consistent with each thread's program order.", exp:"Strongest practical model. Easiest to reason about: no surprises about ordering. Expensive on modern hardware (requires memory barriers). C++ std::atomic default (seq_cst). SPARC TSO is slightly weaker (total store order). Java volatile provides seq_cst for that variable." },
{ id:417, q:"What is the happens-before relationship?", a:"The happens-before relationship defines a partial order on memory operations, guaranteeing that writes visible before a synchronization point are visible after it in other threads.", exp:"If A happens-before B, then all memory writes done before A are visible to operations after B. Established by: mutex acquire/release, thread join, atomic operations with acquire/release semantics. Java Memory Model, C++ memory model define happens-before for all synchronization operations." },
{ id:418, q:"What is OpenMP?", a:"OpenMP is an API for shared-memory parallel programming in C, C++, and Fortran using compiler directives (#pragma omp) to parallelize loops and regions.", exp:"#pragma omp parallel for: parallelize loop across threads. Threads share memory automatically. Work sharing: for (static/dynamic/guided scheduling), sections, tasks. Synchronization: critical, atomic, barrier, reduction. Used in scientific computing, image processing. Simpler than pthreads for data-parallel code." },
{ id:419, q:"What is MPI (Message Passing Interface)?", a:"MPI is a standardized message-passing library for distributed-memory parallel computing (clusters), where processes communicate by sending/receiving messages.", exp:"Each MPI process has own memory, communicates explicitly. MPI_Send/MPI_Recv for point-to-point, MPI_Bcast/MPI_Reduce for collective. Used in HPC/supercomputers. Can combine with OpenMP (MPI across nodes, OpenMP within node). OpenMPI, MPICH are implementations." },
{ id:420, q:"What is NUMA-aware memory allocation?", a:"NUMA-aware allocation places memory on the NUMA node local to the accessing CPU, minimizing cross-NUMA memory access latency.", exp:"numactl --membind=0 ./program: bind memory to node 0. numa_alloc_local() in code. NUMA distance: local 10, remote 21 (varies). Linux first-touch policy: page allocated on node of first-touching CPU. NUMA libraries: libnuma. Applications with NUMA awareness can see 2× performance improvement on 2-socket servers." },
{ id:421, q:"What is the role of the memory allocator?", a:"The memory allocator manages dynamic memory (heap) allocation and deallocation, implementing malloc/free efficiently while minimizing fragmentation.", exp:"Allocators: glibc malloc (ptmalloc), jemalloc (Firefox, Redis), tcmalloc (Chrome, Go), mimalloc (Microsoft). Strategies: size classes, thread-local caches, arena-based allocation. malloc performance critical for allocation-heavy apps. jemalloc/tcmalloc reduce lock contention vs ptmalloc." },
{ id:422, q:"What is memory sanitizer?", a:"Memory Sanitizer (MSan) is a runtime tool that detects use of uninitialized memory in programs, helping find hard-to-reproduce bugs.", exp:"Part of LLVM/GCC sanitizers. Instruments reads — if source was never written, reports error. Useful for C/C++ where uninitialized reads are undefined behavior. AddressSanitizer (ASan): buffer overflows, use-after-free. UBSan: undefined behavior. MemorySanitizer: uninitialized reads. ThreadSanitizer: race conditions." },
{ id:423, q:"What is Valgrind?", a:"Valgrind is a dynamic analysis framework for detecting memory errors (leaks, invalid accesses, uninitialized reads) by running programs in a virtual CPU.", exp:"Most used tool: Memcheck. Detects: heap out-of-bounds, use-after-free, double-free, memory leaks, uninitialized reads. 10–50× slowdown. Alternative: ASan (compile-time instrumentation, 2× slowdown). Massif: heap profiler. Callgrind: CPU profiler. Helgrind: thread error detector." },
{ id:424, q:"What is DTrace?", a:"DTrace is a comprehensive dynamic tracing framework for production systems, allowing safe tracing of both kernel and user-space events in real-time.", exp:"Developed by Sun/Oracle for Solaris. Ported to macOS, FreeBSD, and Linux (dtrace-utils). D language for writing probes. Low overhead (no-op when disabled). Probes at arbitrary kernel/user locations. Used for performance analysis in production. BPFTrace is the Linux alternative using eBPF." },
{ id:425, q:"What is SystemTap?", a:"SystemTap is a Linux scripting tool and infrastructure for dynamic instrumentation of running kernels using kernel probes (kprobes/uprobes).", exp:"Write scripts in SystemTap language. Compile to kernel module, load for tracing, unload when done. Can trace any kernel function, user function, syscall. Used before eBPF became prevalent. More complex than eBPF. Used for advanced kernel debugging and performance analysis." },
{ id:426, q:"What is ftrace?", a:"ftrace is the Linux kernel's built-in tracing framework providing function tracing, latency tracing, and event tracing via the tracefs filesystem.", exp:"Access via /sys/kernel/debug/tracing/. Enable function tracer: echo function > current_tracer. trace-cmd command wrapper. Events: echo 1 > events/sched/sched_switch/enable. Used for: context switch latency, interrupt latency, scheduler debugging, finding unexpected function calls. Built into kernel — no modules needed." },
{ id:427, q:"What is kprobes?", a:"kprobes is a Linux kernel debugging mechanism that allows dynamic insertion of probes (breakpoints) into any kernel instruction to trace and profile the kernel without recompiling.", exp:"Insert probe at kernel function entry/return/any instruction. Probe handler runs when breakpoint hit. Used by SystemTap, eBPF, perf. kretprobes for function return probes. Very flexible — probe any instruction. Some overhead per probe hit (single-step emulation). uprobes extends this to user-space." },
{ id:428, q:"What is the perf framework in Linux?", a:"perf is the Linux performance analysis subsystem and tool using hardware performance monitoring counters (PMCs) and software events.", exp:"Hardware events: CPU cycles, cache misses, branch mispredictions, TLB misses — measured by PMCs. Software events: context switches, page faults, process migrations. perf stat (count), perf record (sample with call graphs), perf report/top (analysis). Foundation for flame graphs, profiling, tuning." },
{ id:429, q:"What is a flame graph?", a:"A flame graph is a visualization of CPU profiling data showing call stack frequency as stacked horizontal bars, making hot code paths immediately visible.", exp:"X-axis: alphabetical (not time). Y-axis: call depth. Width: fraction of time. Created by Brendan Gregg. Generated from perf record or DTrace stacks. 'Plateaus' indicate hot functions. Quick to identify where CPU time is spent. Now standard for performance analysis." },
{ id:430, q:"What is the difference between user-space and kernel-space profiling?", a:"User-space profiling samples/instruments application code; kernel-space profiling includes kernel functions in call stacks to show full system behavior.", exp:"perf record -g --call-graph dwarf captures both user and kernel frames. Without kernel frames, can't see why syscalls are slow (what kernel code runs). For system calls, network, disk I/O: kernel stack shows which code path handles the request. Requires CAP_SYS_ADMIN or /proc/sys/kernel/perf_event_paranoid ≤ 1." },
{ id:431, q:"What is CPU cache miss?", a:"A CPU cache miss occurs when requested data is not in the CPU cache (L1/L2/L3), requiring a slower fetch from the next cache level or RAM.", exp:"L1 hit: ~4 cycles. L2 hit: ~12 cycles. L3 hit: ~40 cycles. RAM: ~200 cycles. TLB miss adds page table walk. Cache misses dominate performance of cache-unfriendly data structures (linked lists, trees). Solution: cache-friendly layouts (arrays, struct-of-arrays), prefetching, alignment." },
{ id:432, q:"What is cache-friendly data structures?", a:"Cache-friendly data structures organize data to maximize spatial and temporal locality, keeping frequently accessed data in contiguous memory for better cache utilization.", exp:"Array vs linked list: array elements contiguous (prefetched), linked list nodes scattered (cache miss per node). Struct-of-arrays vs array-of-structs: iterate one field → struct-of-arrays is better. Hash table with open addressing > chaining (pointer chasing = cache misses). B-tree better than BST for disk/cache." },
{ id:433, q:"What is memory bandwidth?", a:"Memory bandwidth is the rate at which data can be read from or written to main memory, typically measured in GB/s.", exp:"Typical DDR4: 25–50 GB/s per channel (dual-channel = 2×). Memory-bound workloads (stream processing, large matrix multiply) are limited by bandwidth not CPU compute. NUMA systems: higher bandwidth to local memory. Profiling: perf stat -e cache-misses,cache-references reveals memory pressure." },
{ id:434, q:"What is hyperthreading?", a:"Hyperthreading (Intel) / SMT (Simultaneous Multithreading) allows one physical CPU core to appear as two logical CPUs, sharing execution resources between two threads.", exp:"Two hardware threads share execution units but have separate registers and program counters. When one thread stalls (cache miss), other thread uses execution units. Typically 15–30% performance improvement for mixed workloads. Disabled for security (Spectre-class vulnerabilities use SMT as attack vector)." },
{ id:435, q:"What is SIMD (Single Instruction Multiple Data)?", a:"SIMD is a CPU instruction set extension that applies one instruction to multiple data elements simultaneously, accelerating vector operations.", exp:"SSE2 (16 bytes), AVX (32 bytes), AVX-512 (64 bytes). One SIMD instruction adds 8 floats simultaneously instead of 8 separate adds. Used in: image processing, audio/video encoding, scientific computing, string processing, AES. OS must save/restore SIMD registers on context switch (significant overhead if large)." },
{ id:436, q:"What is out-of-order execution?", a:"Out-of-order execution is a CPU optimization where instructions are executed as their input data becomes available rather than strictly in program order.", exp:"CPU analyzes instruction stream, identifies independent instructions, executes them simultaneously or out of order. Reorder buffer (ROB) commits results in order. This is the foundation of Spectre/Meltdown vulnerabilities — CPU executes instructions that shouldn't run (across privilege boundaries) speculatively." },
{ id:437, q:"What is branch prediction?", a:"Branch prediction is a CPU mechanism that guesses the outcome of conditional branches to avoid pipeline stalls from waiting for the branch condition to be computed.", exp:"Modern CPUs: 95–99% prediction accuracy. Misprediction penalty: 10–20 cycles (pipeline flush). Branch predictor uses history of past branch outcomes. Code optimization: sort data before branching on value (consistent branch direction), branchless code (cmov instruction). Spectre exploits branch predictor." },
{ id:438, q:"What is speculative execution?", a:"Speculative execution allows the CPU to execute instructions beyond a branch before knowing the branch outcome, discarding results if prediction was wrong.", exp:"Improves IPC (instructions per cycle) by keeping CPU busy. Wrong speculation: pipeline flushed, results discarded — wasted work but no correctness issue. Security issue: side effects (cache state) remain even after discard — Spectre/Meltdown exploit this." },
{ id:439, q:"What is CPU pipeline?", a:"A CPU pipeline breaks instruction execution into stages (fetch, decode, execute, memory, writeback), allowing multiple instructions to be in different stages simultaneously.", exp:"5-stage pipeline: IF (instruction fetch), ID (decode), EX (execute), MEM (memory access), WB (writeback). With pipelining: 5 instructions in different stages simultaneously. Pipeline stalls: data hazards (dependency), control hazards (branches), structural hazards (resource conflicts). Modern CPUs have 14–20 stage pipelines." },
{ id:440, q:"What is a syscall table?", a:"The syscall table is an array in the kernel mapping syscall numbers to their handler functions.", exp:"On Linux x86-64: RAX register holds syscall number (0=read, 1=write, 2=open, etc.). The kernel's sys_call_table[] array maps these to functions (sys_read, sys_write, sys_open). The 'syscall' instruction traps to kernel; kernel looks up handler. On 32-bit: int 0x80 or sysenter. Security: kernel protects the table from modification." },
{ id:441, q:"What is vsyscall and vDSO?", a:"vsyscall (deprecated) and vDSO are mechanisms to make certain frequent syscalls execute in userspace without a full kernel mode switch.", exp:"vsyscall: fixed address (0xFFFFFFFFFF600000), mapped kernel read-only data, directly callable from userspace — gettimeofday, time, getcpu. Security risk: fixed address aids ROP. vDSO (modern): randomly mapped shared library with same functions but ASLR protection. Provides clock_gettime, gettimeofday at 10ns vs 100ns syscall." },
{ id:442, q:"What is the Linux scheduler domains?", a:"Scheduler domains form a hierarchical topology describing the CPU topology (hyperthreads, cores, sockets, NUMA nodes) to guide load balancing decisions.", exp:"The Linux CFS scheduler uses domain topology for load balancing. Lowest domain: SMT siblings (hyperthreads). Next: physical cores in one die. Next: NUMA node. Highest: across NUMA nodes. Load balancing aggressiveness decreases at higher levels (moving tasks across NUMA is expensive)." },
{ id:443, q:"What is the difference between user threads and kernel threads in Linux?", a:"In Linux's 1:1 model, each user thread (pthread) is a kernel thread (task) — there's no distinction; both are kernel-scheduled.", exp:"Unlike some systems with separate user-level and kernel-level threading, Linux uses clone() to create threads that are kernel-visible. Each pthread appears in /proc as a separate task (LWP). ps -L shows threads. The kernel schedules each pthread independently on any available CPU." },
{ id:444, q:"What is a task struct in Linux kernel?", a:"task_struct is the kernel data structure representing a process or thread in the Linux kernel.", exp:"Contains: PID, state, priority, scheduling info, memory map (mm_struct), file descriptor table (files_struct), signal handlers (sighand_struct), CPU registers (thread_struct), cgroup membership, security context (cred). The kernel maintains a list of all task_structs. sizeof(task_struct) ≈ 10KB." },
{ id:445, q:"What is the Linux kernel's mm_struct?", a:"mm_struct (memory map structure) is the Linux kernel data structure representing a process's entire virtual address space.", exp:"Contains: vm_area_struct list (VMAs — regions of virtual memory), page table base (pgd), memory usage counters, mmap_lock (rwsemaphore). Each VMA describes a contiguous region (stack, heap, .text, mmap'd library). cat /proc/PID/maps shows all VMAs. Threads in the same process share the same mm_struct." },
{ id:446, q:"What is a VMA (Virtual Memory Area)?", a:"A VMA describes a contiguous region in a process's virtual address space with uniform properties (permissions, file backing, flags).", exp:"Each mmap(), stack, heap, text segment creates a VMA. VMA has: start/end addresses, flags (VM_READ, VM_WRITE, VM_EXEC), backing file (or anonymous), offset. /proc/PID/maps shows all VMAs. The kernel's fault handler looks up the VMA to determine how to handle a page fault." },
{ id:447, q:"What is huge TLB in Linux?", a:"HugeTLB is Linux's explicit huge page mechanism that pre-allocates huge pages (2MB or 1GB) from a pool for use by applications that request them.", exp:"Unlike THP (automatic), HugeTLB pages are pre-reserved: echo 1024 > /proc/sys/vm/nr_hugepages. Applications use mmap with MAP_HUGETLB or SHM_HUGETLB. Cannot be paged out (pinned). Critical for Oracle, SAP HANA, Redis — large in-memory databases benefit greatly from reduced TLB pressure." },
{ id:448, q:"What is OOM score?", a:"OOM score is a numeric value assigned to each process by the Linux kernel indicating how likely it is to be killed when the system is out of memory.", exp:"Higher score = more likely to be killed. Factors: resident memory, swap, run time, nice value. /proc/PID/oom_score shows current score. /proc/PID/oom_score_adj: range -1000 to +1000 to adjust. -1000: never kill. +1000: always kill first. Critical processes (init, kernel threads) have -1000." },
{ id:449, q:"What is memory pressure notification?", a:"Memory pressure notification allows the kernel to notify applications when memory is scarce so they can release caches or reduce memory usage proactively.", exp:"cgroup memory controller: memory.pressure (PSI — Pressure Stall Information). PSI shows percentage of time tasks stalled waiting for memory. memfd and poll-based notification. Redis, databases can register for notifications and flush internal caches when memory pressure is reported, avoiding OOM kills." },
{ id:450, q:"What is PSI (Pressure Stall Information)?", a:"PSI is a Linux kernel feature that measures the percentage of time that tasks are stalled waiting for CPU, memory, or I/O resources.", exp:"Three resources: cpu, memory, io. Two levels: some (at least one task stalled), full (all tasks stalled). Metrics: avg10, avg60, avg300 (10s, 1m, 5m windows). /proc/pressure/{cpu,memory,io}. Facebook developed PSI for resource pressure detection. Used by systemd, k8s, Android for resource management." },
{ id:451, q:"What is the 4GB memory limit in 32-bit operating systems?", a:"32-bit processors can address at most 2^32 bytes = 4GB of memory, limiting the address space for both user programs and kernel.", exp:"64-bit lifted this limit (x86-64: 48-bit virtual = 256TB). PAE (Physical Address Extension) allowed 32-bit OS to access >4GB physical RAM (3-level paging), but each process still limited to 4GB virtual space (or 2GB user + 2GB kernel split). 64-bit OS provides 128TB user virtual space." },
{ id:452, q:"What is the 3GB/1GB split in 32-bit Linux?", a:"On 32-bit Linux, the 4GB virtual address space is split: 3GB for user space (0–3GB) and 1GB for kernel space (3–4GB), which is mapped the same in every process.", exp:"Kernel space always present in process's address space for fast syscall entry (no address space switch). User cannot access kernel pages (CPL ring check). 1GB kernel limit constrains amount of directly mapped kernel memory. CONFIG_VMSPLIT_2G/3G options change the split." },
{ id:453, q:"What is high memory in 32-bit Linux?", a:"High memory is the portion of physical memory above 896MB on 32-bit Linux that cannot be permanently mapped in the kernel's 1GB virtual address window.", exp:"With 1GB kernel space: first 896MB physical → directly mapped (lowmem). Above 896MB → highmem, must be temporarily mapped (kmap). This created serious issues with >1GB RAM on 32-bit. 64-bit kernels eliminated this: entire physical memory can be directly mapped in kernel space." },
{ id:454, q:"What is kdump?", a:"kdump is a Linux kernel crash dump mechanism that captures a memory dump of a crashed kernel for post-mortem analysis.", exp:"Second kernel (crash kernel) reserved in low memory. On kernel panic: first kernel saves registers, triggers jump to crash kernel. Crash kernel boots, captures /proc/vmcore dump. Analyzed with crash(8) tool. Configured via kexec-tools and kdump.conf. Required for kernel bug investigation." },
{ id:455, q:"What is kexec?", a:"kexec allows loading and executing a new kernel from the running kernel without going through BIOS/firmware reboot.", exp:"Much faster reboots (skips POST, BIOS initialization). Used by kdump (loads crash kernel). Useful for kernel updates in production (minimal downtime). kexec -l /boot/vmlinuz --initrd=/boot/initrd; kexec -e executes immediately. Requires kexec-tools userspace. Used in some Linux distribution update workflows." },
{ id:456, q:"What is module loading in Linux kernel?", a:"Kernel module loading dynamically adds code to the running kernel without rebooting, used for device drivers and filesystems.", exp:"insmod/modprobe: load module (.ko file). modprobe automatically loads dependencies. rmmod: remove module. lsmod: list loaded modules. /etc/modules-load.d/: modules to load at boot. Module signing (modprobe --force): Secure Boot requires signed modules. /lib/modules/$(uname -r)/ stores modules." },
{ id:457, q:"What is /sys/kernel/debug?", a:"/sys/kernel/debug (debugfs) is a virtual filesystem for kernel debugging, providing a simple way to expose debugging information and controls from kernel code.", exp:"Requires mount: mount -t debugfs none /sys/kernel/debug. Used by: ftrace (/debug/tracing), dynamic debug (pr_debug), various driver debugging interfaces. More flexible than /proc for debugging. Not suitable for production use (exposes internal kernel state). Requires root access." },
{ id:458, q:"What is kernel oops vs kernel panic?", a:"Kernel oops is a recoverable kernel error that logs a trace; kernel panic is an unrecoverable error that halts the system.", exp:"Oops: kernel detected error (null pointer, bad pointer), logs stack trace to dmesg, may kill offending process, kernel continues. Panic: kernel calls panic() when it cannot safely continue (corrupt data structures, no memory, triple fault). /proc/sys/kernel/panic = N: reboot N seconds after panic (0 = halt)." },
{ id:459, q:"What is the Linux kernel's livepatch?", a:"Livepatch allows applying security patches to a running Linux kernel without rebooting by dynamically replacing kernel functions.", exp:"New patched function code compiled. At patch time: kernel redirects calls from old function to new function using ftrace/kpatch infrastructure. Old function trampolined. Consistency model: ensures patched functions are not currently executing (per-task patching). Used by Red Hat kpatch, Ubuntu Livepatch, SUSE kGraft." },
{ id:460, q:"What is CPU hotplug and memory hotplug?", a:"CPU hotplug dynamically adds/removes CPUs; memory hotplug dynamically adds/removes memory modules from a running system.", exp:"CPU hotplug: echo 0 > /sys/devices/system/cpu/cpu1/online. Used for power management and server hardware. Memory hotplug: add DIMM to running server (with hot-plug capable hardware). Linux must be configured with CONFIG_HOTPLUG_CPU, CONFIG_MEMORY_HOTPLUG. Critical for cloud infrastructure maintenance." },
{ id:461, q:"What is kernel lockdown mode?", a:"Kernel lockdown mode restricts kernel features that could be used by the root user to subvert kernel integrity, particularly important with Secure Boot.", exp:"Modes: none (disabled), integrity (prevents modification of kernel code/data), confidentiality (also blocks reading kernel memory). Prevents: kexec (load unsigned kernel), loading unsigned modules, /dev/mem access, debugfs, certain BPF operations. Enabled automatically when Secure Boot active." },
{ id:462, q:"What is secureboot in context of Linux?", a:"Secure Boot in Linux ensures each boot stage (GRUB, kernel, modules) is cryptographically signed and verified by the firmware.", exp:"UEFI firmware → signed shim → signed GRUB → signed kernel (via shim's MOK — Machine Owner Key). Kernel modules must be signed (MODPROBE_ENFORCE_MODULE_SIG). Users can add keys to MOK via mokutil. Lockdown mode restricts kernel capabilities to prevent Secure Boot bypass from within Linux." },
{ id:463, q:"What is UEFI Secure Boot key hierarchy?", a:"UEFI Secure Boot uses a hierarchy of keys: Platform Key (PK), Key Exchange Keys (KEK), Signature Database (db), and Forbidden Signatures Database (dbx).", exp:"PK: root of trust, owned by platform manufacturer. KEK: keys that can update db/dbx. db: allowed signatures for bootloaders. dbx: forbidden signatures (revoked). Microsoft's key in KEK/db allows signed Windows/shim bootloaders. Users can add their own keys via tools if PK allows it." },
{ id:464, q:"What is Linux's memory model (5-level paging)?", a:"5-level paging (Linux 5.12+ on capable CPUs) extends x86-64 paging from 4 levels to 5, increasing virtual address space from 256TB to 128PB.", exp:"4-level: 48-bit VA = 256TB user + 256TB kernel. 5-level (Intel Ice Lake+, AMD Zen 4+): 57-bit VA = 128PB user + 128PB kernel. Required for memory-intensive workloads (HPC, large in-memory databases). The extra level adds one memory access per TLB miss." },
{ id:465, q:"What is the role of the init process in Unix?", a:"Init (PID 1) is the first user-space process started by the kernel. It initializes the user environment, starts services, and adopts orphaned processes.", exp:"Must not die (if PID 1 crashes, kernel panics). Spawns all other processes (directly or indirectly). Reaps zombie children of orphaned processes. Modern: systemd (PID 1 in most Linux distros), handles init.d services, socket activation, logging, networking, etc." },
{ id:466, q:"What is socket activation in systemd?", a:"Socket activation allows systemd to create and listen on sockets before starting the service, enabling on-demand service startup and parallel initialization.", exp:"systemd creates the socket (e.g., TCP port 80). When a connection arrives, systemd starts the service, passing the socket. Service starts with connections already waiting. Benefits: faster boot (services start lazily), automatic socket handoff for restarts. Used by D-Bus, sshd, nginx, and many systemd services." },
{ id:467, q:"What is D-Bus?", a:"D-Bus is an IPC system for inter-process communication on Linux desktops and systems, providing a message bus where services can expose APIs.", exp:"Two buses: system bus (root services, hardware events from udev) and session bus (per-user, GUI applications). Services publish interfaces (introspectable via D-Bus API). Used by: NetworkManager, BlueZ, systemd, PulseAudio, GNOME, KDE. Alternative: Varlink (simple JSON over sockets)." },
{ id:468, q:"What is the Linux kernel scheduler's task group?", a:"A task group is a scheduling entity in the Linux kernel that groups processes/threads for proportional CPU sharing via group scheduling.", exp:"CFS hierarchical scheduling: tasks in a group share a vruntime account. cgroup cpu controller creates groups. systemd uses task groups for services — each service gets fair CPU share. Makes resource contention fairer: 100 threads in one service don't starve a single-thread service." },
{ id:469, q:"What is the difference between CPU shares and CPU quota in cgroups?", a:"CPU shares are relative weights for proportional sharing when CPUs are contended; CPU quota is a hard limit (X ms every Y ms period) regardless of availability.", exp:"cpu.shares/cpu.weight: proportional. If one group has 1024 shares and another 512: first gets 2× CPU when both busy. When idle, groups can burst. cpu.max (v2)/cpu.quota_us (v1): absolute throttling. Group limited to e.g., 50ms per 100ms period (50% CPU even if CPUs are idle). Kubernetes uses both." },
{ id:470, q:"What is cgroup memory limit enforcement?", a:"cgroup memory limits prevent a group of processes from using more than a specified amount of memory, triggering OOM kills within the cgroup when exceeded.", exp:"memory.limit_in_bytes (v1) / memory.max (v2). When a container exceeds its memory limit, the kernel OOM kills processes within that cgroup (not other containers). memory.soft_limit_in_bytes: reclaim more aggressively from this group under pressure. Docker --memory flag sets this." },
{ id:471, q:"What is CPU throttling in containers?", a:"CPU throttling occurs when a container has used its CPU quota and must wait until the next period, causing latency spikes even when the host has idle CPUs.", exp:"With cpu.max=50ms/100ms: container gets 50ms of CPU per 100ms period. If it uses 50ms in first 10ms, it's throttled for 90ms — can cause latency spikes. Visible in /sys/fs/cgroup/.../cpu.stat: throttled_time. Fix: increase quota, remove limit, or reduce CPU usage. Common cause of P99 latency issues." },
{ id:472, q:"What is a cgroup hierarchy?", a:"A cgroup hierarchy is a tree of control groups where resource limits are inherited and refined from parent to child groups.", exp:"v1: multiple separate hierarchies per controller (cpu, memory, io each have own tree). Messy. v2: unified single hierarchy — all controllers share one tree. Systemd manages the hierarchy. Docker creates per-container cgroup subtrees. Kubernetes creates per-pod, per-container cgroup subtrees for resource management." },
{ id:473, q:"What is container runtime?", a:"A container runtime is the software that executes container images, managing namespaces, cgroups, filesystems, and network setup.", exp:"Low-level runtimes (OCI-compliant): runc (reference, Docker), crun (C, fast), gVisor (user-space kernel, Google). High-level: containerd (Docker's runtime), CRI-O (Kubernetes). Docker = containerd + runc. Kubernetes talks to containerd or CRI-O via CRI (Container Runtime Interface). Each layer adds functionality." },
{ id:474, q:"What is OCI (Open Container Initiative)?", a:"OCI defines open industry standards for container image format and runtime, ensuring containers are portable across different runtimes and registries.", exp:"OCI Image Spec: container image format (layers, manifest, config). OCI Runtime Spec: how to execute a container (config.json describes namespaces, mounts, cgroups). runc is the OCI-compliant reference runtime. Ensures Docker images run on Podman, containerd, CRI-O without changes." },
{ id:475, q:"What is gVisor?", a:"gVisor is a user-space kernel by Google that intercepts application system calls and implements them in Go, providing sandboxing without requiring hardware virtualization.", exp:"Application → gVisor (Sentry, user-space OS) → limited syscalls to host kernel. Attack surface: host sees only ~20 syscalls. If app is compromised, attacker faces gVisor's Go implementation, not host kernel. Overhead: slower than runc, faster than VM. Used by Google Cloud for App Engine isolation." },
{ id:476, q:"What is Kata Containers?", a:"Kata Containers run each container in a lightweight VM for strong isolation combining container convenience with VM-level security.", exp:"Uses hardware virtualization (KVM). Container appears as normal OCI container. Pod runs as lightweight VM (firecracker or QEMU micro-VM). Each container has its own kernel. More secure than namespaces+cgroups (different kernel = stronger isolation). Overhead: VM startup time, more memory." },
{ id:477, q:"What is Firecracker?", a:"Firecracker is a lightweight VMM (Virtual Machine Monitor) by AWS that uses KVM to create micro-VMs in milliseconds, designed for serverless (Lambda) and container workloads.", exp:"Minimal device model (virtio-net, virtio-block, serial). Boot to working kernel in <125ms. Very low memory overhead (~5MB per VM). Used by AWS Lambda, Fargate, and Fly.io. Provides better isolation than containers with performance approaching containers. Kata Containers can use Firecracker as VMM." },
{ id:478, q:"What is eBPF verifier?", a:"The eBPF verifier is a kernel subsystem that statically analyzes eBPF programs before loading to ensure they cannot crash the kernel or cause security issues.", exp:"Verifier checks: bounded loops (no infinite loops since Linux 5.3 with bounds checking), memory safety (no out-of-bounds), valid helper function usage, return type correctness, no unbounded stack usage. If verification fails, program rejected. This safety guarantee makes eBPF usable in kernel without kernel modules." },
{ id:479, q:"What is BPFTrace?", a:"BPFTrace is a high-level tracing language for Linux using eBPF, similar to DTrace's D language for dynamic kernel and user-space tracing.", exp:"One-liner: bpftrace -e 'tracepoint:syscalls:sys_enter_open { printf(\"%s\\n\", str(args->filename)); }'. Probes: kprobe, tracepoint, uprobe, USDT, software, hardware, profile. Used for performance analysis, debugging. Brendan Gregg's BPFTrace book. Lower overhead than strace, works in production." },
{ id:480, q:"What is the difference between tracepoints and kprobes?", a:"Tracepoints are stable, pre-defined kernel instrumentation points; kprobes are dynamic probes that can be attached to any kernel instruction.", exp:"Tracepoints: kernel developers add them explicitly — stable API, minimal overhead when disabled (single NOP). kprobes: attach to any kernel address, more flexible but fragile (address may change with kernel version). Tracepoints preferred for performance tools. kprobes for debugging specific functions. eBPF supports both." },
{ id:481, q:"What is USDT (Userland Statically Defined Tracing)?", a:"USDT probes are stable tracepoints in user-space applications that can be observed by tracing tools (DTrace, eBPF, SystemTap) without modifying the application.", exp:"Define probes in application code with DTRACE_PROBE macro. Inactive probes are no-ops (NOP instruction). When tool attaches, probe fires. PostgreSQL, MySQL, Node.js, OpenJDK have USDT probes. BPFTrace can attach: bpftrace -e 'usdt:/usr/bin/postgres:postgresql:query__start { ... }'. Production-safe tracing." },
{ id:482, q:"What is memory-mapped I/O vs port I/O?", a:"Memory-mapped I/O places device registers in the CPU's memory address space; port I/O uses a separate I/O address space with special IN/OUT instructions.", exp:"MMIO: device registers accessed like memory (load/store). Modern CPUs and most devices use MMIO. Port I/O (x86): 64K I/O ports, accessed with IN/OUT instructions (require privilege level 0 or IOPL). Legacy devices (VGA, serial ports) use port I/O. ARM has no port I/O — only MMIO." },
{ id:483, q:"What is PCIe and its relevance to OS?", a:"PCIe (Peripheral Component Interconnect Express) is the dominant bus for connecting CPUs to high-speed peripherals (NVMe, GPUs, NICs); the OS configures PCIe device discovery and resource allocation.", exp:"OS uses ACPI/BIOS tables to discover PCIe topology. Each device has config space (vendor/device ID, BARs — Base Address Registers). OS allocates memory ranges to BARs. PCIe devices use MSI/MSI-X for interrupts (memory writes vs physical IRQ lines). lspci lists all PCIe devices." },
{ id:484, q:"What is hot-plug in PCIe context?", a:"PCIe hot-plug allows devices to be inserted and removed from a running system without power cycling, with the OS dynamically allocating and releasing resources.", exp:"Hot-plug controller generates interrupt on device insertion. OS driver detects event, reads device config space, allocates BARs, loads driver. On removal: OS driver unloads, releases resources. Critical for server hot-swap storage (NVMe, SAS) and high-availability configurations." },
{ id:485, q:"What is SR-IOV (Single Root I/O Virtualization)?", a:"SR-IOV allows a single PCIe device (NIC, HBA) to appear as multiple independent virtual devices (VFs) that can be directly assigned to VMs.", exp:"Physical Function (PF): full device. Virtual Functions (VFs): lightweight instances sharing hardware. VMs get direct hardware access via VF (no emulation overhead). IOMMU provides isolation between VFs. Used for high-performance virtualized networking. 10/25/40Gbit NICs support 64–256 VFs per port." },
{ id:486, q:"What is VFIO (Virtual Function I/O)?", a:"VFIO is a Linux framework for safe, IOMMU-protected userspace access to hardware devices, used for device passthrough to VMs.", exp:"VFIO uses IOMMU to give a device's DMA access isolated to specific memory regions. VMs can use VFIO to directly access GPUs, NICs, NVMe drives with near-native performance. QEMU/KVM uses VFIO for PCIe device passthrough. Also used by DPDK for userspace NIC drivers." },
{ id:487, q:"What is the GPU and its OS interaction?", a:"The OS manages GPU memory, schedules GPU tasks, and provides an abstraction layer (DRM/KMS) for graphics and compute workloads.", exp:"DRM (Direct Rendering Manager): kernel subsystem managing GPU access. KMS (Kernel Mode Setting): sets display resolution/refresh from kernel. Mesa (user-space OpenGL), CUDA/ROCm for compute. GPU memory management: GPUs have GDDR/HBM VRAM; kernel's DRM allocates/manages it. Multiple processes share GPU via scheduling." },
{ id:488, q:"What is KMS (Kernel Mode Setting)?", a:"KMS moves display mode setting (resolution, color depth, refresh rate) from X server user-space code to the kernel, enabling earlier graphical output and better security.", exp:"Before KMS: X server set mode by accessing video hardware directly (root required). After KMS: kernel sets mode, can show graphical splash screen early in boot, non-root user-space can use display. DRM driver implements KMS. Enables fast user switching, Wayland compositors, virtual console graphics." },
{ id:489, q:"What is Wayland vs X11?", a:"Wayland is a modern display protocol that replaces the X Window System (X11); it moves rendering into clients and the compositor, eliminating the X server middleman.", exp:"X11: 40 years old, network-transparent, all apps go through X server. Wayland: direct compositor communication, lower latency, better security (apps can't spy on each other), mandatory compositing. Adoption: major distros moving to Wayland (GNOME, KDE on Wayland). XWayland compatibility layer for X11 apps." },
{ id:490, q:"What is a display server?", a:"A display server is the OS component that manages graphical display hardware and provides an API for GUI applications to render windows.", exp:"X.org/X11: traditional, network-transparent display server on Linux. Wayland compositors (Mutter, Kwin, Weston) combine display server and compositor. macOS: Quartz Compositor. Windows: Desktop Window Manager (DWM). The display server handles input (keyboard, mouse) and allocates window surfaces." },
{ id:491, q:"What is a device tree?", a:"A device tree is a data structure describing hardware components in a system, used by embedded Linux and ARM systems where hardware isn't self-describing (unlike PCIe).", exp:"On x86: BIOS/ACPI tables describe hardware. On ARM (phones, embedded): no self-description → device tree blob (DTB) passed to kernel by bootloader. Describes: CPUs, memory, interrupts, clocks, GPIO, I2C, SPI buses. Kernel reads DTB, instantiates drivers. Stored in /boot/*.dtb." },
{ id:492, q:"What is the difference between big-endian and little-endian?", a:"Endianness describes byte order in memory: little-endian stores least significant byte first (Intel x86); big-endian stores most significant byte first (SPARC, network byte order).", exp:"0x12345678 in memory: little-endian: 78 56 34 12. Big-endian: 12 34 56 78. Network protocols use big-endian (htonl/ntohl conversion functions). x86/x86-64 and ARM (configurable, usually little-endian) use little-endian. File format portability requires explicit byte-order handling." },
{ id:493, q:"What is the OS role in handling hardware errors?", a:"The OS handles hardware errors via ACPI error handling, Machine Check Exceptions (MCE), ECC memory, and EDAC (Error Detection and Correction) frameworks.", exp:"MCE: CPU detects hardware error (memory corruption, CPU errors), raises Machine Check Exception. Kernel's mce handler logs error via /dev/mcelog or rasdaemon. ECC RAM: corrects single-bit errors silently, reports double-bit errors. EDAC: kernel framework for memory controller error reporting. SMART monitors disk health." },
{ id:494, q:"What is MCE (Machine Check Exception)?", a:"A Machine Check Exception is generated by the CPU when it detects a hardware error — memory error, cache error, bus error — that may indicate hardware failure.", exp:"The CPU sets MCE registers (MCi_STATUS, MCi_ADDR, MCi_MISC). Kernel MCE handler reads these registers. Recoverable MCE: kernel continues (UCNA — uncorrected no action). Fatal MCE: kernel panics (corrupt kernel memory). mcelog or rasdaemon logs MCE events. Indicator of hardware needing replacement." },
{ id:495, q:"What is the role of the OS in laptop battery management?", a:"The OS interacts with ACPI firmware to read battery state, manage power profiles, trigger charging, and estimate remaining time.", exp:"/sys/class/power_supply/BAT0/: capacity, status (Charging/Discharging), energy_now, energy_full. ACPI battery events trigger udev. power-supply notify change → desktop environment updates indicator. TLP (Linux), powerd, thermald optimize power. Hibernate on low battery: kernel writes RAM to disk, powers off." },
{ id:496, q:"What is suspend-to-RAM vs suspend-to-disk?", a:"Suspend-to-RAM (sleep/S3) saves system state in RAM and cuts power to most components; suspend-to-disk (hibernate/S4) writes RAM to disk and fully powers off.", exp:"S3 (suspend): fast resume (seconds), consumes small battery power (keeps RAM refreshed). S4 (hibernate): slow resume (disk read time), zero power, no data loss on battery death. Hybrid sleep: write to disk AND keep in RAM (fast resume normally, safe if battery dies). systemctl suspend/hibernate." },
{ id:497, q:"What is firmware vs BIOS vs UEFI?", a:"Firmware is software embedded in hardware; BIOS and UEFI are firmware implementations for PC platform initialization and boot.", exp:"Firmware: any software in ROM/flash on hardware devices (NIC firmware, SSD firmware, CPU microcode). BIOS: Basic I/O System, 16-bit, circa 1975, MBR boot, limited to 2TB. UEFI: modern replacement, 64-bit, GUI, GPT support, Secure Boot, network boot, extensible via modules, faster POST." },
{ id:498, q:"What is CPU microcode?", a:"CPU microcode is firmware inside the CPU that implements complex instructions and can be updated by the OS to fix bugs or security vulnerabilities.", exp:"Modern CPUs: CISC instructions decoded to micro-operations using microcode ROM. Intel/AMD release microcode updates for security vulnerabilities (Spectre, MDS). OS loads microcode update on boot (/lib/firmware/intel-ucode/). Per-CPU microcode updates: /sys/devices/system/cpu/microcode/. Critical for security." },
{ id:499, q:"What is the role of the OS scheduler in power management?", a:"The scheduler influences power consumption by choosing when to idle CPUs, consolidating work onto fewer cores, and coordinating with the CPU frequency governor.", exp:"Linux scheduler: tracks per-CPU load. With power-aware scheduling, tries to consolidate tasks on fewer CPUs (cluster scheduling) allowing other CPUs to enter deep C-states. CPU frequency governor (schedutil) scales frequency based on scheduler's load signal. Better power efficiency with fewer more-loaded cores vs many lightly-loaded." },
{ id:500, q:"What is the future of operating systems?", a:"Future OS trends include: increased security (confidential computing, formal verification), energy efficiency (heterogeneous computing, fine-grained power management), cloud-native designs (unikernels, serverless), and hardware-software co-design.", exp:"Key trends: Confidential computing (SGX, SEV-SNP for secure enclaves), Rust in OS kernels (memory safety — Linux, Windows experimenting), eBPF for programmable kernel, io_uring for async I/O, ARM dominance (Apple Silicon, AWS Graviton), heterogeneous computing (CPU+GPU+NPU), serverless/unikernels for microservices." },
// Bonus questions 501-510
{ id:501, q:"What is the Copy-on-Fork optimization in Linux?", a:"Copy-on-Fork (copy-on-write for fork) means that after fork(), parent and child share the same physical memory pages until one of them writes, at which point the OS creates a copy.", exp:"Without COW: fork() would require copying all parent memory immediately — very expensive. With COW: pages marked read-only and shared. First write triggers a page fault; OS copies the page; write completes. Makes fork() + exec() cheap since exec() discards all pages anyway (no copies ever made)." },
{ id:502, q:"What is Transparent Huge Pages (THP)?", a:"THP is a Linux kernel feature that automatically uses 2MB huge pages for anonymous memory instead of 4KB pages, without requiring application changes.", exp:"khugepaged kernel thread scans for adjacent 512 contiguous 4KB pages and collapses them into one 2MB huge page. Reduces TLB pressure. Downsides: memory waste (partial huge pages), latency spikes during collapse/split, not good for short-lived allocations. THP=madvise mode: only use THP when app explicitly requests." },
{ id:503, q:"What is memory deduplication (KSM)?", a:"Kernel Same-page Merging (KSM) is a Linux feature that finds identical memory pages across different processes and merges them into one copy-on-write shared page.", exp:"Useful for VMs: multiple VMs with same OS have identical kernel pages — KSM merges them. ksmd daemon scans pages, computes checksums, merges duplicates. Reduces physical memory needed for VM hosting. Trade-off: CPU overhead for scanning, write causes copy-on-write (latency spike). Enabled per-region via madvise(MADV_MERGEABLE)." },
{ id:504, q:"What is the role of the OS in GPU computing?", a:"The OS manages GPU device access, allocates GPU memory, handles context switching between GPU workloads, and provides APIs for compute (CUDA, OpenCL, ROCm) and graphics.", exp:"DRM/KMS for display. Compute: CUDA (NVIDIA), ROCm (AMD), oneAPI (Intel) — user-space libraries with kernel drivers. GPU scheduler: multiple processes can share GPU (time-slicing or spatial partitioning with MIG on A100). Memory: GDDR managed by GPU driver, DMA between CPU-RAM and GPU-VRAM." },
{ id:505, q:"What is NUMA topology in multi-socket servers?", a:"In multi-socket servers, each CPU socket has its own local DRAM, and access to another socket's memory goes through the inter-socket interconnect (QPI/UPI on Intel, Infinity Fabric on AMD), with higher latency.", exp:"2-socket server: 2 NUMA nodes. Access local memory: ~80ns. Access remote memory: ~120–160ns. OS-level: numactl --hardware shows topology. Linux NUMA-aware allocator: first-touch policy. Applications should be NUMA-aware: pin threads to NUMA node, allocate memory locally. lscpu, numastat for info." },
{ id:506, q:"What is the difference between SCHED_FIFO and SCHED_RR in Linux?", a:"SCHED_FIFO is a real-time scheduling policy where processes run until they block or yield (no preemption at same priority); SCHED_RR adds round-robin preemption for same-priority processes.", exp:"Both are real-time policies (priorities 1–99, above normal CFS tasks). SCHED_FIFO: a process at priority 50 runs until it blocks or yields, even if another priority-50 process is waiting. SCHED_RR: processes at same priority time-share (default quantum 100ms). Lower priority processes starve. Use with care." },
{ id:507, q:"What is the difference between wall time, CPU time, and real time in process measurement?", a:"Wall time (elapsed real time): clock time from start to end. CPU time: time actually spent on CPU. Real time (similar to wall): system clock elapsed. CPU time ≤ wall time for single-threaded; CPU time > wall time for multi-threaded.", exp:"time command: real (wall), user (user-space CPU), sys (kernel CPU). real > user+sys for I/O-bound. user+sys >> real for parallel (multiple CPUs used simultaneously). Example: 4 threads each use 10s CPU → user=40s sys=1s real=10s. Used for performance benchmarking and billing in cloud." },
{ id:508, q:"What is the difference between a kernel module and a device driver?", a:"A device driver is code that controls a specific hardware device; a kernel module is the mechanism for loading/unloading code into/from the kernel dynamically. Device drivers are typically implemented as kernel modules.", exp:"Not all kernel modules are device drivers (e.g., filesystem modules, network protocol modules). Device drivers can be compiled into the kernel (built-in) or as modules (.ko). Built-in: always present, no loading overhead. Module: loaded on demand (saves memory, easier development, can be reloaded after changes)." },
{ id:509, q:"What is the difference between mknod and device file creation?", a:"mknod creates a special file (character or block device node); modern Linux uses udev to automatically create device files in /dev based on kernel uevent notifications.", exp:"mknod /dev/mydev c 200 0 (character device, major 200, minor 0). Major number identifies the driver; minor identifies the specific device instance. Modern: drivers call device_create() which triggers uevent; udev creates /dev/mydev automatically with proper permissions. Static /dev (pre-udev) used /lib/dev.d/ files." },
{ id:510, q:"What is the relationship between Linux kernel versions and LTS support?", a:"Linux kernel releases include regular releases and Long Term Support (LTS) versions maintained for 2–6 years with backported security fixes, used by embedded systems, Android, and enterprise Linux distributions.", exp:"Regular releases: ~9–10 weeks cycle, maintained for ~3 months. LTS versions: selected by kernel maintainers (e.g., 5.15, 6.1, 6.6), maintained 2–6 years. Android uses a specific LTS kernel for several device generations. RHEL/Ubuntu LTS use heavily patched LTS kernels. kernel.org/releases shows current maintained versions." },
];

